QT_ISI(12,{"1479":["(Dan tidak ada) huruf min di sini zaidah (suatu binatang melata pun di bumi) yaitu hewan yang melata di atas bumi (melainkan Allahlah yang memberi rezekinya) Dialah yang menanggung rezekinya sebagai karunia daripada-Nya (dan Dia mengetahui tempat berdiam binatang itu) tempat hidupnya di dunia atau pada tulang sulbi (dan tempat penyimpanannya) sesudah mati atau di dalam rahim. (Semuanya) yang telah disebutkan itu (tertulis dalam kitab yang nyata) kitab yang jelas, yaitu Lohmahfuz.",[["۞ وَمَا","Dan tidak"],["مِن","sebarang"],["دَآبَّةٍۢ","makhluk bergerak"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["إِلَّا","tetapi"],["عَلَى","pada"],["ٱللَّهِ","Allah"],["رِزْقُهَا","(adalah) peruntukannya"],["وَيَعْلَمُ","Dan Dia tahu"],["مُسْتَقَرَّهَا","tempat kediamannya"],["وَمُسْتَوْدَعَهَا ۚ","dan tempat penyimpanannya"],["كُلٌّۭ","Semua"],["فِى","(berada) dalam"],["كِتَـٰبٍۢ","sebuah Rekod"],["مُّبِينٍۢ","yang nyata"]]],"1480":["(Dan Dialah yang menciptakan langit dan bumi dalam enam hari) yang permulaannya adalah hari Ahad dan berakhir pada hari Jumat (dan adalah Arasy-Nya) sebelum diciptakan langit dan bumi (di atas air) yaitu berada di atas angin (agar Dia menguji kalian) lafal liyabluwakum berta'alluq kepada lafal khalaqa artinya, Allah menciptakan langit dan bumi beserta isinya yaitu berupa manfaat-manfaat dan maslahat-maslahat bagi kalian untuk menguji kalian (siapakah di antara kalian yang lebih baik amalnya) artinya yang lebih taat kepada Allah (dan jika kamu berkata) hai Muhammad, kepada penduduk Mekah (\"Sesungguhnya kalian akan dibangkitkan sesudah mati,\" niscaya orang-orang yang kafir itu akan berkata, \"Tiada lain) tidak lain (ini) yakni Alquran yang menceritakan adanya hari berbangkit seperti yang telah engkau katakan itu (hanyalah sihir yang nyata\") sihir yang jelas. Menurut qiraat dibaca saahirun bukannya sihrun; sedangkan yang diisyaratkan oleh musyar ilaih adalah Nabi Muhammad saw. bukannya Alquran.",[["وَهُوَ","Dan Dia"],["ٱلَّذِى","(ialah) Yang"],["خَلَقَ","dicipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["فِى","dalam"],["سِتَّةِ","enam"],["أَيَّامٍۢ","zaman"],["وَكَانَ","dan takhta-Nya adalah"],["عَرْشُهُۥ","dan takhta-Nya adalah"],["عَلَى","pada"],["ٱلْمَآءِ","air itu"],["لِيَبْلُوَكُمْ","supaya Dia menguji [kamu]"],["أَيُّكُمْ","yang mana antara kamu"],["أَحْسَنُ","(adalah) terbaik"],["عَمَلًۭا ۗ","(dalam) perbuatan"],["وَلَئِن","Tetapi jika"],["قُلْتَ","kamu cakap"],["إِنَّكُم","Sesungguhnya kamu"],["مَّبْعُوثُونَ","(akan) dibangkitkan"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["ٱلْمَوْتِ","[the] kematian"],["لَيَقُولَنَّ","pasti akan berkata"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["إِنْ","Ini bukan"],["هَـٰذَآ","Ini bukan"],["إِلَّا","tetapi"],["سِحْرٌۭ","sihir"],["مُّبِينٌۭ","yang nyata"]]],"1481":["(Dan sesungguhnya jika Kami undurkan azab dari mereka sampai pada) datangnya (suatu waktu) beberapa waktu (yang ditentukan, niscaya mereka akan berkata) yang dimaksud dari keterangan ini adalah cemoohan (\"Apakah yang menghalanginya?\") apakah gerangan yang mencegah turunnya azab. Sebagai sanggahannya Allah berfirman: (Ingatlah, di waktu azab itu datang kepada mereka tidaklah dapat dipalingkan) tidak dapat ditahan lagi (dari mereka dan mereka diliputi) dikepung (oleh azab yang dahulunya mereka selalu memperolok-olokkannya) yang dimaksud adalah mereka memperolok-olokkan azab itu sebelumnya.",[["وَلَئِنْ","Dan jika"],["أَخَّرْنَا","Kita tangguhkan"],["عَنْهُمُ","daripada mereka"],["ٱلْعَذَابَ","azab"],["إِلَىٰٓ","bagi"],["أُمَّةٍۢ","suatu masa"],["مَّعْدُودَةٍۢ","ditentukan"],["لَّيَقُولُنَّ","mereka pasti akan berkata"],["مَا","Apa"],["يَحْبِسُهُۥٓ ۗ","menahannya"],["أَلَا","Tidak syak lagi"],["يَوْمَ","(Pada) hari itu"],["يَأْتِيهِمْ","ia datang kepada mereka"],["لَيْسَ","tidak"],["مَصْرُوفًا","(akan) dielakkan"],["عَنْهُمْ","daripada mereka"],["وَحَاقَ","dan akan mengelilingi"],["بِهِم","mereka"],["مَّا","apa"],["كَانُوا۟","mereka pernah (untuk)"],["بِهِۦ","mengejek [itu]"],["يَسْتَهْزِءُونَ","mengejek [itu]"]]],"1482":["(Dan jika Kami rasakan kepada manusia) yang kafir (suatu rahmat dari Kami) yaitu berupa kekayaan dan kesehatan (kemudian rahmat itu Kami cabut daripadanya pastilah dia menjadi putus asa) merasa putus asa dari rahmat Allah (lagi tidak berterima kasih) sangat mengingkari-Nya.",[["وَلَئِنْ","Dan jika"],["أَذَقْنَا","Kami memberi manusia rasa"],["ٱلْإِنسَـٰنَ","Kami memberi manusia rasa"],["مِنَّا","(dari) Rahmat dari Kami"],["رَحْمَةًۭ","(dari) Rahmat dari Kami"],["ثُمَّ","kemudian"],["نَزَعْنَـٰهَا","Kami menarik baliknya"],["مِنْهُ","daripada dia"],["إِنَّهُۥ","memang dia"],["لَيَـُٔوسٌۭ","(adalah) putus asa"],["كَفُورٌۭ","(dan) tidak bersyukur"]]],"1483":["(Dan jika kami rasakan kepadanya kebahagiaan sesudah bencana) kemiskinan dan kesengsaraan (yang menimpanya, niscaya dia akan berkata, \"Telah hilang keburukan-keburukan itu) yaitu bencana-bencana tersebut (dariku.\") akan tetapi ia tidak mempunyai perasaan bahwa kebahagiaan itu bakal lenyap darinya dan pula ia tidak mensyukurinya (Sesungguhnya dia sangat gembira) meluap (lagi bangga) terhadap manusia atas apa yang diberikan kepadanya.",[["وَلَئِنْ","Tetapi jika"],["أَذَقْنَـٰهُ","Kita bagi dia rasa"],["نَعْمَآءَ","(dari) nikmat"],["بَعْدَ","selepas"],["ضَرَّآءَ","kesusahan"],["مَسَّتْهُ","(telah) menyentuhnya"],["لَيَقُولَنَّ","pasti, dia akan berkata"],["ذَهَبَ","Telah pergi"],["ٱلسَّيِّـَٔاتُ","kejahatan"],["عَنِّىٓ ۚ","daripada aku"],["إِنَّهُۥ","Sesungguhnya dia"],["لَفَرِحٌۭ","(adalah) gembira"],["فَخُورٌ","(dan) bermegah-megahan"]]],"1484":["(Kecuali) tetapi (orang-orang yang sabar) terhadap bencana (dan mengerjakan amal-amal saleh) sewaktu diberi kebahagiaan (mereka itu beroleh ampunan dan pahala yang besar) yaitu surga.",[["إِلَّا","Kecuali"],["ٱلَّذِينَ","orang yang"],["صَبَرُوا۟","(adalah) sabar"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","perbuatan baik itu"],["أُو۟لَـٰٓئِكَ","mereka"],["لَهُم","bagi mereka"],["مَّغْفِرَةٌۭ","(akan) pengampunan"],["وَأَجْرٌۭ","dan ganjaran"],["كَبِيرٌۭ","yang besar"]]],"1485":["(Maka boleh jadi kamu) hai Muhammad (meninggalkan sebagian dari apa yang diwahyukan kepadamu) sehingga kamu tidak menyampaikannya kepada mereka karena mereka menganggap remeh terhadapnya (dan sempit karenanya dadamu) sewaktu engkau membacakannya kepada mereka, karena khawatir bahwa (mereka akan mengatakan, \"Mengapa tidak) bagaimana tidak (diturunkan kepadanya perbendaharaan atau datang bersama-sama dengan dia satu malaikat?\") yang membenarkannya sesuai dengan apa yang kami minta. (Sesungguhnya kamu hanyalah seorang pemberi peringatan) tugasmu hanyalah menyampaikan bukannya mendatangkan apa yang mereka kehendaki. (Dan Allah Pemelihara segala sesuatu) yakni Dia hafal kesemuanya, maka Dia membalas mereka karenanya.",[["فَلَعَلَّكَ","Kemudian mungkin kamu"],["تَارِكٌۢ","(boleh) berputus asa"],["بَعْضَ","bahagian"],["مَا","apa"],["يُوحَىٰٓ","didedahkan"],["إِلَيْكَ","kepada kamu"],["وَضَآئِقٌۢ","dan tertekan"],["بِهِۦ","olehnya"],["صَدْرُكَ","payudara kamu"],["أَن","kerana"],["يَقُولُوا۟","mereka berkata"],["لَوْلَآ","kenapa tidak"],["أُنزِلَ","diturunkan"],["عَلَيْهِ","baginya"],["كَنزٌ","harta karun"],["أَوْ","atau"],["جَآءَ","telah datang"],["مَعَهُۥ","dengan dia"],["مَلَكٌ ۚ","seorang Malaikat"],["إِنَّمَآ","Hanya"],["أَنتَ","kamu"],["نَذِيرٌۭ ۚ","(adalah) pemberi amaran"],["وَٱللَّهُ","Dan Allah"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["وَكِيلٌ","seorang Penjaga"]]],"1486":["(Bahkan) akan tetapi apakah (mereka mengatakan, \"Muhammad telah membuat-buatnya\") yakni Alquran itu (Katakanlah, \"Kalau demikian, maka datangkanlah sepuluh surah-surah semisal dengannya) dalam masalah kefasihan bahasa dan ketinggian paramasastranya (yang dibuat-buat) karena sesungguhnya kalian sama denganku adalah orang-orang Arab yang fasih dalam berbahasa. Allah swt. menantang mereka untuk pertama kalinya supaya mereka mendatangkan sepuluh surah, kemudian pada tantangan yang berikutnya cukup hanya dengan satu surah saja (dan panggillah orang-orang yang kalian sanggup memanggilnya selain Allah) selain dari Allah (jika kalian memang orang-orang yang benar.\") di dalam tuduhan kalian yang menyatakan, bahwa Alquran itu hanyalah buat-buatan belaka.",[["أَمْ","Atau"],["يَقُولُونَ","mereka berkata"],["افْتَرَاهُ ۖ","Dia telah mengada-adakannya"],["قُلْ","Katakanlah"],["فَأْتُوا۟","Kemudian bawa"],["بِعَشْرِ","sepuluh"],["سُوَرٍۢ","Surah"],["مِّثْلِهِۦ","suka"],["مُفْتَرَيَـٰتٍۢ","direka-reka"],["وَٱدْعُوا۟","dan panggil"],["مَنِ","sesiapa sahaja"],["ٱسْتَطَعْتُم","kamu boleh"],["مِّن","selain Allah"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"1487":["(Jika) bila (mereka yang kalian seru tidak menerima seruan/ajakan kalian) yaitu orang-orang yang kalian ajak untuk membantu kalian (maka ketahuilah) khithab atau pembicaraan ditujukan kepada orang-orang musyrik (sesungguhnya Alquran itu diturunkan) berdasarkan (ilmu Allah) dan bukannya buat-buatan yang dilakukan terhadap-Nya (dan bahwasanya) an di sini adalah bentuk takhfif daripada anna (tidak ada Tuhan selain Dia, maka maukah kalian berserah diri kepada-Nya) sesudah adanya hujah-hujah yang pasti ini. Makna yang dimaksud ialah hendaknya kalian masuk Islam.",[["فَإِلَّمْ","Kemudian jika tidak"],["يَسْتَجِيبُوا۟","mereka bertindak balas"],["لَكُمْ","kepada kamu"],["فَٱعْلَمُوٓا۟","maka ketahuilah"],["أَنَّمَآ","bahawa"],["أُنزِلَ","ia diturunkan"],["بِعِلْمِ","dengan ilmu Allah"],["ٱللَّهِ","dengan ilmu Allah"],["وَأَن","dan bahawa"],["لَّآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ ۖ","Dia"],["فَهَلْ","Kemudian, akan"],["أَنتُم","kamu"],["مُّسْلِمُونَ","(menjadi) orang Islam"]]],"1488":["(Barang siapa yang menghendaki kehidupan dunia dan perhiasannya) seumpamanya ia tetap bersikeras dalam kemusyrikannya. Menurut suatu pendapat ayat ini ditujukan kepada orang-orang yang berbuat ria atau pamer (niscaya Kami berikan kepada mereka balasan pekerjaannya dengan sempurna) pembalasan dari amal baik yang telah dikerjakannya, seperti sedekah dan bersilaturahmi (di dunia) umpamanya Kami meluaskan lapangan rezeki mereka (dan mereka di dalamnya) yakni di dunia (tidak dirugikan) artinya tidak akan dikurangi sedikit pun balasannya.",[["مَن","sesiapa sahaja"],["كَانَ","sesiapa sahaja"],["يُرِيدُ","keinginan"],["ٱلْحَيَوٰةَ","kehidupan"],["ٱلدُّنْيَا","dunia"],["وَزِينَتَهَا","dan perhiasannya"],["نُوَفِّ","Kami akan membayar balik sepenuhnya"],["إِلَيْهِمْ","kepada mereka"],["أَعْمَـٰلَهُمْ","(untuk) perbuatan mereka"],["فِيهَا","di dalamnya"],["وَهُمْ","dan mereka"],["فِيهَا","di dalamnya"],["لَا","tidak akan berkurangan"],["يُبْخَسُونَ","tidak akan berkurangan"]]],"1489":["(Itulah orang-orang yang tidak memperoleh di akhirat kecuali neraka dan lenyaplah) dileburlah (apa yang telah mereka usahakan) itu (di akhirat nanti) sehingga mereka tidak mempunyai pahala lagi (dan sia-sialah apa yang telah mereka kerjakan.)",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلَّذِينَ","(adalah) orang-orang yang"],["لَيْسَ","(adalah) tidak"],["لَهُمْ","bagi mereka"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["إِلَّا","kecuali"],["ٱلنَّارُ ۖ","neraka"],["وَحَبِطَ","Dan (telah) pergi dengan sia-sia"],["مَا","apa"],["صَنَعُوا۟","mereka lakukan"],["فِيهَا","di dalamnya"],["وَبَـٰطِلٌۭ","dan (adalah) tidak bernilai"],["مَّا","apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَعْمَلُونَ","lakukan"]]],"1490":["(Apakah orang yang mempunyai bukti) penjelasan (dari Rabbnya) yaitu Nabi saw. atau orang-orang mukmin yang dimaksud dengan bukti adalah Alquran (dan diikuti pula) dipanuti (oleh saksi) baginya yang membenarkannya (dari-Nya) yaitu dari Allah, yang dimaksud adalah malaikat Jibril (dan sebelumnya) sebelum Alquran (telah ada kitab Musa) yaitu kitab Taurat yang menyaksikan kebenaran Alquran pula (yang menjadi pedoman dan rahmat?) menjadi kata keterangan dari Alquran. Apakah keadaannya sama dengan orang-orang yang tidak demikian keadaannya? Tentu saja tidak (mereka itu) yakni orang-orang yang mempunyai bukti (beriman kepadanya) kepada Alquran, maka bagi mereka surga. (Dan barang siapa di antara golongan yang bersekutu ingkar kepada Alquran) semua orang-orang kafir (maka nerakalah tempat yang diancamkan baginya, karena itu janganlah kamu ragu-ragu) menaruh syak (kepadanya) kepada Alquran (Sesungguhnya Alquran itu benar-benar dari Rabbmu tetapi kebanyakan manusia) penduduk Mekah (tidak beriman).",[["أَفَمَن","Maka adakah dia yang"],["كَانَ","ialah"],["عَلَىٰ","pada"],["بَيِّنَةٍۢ","bukti yang jelas"],["مِّن","daripada"],["رَّبِّهِۦ","Tuhannya"],["وَيَتْلُوهُ","dan membacanya"],["شَاهِدٌۭ","seorang saksi"],["مِّنْهُ","daripadaNya"],["وَمِن","dan sebelum itu"],["قَبْلِهِۦ","dan sebelum itu"],["كِتَـٰبُ","(adalah) sebuah Kitab"],["مُوسَىٰٓ","(dari) Musa"],["إِمَامًۭا","(sebagai) panduan"],["وَرَحْمَةً ۚ","dan (sebagai) rahmat"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["يُؤْمِنُونَ","beriman"],["بِهِۦ ۚ","di dalamnya"],["وَمَن","Tetapi siapa pun"],["يَكْفُرْ","tidak beriman"],["بِهِۦ","di dalamnya"],["مِنَ","antara"],["ٱلْأَحْزَابِ","mazhab-mazhab"],["فَٱلنَّارُ","kemudian api"],["مَوْعِدُهُۥ ۚ","(akan menjadi) tempat (pertemuan) yang dijanjikannya"],["فَلَا","Jadi (jangan)"],["تَكُ","jadilah"],["فِى","dalam"],["مِرْيَةٍۢ","keraguan"],["مِّنْهُ ۚ","mengenainya"],["إِنَّهُ","Sesungguhnya, ia"],["ٱلْحَقُّ","(adalah) kebenaran"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَ","kebanyakannya"],["ٱلنَّاسِ","(daripada) rakyat"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"]]],"1491":["(Dan siapakah) tidak ada seorang pun (yang lebih lalim daripada orang yang membuat-buat dusta terhadap Allah?) dengan menisbatkan sekutu terhadap-Nya dan menganggapnya mempunyai anak. (Mereka itu akan dihadapkan kepada Rabb mereka) kelak di hari kiamat di antara semua makhluk-Nya (dan para saksi akan berkata) lafal asyhaad adalah bentuk jamak dari lafal syahiid yang artinya saksi. Mereka adalah para malaikat; mereka memberikan kesaksian, bahwa para rasul telah menyampaikan risalahnya, adapun orang-orang kafir mereka cap sebagai pendusta (\"Orang-orang inilah yang telah berdusta terhadap Rabb mereka.\" Ingatlah, kutukan Allah dilimpahkan atas orang-orang yang lalim) yaitu orang-orang musyrik.",[["وَمَنْ","Dan siapa"],["أَظْلَمُ","(adalah) lebih zalim"],["مِمَّنِ","daripada (dia) yang"],["ٱفْتَرَىٰ","mencipta"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["كَذِبًا ۚ","satu pembohongan"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["يُعْرَضُونَ","akan dibentangkan"],["عَلَىٰ","sebelum"],["رَبِّهِمْ","Tuhan mereka"],["وَيَقُولُ","dan akan berkata"],["ٱلْأَشْهَـٰدُ","para saksi"],["هَـٰٓؤُلَآءِ","Ini (adalah)"],["ٱلَّذِينَ","orang yang"],["كَذَبُوا۟","berbohong"],["عَلَىٰ","terhadap"],["رَبِّهِمْ ۚ","Tuhan mereka"],["أَلَا","Tidak syak lagi"],["لَعْنَةُ","(Laknat) Allah"],["ٱللَّهِ","(Laknat) Allah"],["عَلَى","(berada) di atas"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"1492":["(Yaitu orang-orang yang menghalangi manusia dari jalan Allah) dari agama Islam (dan menghendaki supaya jalan itu) (bengkok) tidak lurus (Dan mereka terhadap hari kemudian adalah) lafal hum kedua mengukuhkan makna lafal hum pertama (orang-orang yang tidak percaya).",[["ٱلَّذِينَ","Orang yang"],["يَصُدُّونَ","menghalang"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["وَيَبْغُونَهَا","dan carilah (ke dalamnya)."],["عِوَجًۭا","kebengkokan"],["وَهُم","sedangkan mereka"],["بِٱلْـَٔاخِرَةِ","di akhirat"],["هُمْ","[mereka]"],["كَـٰفِرُونَ","(adalah) orang-orang kafir"]]],"1493":["(Orang-orang itu tidak mampu menghalang-halangi) Allah (di bumi ini dan sekali-kali tidak adalah bagi mereka selain Allah) selain-Nya (yang menolong mereka) maksudnya para penolong yang dapat mencegah azab Allah terhadap mereka. (Siksaan itu dilipatgandakan kepada mereka) karena mereka menyesatkan orang lain. (Mereka selalu tidak dapat mendengar) kebenaran (dan mereka selalu tidak melihat) kebenaran itu karena kebencian mereka yang sangat terhadap kebenaran itu sehingga digambarkan seolah-olah mereka tidak mampu untuk mendengar dan melihatnya.",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["لَمْ","tidak"],["يَكُونُوا۟","akan menjadi"],["مُعْجِزِينَ","(dapat) melarikan diri"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَمَا","dan bukan"],["كَانَ","ialah"],["لَهُم","bagi mereka"],["مِّن","selain"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["مِنْ","sebarang"],["أَوْلِيَآءَ ۘ","pelindung"],["يُضَـٰعَفُ","Dan akan digandakan"],["لَهُمُ","bagi mereka"],["ٱلْعَذَابُ ۚ","azab"],["مَا","Tidak"],["كَانُوا۟","mereka adalah"],["يَسْتَطِيعُونَ","mampu"],["ٱلسَّمْعَ","(untuk) mendengar"],["وَمَا","dan bukan"],["كَانُوا۟","mereka pernah (untuk)"],["يُبْصِرُونَ","lihat"]]],"1494":["(Mereka itulah orang-orang yang merugikan dirinya sendiri) karena mereka menjerumuskan dirinya ke dalam neraka yang abadi (dan lenyaplah) terhapuslah (dari mereka apa yang selalu mereka ada-adakan) terhadap Allah, yaitu tuduhan mereka yang menyekutukan Allah.",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلَّذِينَ","(adalah) orang-orang yang"],["خَسِرُوٓا۟","(telah) kalah"],["أَنفُسَهُمْ","jiwa mereka"],["وَضَلَّ","dan hilang"],["عَنْهُم","daripada mereka"],["مَّا","(ialah) apa"],["كَانُوا۟","mereka gunakan"],["يَفْتَرُونَ","(untuk) mencipta"]]],"1495":["(Pasti) sungguh (mereka itu di akhirat menjadi orang-orang yang paling merugi).",[["لَا","Tidak"],["جَرَمَ","keraguan"],["أَنَّهُمْ","bahawa mereka"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["هُمُ","[mereka]"],["ٱلْأَخْسَرُونَ","(akan menjadi) orang-orang yang paling rugi"]]],"1496":["(Sesungguhnya orang-orang yang beriman dan mengerjakan amal-amal saleh dan merendahkan diri) merasa tenang dan aman, atau kembali (kepada Rabb mereka, mereka itu adalah penghuni-penghuni surga; mereka kekal di dalamnya).",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","perbuatan baik"],["وَأَخْبَتُوٓا۟","dan merendahkan diri"],["إِلَىٰ","sebelum"],["رَبِّهِمْ","Tuhan mereka"],["أُو۟لَـٰٓئِكَ","mereka"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلْجَنَّةِ ۖ","(dari) Syurga"],["هُمْ","mereka"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","(akan) kekal selama-lamanya"]]],"1497":["(Perumpamaan) gambaran (kedua golongan itu) yakni orang-orang kafir dan orang-orang mukmin (seperti orang buta dan tuli) ini perumpamaan orang kafir (dengan orang yang dapat melihat dan dapat mendengar) ini perumpamaan orang mukmin. (Adakah kedua golongan itu sama keadaan dan sifatnya?) Tentu saja tidak. (Maka tidakkah kalian mengambil pelajaran) lafal tadzakkaruuna asalnya tatadzakkaruuna, kemudian huruf ta asal diidgamkan kepada huruf dzal sehingga jadilah tadzakkaruuna, artinya sama dengan lafal tatta'izhuuna, yaitu mengambil pelajaran.",[["۞ مَثَلُ","(The) contoh"],["ٱلْفَرِيقَيْنِ","(dari) dua pihak"],["كَٱلْأَعْمَىٰ","(adalah) seperti orang buta"],["وَٱلْأَصَمِّ","dan orang pekak"],["وَٱلْبَصِيرِ","dan pelihat"],["وَٱلسَّمِيعِ ۚ","dan pendengar"],["هَلْ","Adakah"],["يَسْتَوِيَانِ","mereka sama"],["مَثَلًا ۚ","(dalam) perbandingan"],["أَفَلَا","Kemudian, tidak akan"],["تَذَكَّرُونَ","kamu ambil iktibar"]]],"1498":["(Dan sesungguhnya Kami telah mengutus Nuh kepada kaumnya, ia berkata, \"Sesungguhnya aku) bahwa aku. Menurut suatu qiraat lafal innii dengan memperkirakan adanya makna al-qaul yang artinya, dia berkata (adalah pemberi peringatan yang nyata bagi kalian) yakni jelas peringatannya.",[["وَلَقَدْ","Dan sesungguhnya"],["أَرْسَلْنَا","Kami utus"],["نُوحًا","Nuh"],["إِلَىٰ","kepada"],["قَوْمِهِۦٓ","umatnya"],["إِنِّى","Memang aku"],["لَكُمْ","kepada kamu"],["نَذِيرٌۭ","seorang pemberi amaran"],["مُّبِينٌ","yang nyata"]]],"1499":["(Agar) supaya (kalian jangan menyembah selain Allah. Sesungguhnya aku takut kalian) jika kalian menyembah selain-Nya (akan ditimpa azab pada hari yang sangat menyakitkan.\") azab yang menyakitkan di dunia dan di akhirat.",[["أَن","Itu"],["لَّا","jangan"],["تَعْبُدُوٓا۟","ibadah"],["إِلَّا","kecuali"],["ٱللَّهَ ۖ","Allah"],["إِنِّىٓ","Sesungguhnya aku"],["أَخَافُ","[Aku] takut"],["عَلَيْكُمْ","bagi kamu"],["عَذَابَ","azab"],["يَوْمٍ","(dari) sehari"],["أَلِيمٍۢ","yang pedih"]]],"1500":["(Maka berkatalah pemimpin-pemimpin yang kafir dari kaumnya,) mereka adalah terdiri dari orang-orang terhormat kaumnya (\"Kami tidak melihat kamu melainkan sebagai manusia biasa seperti kami) tidak ada kelebihan bagimu atas diri kami (dan kami tidak melihat orang-orang yang mengikuti kamu, melainkan orang-orang yang hina-dina di antara kami) yaitu orang-orang yang rendah di antara kami, seperti tukang tambal pakaian dan tukang sol sepatu (yang lekas percaya saja) dapat dibaca baadiya dan baadia yang artinya, mereka lekas percaya kepadamu tanpa berpikir lebih matang lagi. Lafal ini dinashabkan karena menjadi zharaf yang artinya, mereka terus percaya dengan begitu saja (dan kami tidak melihat kalian memiliki suatu kelebihan apa pun atas kami) sehingga karena kelebihan itulah kalian berhak untuk diikuti daripada kami (bahkan kami yakin bahwa kalian adalah orang-orang yang dusta\") dalam pengakuan risalah yang kalian bawa. Dalam hal ini mereka mengikut sertakan sebutan Nabi Nuh beserta kaum yang mengikutinya.",[["فَقَالَ","Begitu kata"],["ٱلْمَلَأُ","ketua-ketua"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["مِن","daripada"],["قَوْمِهِۦ","umatnya"],["مَا","Tidak"],["نَرَىٰكَ","kita jumpa kamu"],["إِلَّا","tetapi"],["بَشَرًۭا","seorang lelaki"],["مِّثْلَنَا","seperti kita"],["وَمَا","dan bukan"],["نَرَىٰكَ","kita jumpa kamu"],["ٱتَّبَعَكَ","mengikuti [kamu]"],["إِلَّا","kecuali"],["ٱلَّذِينَ","orang yang"],["هُمْ","[mereka]"],["أَرَاذِلُنَا","(adalah) yang paling rendah di antara kita"],["بَادِىَ","tidak matang pada pendapat"],["ٱلرَّأْىِ","tidak matang pada pendapat"],["وَمَا","Dan tidak"],["نَرَىٰ","kita nampak"],["لَكُمْ","dalam kamu"],["عَلَيْنَا","atas kita"],["مِن","sebarang"],["فَضْلٍۭ","merit"],["بَلْ","tidak"],["نَظُنُّكُمْ","kami fikir kamu"],["كَـٰذِبِينَ","(adalah) pembohong"]]],"1501":["(Berkata Nuh, \"Hai kaumku! Bagaimana pikiranmu) coba katakan kepadaku (jika aku ada mempunyai bukti yang nyata) penjelasan yang nyata (dari Rabbku dan diberi-Nya aku rahmat) kenabian (dari sisi-Nya tetapi rahmat itu disamarkan) disembunyikan (bagi kalian) dan menurut suatu qiraat dibaca fa`amiyat (apa akan kami paksakan kalian menerimanya) artinya apakah kami harus memaksakan kalian untuk menerimanya (padahal kalian tiada menyukainya?\") tidak mampu untuk melakukan hal tersebut.",[["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["أَرَءَيْتُمْ","Adakah kamu melihat"],["إِن","jika"],["كُنتُ","aku pernah"],["عَلَىٰ","pada"],["بَيِّنَةٍۢ","(the) bukti yang jelas"],["مِّن","daripada"],["رَّبِّى","Tuhanku"],["وَءَاتَىٰنِى","sedangkan Dia telah memberikan kepadaku"],["رَحْمَةًۭ","belas kasihan"],["مِّنْ","daripada"],["عِندِهِۦ","dirinya sendiri"],["فَعُمِّيَتْ","tetapi (ia) telah dikaburkan"],["عَلَيْكُمْ","daripada kamu"],["أَنُلْزِمُكُمُوهَا","patutkah Kami paksa kamu (menerima)nya"],["وَأَنتُمْ","semasa kamu (ada)"],["لَهَا","menolaknya"],["كَـٰرِهُونَ","menolaknya"]]],"1502":["(Dan dia berkata, \"Hai kaumku! Aku tiada meminta kepada kalian sebagai upah bagi seruanku) di dalam menyampaikan risalahku (harta benda) yang kalian berikan kepadaku sebagai imbalannya (tiada lain) (upahku) pahalaku (hanyalah dari Allah dan aku sekali-kali tidak akan mengusir orang-orang yang telah beriman) seperti apa yang kalian perintahkan supaya aku melakukannya. (Sesungguhnya mereka pasti akan bertemu dengan Rabbnya) melalui hari berbangkit kemudian Allah membalas mereka dan menghukum orang-orang yang menyakiti dan mengusir orang-orang yang beriman (tetapi aku memandang kalian suatu kaum yang tidak mengetahui.\") akibat dari perbuatan kalian yang demikian itu.",[["وَيَـٰقَوْمِ","Dan wahai kaumku"],["لَآ","tidak"],["أَسْـَٔلُكُمْ","Aku bertanya (dari) kamu"],["عَلَيْهِ","baginya"],["مَالًا ۖ","sebarang kekayaan"],["إِنْ","Tidak"],["أَجْرِىَ","(ialah) pahala aku"],["إِلَّا","kecuali"],["عَلَى","daripada"],["ٱللَّهِ ۚ","Allah"],["وَمَآ","Dan tidak"],["أَنَا۠","aku"],["بِطَارِدِ","akan menghalau"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوٓا۟ ۚ","beriman"],["إِنَّهُم","Sesungguhnya mereka"],["مُّلَـٰقُوا۟","(akan) bermesyuarat"],["رَبِّهِمْ","Tuhan mereka"],["وَلَـٰكِنِّىٓ","tapi aku"],["أَرَىٰكُمْ","jumpa kamu"],["قَوْمًۭا","(adalah) suatu kaum"],["تَجْهَلُونَ","jahil"]]],"1503":["(Dan dia berkata, \"Hai kaumku! Siapakah yang akan menolongku) yang dapat membentengi diriku (dari Allah) dari azab-Nya (jika aku mengusir mereka) orang-orang yang beriman kepadaku, tentu saja tidak ada seorang penolong pun. (Maka tidakkah) mengapa tidak (kalian mengambil pelajaran) lafal tadzakkaruuna asalnya adalah tatadzakkaruuna, kemudian huruf ta asal diidgamkan kepada dzal sehingga jadilah tadzdzakkaruuna, artinya sama dengan tatta`izhuuna, yaitu mengambil pelajaran.",[["وَيَـٰقَوْمِ","Dan wahai kaumku"],["مَن","Siapa"],["يَنصُرُنِى","akan membantu aku"],["مِنَ","terhadap"],["ٱللَّهِ","Allah"],["إِن","jika"],["طَرَدتُّهُمْ ۚ","Aku menghalau mereka"],["أَفَلَا","Kemudian, tidak akan"],["تَذَكَّرُونَ","kamu ambil iktibar"]]],"1504":["(Dan aku tidak mengatakan kepada kalian, bahwa, 'Aku mempunyai gudang-gudang rezeki dan kekayaan dari Allah dan tiada pula) aku (mengetahui yang gaib dan tidak pula aku mengatakan bahwa sesungguhnya aku adalah malaikat.') akan tetapi sesungguhnya aku adalah manusia biasa sama dengan kalian (dan tidak juga aku mengatakan kepada orang-orang yang dipandang hina) dipandang remeh (oleh penglihatan kalian, \"Sekali-kali Allah tidak akan mendatangkan kebaikan kepada mereka.\" Allah lebih mengetahui apa yang ada pada diri mereka) yang terpendam di dalam kalbu mereka (sesungguhnya aku kalau begitu) maksudnya jika aku mengatakan demikian (benar-benar termasuk orang-orang yang lalim).",[["وَلَآ","Dan tidak"],["أَقُولُ","aku cakap"],["لَكُمْ","kepada kamu"],["عِندِى","(itu) dengan aku"],["خَزَآئِنُ","(adalah) khazanah"],["ٱللَّهِ","(milik) Allah"],["وَلَآ","dan bukan"],["أَعْلَمُ","aku tahu"],["ٱلْغَيْبَ","yang ghaib"],["وَلَآ","dan bukan"],["أَقُولُ","aku cakap"],["إِنِّى","bahawa aku"],["مَلَكٌۭ","seorang Malaikat"],["وَلَآ","dan bukan"],["أَقُولُ","aku cakap"],["لِلَّذِينَ","untuk mereka yang"],["تَزْدَرِىٓ","memandang rendah"],["أَعْيُنُكُمْ","mata kamu"],["لَن","tidak pernah"],["يُؤْتِيَهُمُ","adakah Allah akan memberi mereka"],["ٱللَّهُ","adakah Allah akan memberi mereka"],["خَيْرًا ۖ","apa-apa kebaikan"],["ٱللَّهُ","Allah"],["أَعْلَمُ","lebih tahu"],["بِمَا","apa"],["فِىٓ","(berada) dalam"],["أَنفُسِهِمْ  ۖ","jiwa mereka"],["إِنِّىٓ","Sesungguhnya aku"],["إِذًۭا","kemudian"],["لَّمِنَ","(akan) pasti daripada"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"1505":["(Mereka berkata, \"Hai Nuh! Sesungguhnya kamu telah berbantah dengan kami) telah memusuhi kami (dan kamu memperpanjang bantahanmu terhadap kami, maka datangkanlah kepada kami apa yang kamu ancamkan kepada kami) yaitu azab (jika kamu termasuk orang-orang yang benar\") di dalam ancaman yang kamu katakan itu.",[["قَالُوا۟","Mereka berkata"],["يَـٰنُوحُ","Wahai Nuh"],["قَدْ","Sesungguhnya"],["جَـٰدَلْتَنَا","kamu berselisih dengan kami"],["فَأَكْثَرْتَ","dan kamu (telah) kerap"],["جِدَٰلَنَا","(dalam) berselisih dengan kami"],["فَأْتِنَا","Jadi bawa kami"],["بِمَا","apa"],["تَعِدُنَآ","kamu mengancam kami (dengan)"],["إِن","jika"],["كُنتَ","kamu"],["مِنَ","daripada"],["ٱلصَّـٰدِقِينَ","yang benar"]]],"1506":["(Nuh menjawab, \"Hanyalah Allah yang akan mendatangkan azab itu kepada kalian jika Dia menghendaki) supaya azab itu disegerakan terhadap kalian karena sesungguhnya urusan penurunan azab itu kembali kepada-Nya (dan kalian sekali-kali tidak dapat melepaskan diri) dari azab-Nya.",[["قَالَ","Dia berkata"],["إِنَّمَا","Hanya"],["يَأْتِيكُم","akan membawanya (ke atas) kamu"],["بِهِ","akan membawanya (ke atas) kamu"],["ٱللَّهُ","Allah"],["إِن","jika"],["شَآءَ","Dia kehendaki"],["وَمَآ","dan bukan"],["أَنتُم","kamu (adalah)"],["بِمُعْجِزِينَ","orang yang (boleh) melarikan diri (ia)"]]],"1507":["(Dan tidaklah bermanfaat kepada kalian nasihatku jika aku hendak memberi nasihat kepada kalian sekiranya Allah hendak menyesatkan kalian) artinya berkehendak untuk membuat kalian sesat. Jawab syarat tersirat dari makna yang terkandung di dalam kalimat, 'Dan tidaklah bermanfaat kepada kalian nasihatku.' (Dia adalah Rabb kalian dan kepada-Nyalah kalian dikembalikan\"). Selanjutnya Allah swt. berfirman:",[["وَلَا","Dan (akan) tidak"],["يَنفَعُكُمْ","memberi manfaat kepada kamu"],["نُصْحِىٓ","nasihat aku"],["إِنْ","(walaupun) jika"],["أَرَدتُّ","aku harap"],["أَنْ","kepada"],["أَنصَحَ","[Aku] menasihati"],["لَكُمْ","[kepada] kamu"],["إِن","jika"],["كَانَ","itu milik Allah"],["ٱللَّهُ","itu milik Allah"],["يُرِيدُ","kehendak"],["أَن","kepada"],["يُغْوِيَكُمْ ۚ","biarkan kamu sesat"],["هُوَ","dia (adalah)"],["رَبُّكُمْ","Tuhanmu"],["وَإِلَيْهِ","dan kepada-Nya"],["تُرْجَعُونَ","kamu akan dikembalikan"]]],"1508":["(Bahkan) malahan (mereka mengatakan) yang dimaksud adalah orang-orang kafir Mekah (\"Dia cuma membuat-buatnya saja.\") artinya Muhammad hanya membuat-buat Alquran saja (Katakanlah, \"Jika aku membuat-buatnya, maka hanya akulah yang memikul dosanya) azab sebagai akibat dari perbuatan itu (dan aku berlepas diri dari dosa yang kalian lakukan.\") yaitu dosa tuduhan kalian yang mencap diriku sebagai pembuat Alquran.",[["أَمْ","Atau"],["يَقُولُونَ","(lakukan) mereka berkata"],["ٱفْتَرَىٰهُ ۖ","Dia telah menciptanya"],["قُلْ","Katakanlah"],["إِنِ","Jika"],["ٱفْتَرَيْتُهُۥ","Aku telah menciptanya"],["فَعَلَىَّ","kemudian pada aku"],["إِجْرَامِى","(adalah) jenayah aku"],["وَأَنَا۠","tetapi aku"],["بَرِىٓءٌۭ","tidak bersalah"],["مِّمَّا","tentang apa"],["تُجْرِمُونَ","jenayah yang kamu lakukan"]]],"1509":["(Dan diwahyukan kepada Nuh, bahwasanya sekali-kali tidak akan beriman di antara kaummu kecuali orang yang telah beriman saja, karena itu janganlah kamu bersedih hati) merasa susah (tentang apa yang selalu mereka kerjakan) yaitu perbuatan syirik. Maka Nabi Nuh mendoakan kebinasaan bagi mereka yang tidak beriman, yaitu yang disitir oleh firman-Nya, \"Wahai Rabbku! Janganlah Engkau biarkan di atas muka bumi ini...\" (Nuh 26) kemudian Allah mengabulkan doanya seraya berfirman:",[["وَأُوحِىَ","Dan ia telah didedahkan"],["إِلَىٰ","kepada"],["نُوحٍ","Nuh"],["أَنَّهُۥ","Itu"],["لَن","tidak akan pernah"],["يُؤْمِنَ","beriman"],["مِن","daripada"],["قَوْمِكَ","orang kamu"],["إِلَّا","kecuali"],["مَن","(mereka) yang"],["قَدْ","sudah"],["ءَامَنَ","beriman"],["فَلَا","Jadi (jangan)"],["تَبْتَئِسْ","(menjadi) tertekan"],["بِمَا","oleh apa"],["كَانُوا۟","mereka telah"],["يَفْعَلُونَ","melakukan"]]],"1510":["(Dan buatlah bahtera) perahu (dengan pengawasan Kami) dengan pengawasan dan pemeliharaan Kami (dan petunjuk wahyu Kami) yakni perintah Kami (dan janganlah kamu bicarakan dengan Aku tentang orang-orang yang lalim itu) orang-orang kafir itu, biarkanlah mereka binasa (sesungguhnya mereka itu akan ditenggelamkan).",[["وَٱصْنَعِ","Dan membina"],["ٱلْفُلْكَ","kapal itu"],["بِأَعْيُنِنَا","di bawah Mata Kita"],["وَوَحْيِنَا","dan inspirasi Kami"],["وَلَا","dan jangan"],["تُخَـٰطِبْنِى","alamat Aku"],["فِى","tentang"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوٓا۟ ۚ","dizalimi"],["إِنَّهُم","sesungguhnya mereka (adalah)"],["مُّغْرَقُونَ","yang (akan) tenggelam"]]],"1511":["(Dan mulailah Nuh membuat bahtera) dimaksud menceritakan keadaan masa lampau (Dan setiap kali lewat kepada Nuh segolongan) sebagian (dari kaumnya, mereka mengejeknya) mereka memperolok-olokkannya. (Berkatalah Nuh, \"Jika kalian mengejek kami, maka sesungguhnya kami pun akan mengejek kalian sebagaimana kalian mengejek kami) jika kami selamat dan kalian tenggelam nanti.",[["وَيَصْنَعُ","Dan dia sedang membina"],["ٱلْفُلْكَ","kapal itu"],["وَكُلَّمَا","dan setiap masa"],["مَرَّ","lulus"],["عَلَيْهِ","oleh dia"],["مَلَأٌۭ","(para) ketua"],["مِّن","daripada"],["قَوْمِهِۦ","umatnya"],["سَخِرُوا۟","mereka mengejek"],["مِنْهُ ۚ","[dari] dia"],["قَالَ","Dia berkata"],["إِن","Jika"],["تَسْخَرُوا۟","kamu mengejek"],["مِنَّا","kami"],["فَإِنَّا","kemudian kita"],["نَسْخَرُ","boleh mengejek"],["مِنكُمْ","kamu"],["كَمَا","seperti"],["تَسْخَرُونَ","kamu mengejek"]]],"1512":["(Kelak kalian akan mengetahui siapa) lafal man di sini maushul atau kata sambung, kedudukannya menjadi maf`ul atau objek dari lafal ta`lamuuna (yang akan ditimpa oleh azab yang menghinakannya dan yang akan ditimpa) akan dikenakan (kepadanya azab yang kekal.\")",[["فَسَوْفَ","Dan tidak lama lagi"],["تَعْلَمُونَ","kamu akan tahu"],["مَن","(pada) siapa"],["يَأْتِيهِ","akan datang"],["عَذَابٌۭ","azab"],["يُخْزِيهِ","(yang) akan menghinakannya"],["وَيَحِلُّ","dan akan turun"],["عَلَيْهِ","pada dia"],["عَذَابٌۭ","azab"],["مُّقِيمٌ","berkekalan"]]],"1513":["(Hingga) mengisahkan batas pembuatan bahtera (apabila perintah Kami datang) yang membinasakan mereka (dan dapur telah memancarkan air) yang dimaksud adalah dapur pemanggangan roti, hal itu merupakan pertanda bagi Nabi Nuh. (Kami berfirman, \"Muatkanlah ke dalam bahtera itu) ke dalam perahu itu (dari masing-masing binatang sepasang) yaitu jenis jantan dan betina dari semua jenis binatang (yaitu sejodoh) jantan dan betina. Lafal itsnain ini berkedudukan menjadi maf'ul atau objek. Dan disebutkan di dalam kisah Nabi Nuh, bahwasanya Allah swt. mengumpulkan kepada Nabi Nuh semua binatang buas dan semua jenis unggas atau burung. Kemudian Nabi Nuh a.s. memukulkan tangannya kepada setiap jenis binatang itu; maka tangan kanannya mengenai jenis jantan sedangkan tangan kirinya mengenai jenis betina, lalu ia memuatkannya ke dalam perahu (dan keluargamu) yaitu istri dan anak-anaknya (kecuali orang yang telah terdahulu ketetapan terhadapnya) di antara keluargamu yang sudah dipastikan akan binasa, yaitu anaknya yang bernama Kan'an dan istrinya. Sedangkan Sam, Ham, dan Yafits dibawa oleh Nabi Nuh ke dalam bahtera berikut istri-istri mereka yang berjumlah tiga orang (dan muatkan pula orang-orang yang beriman.\" Dan tidak beriman terhadap Nabi Nuh itu melainkan sedikit). Dikatakan, bahwa jumlah mereka yang beriman itu hanya ada enam orang lelaki dan istri-istri mereka. Menurut pendapat yang lain dikatakan, bahwa jumlah orang-orang yang termuat di dalam bahtera itu ada delapan puluh orang; separuh di antara mereka terdiri dari kaum laki-laki sedangkan separuh yang lainnya terdiri dari kaum wanita.",[["حَتَّىٰٓ","Sehingga"],["إِذَا","apabila"],["جَآءَ","datang"],["أَمْرُنَا","Perintah kami"],["وَفَارَ","dan melimpah"],["ٱلتَّنُّورُ","ketuhar"],["قُلْنَا","Kami berkata"],["ٱحْمِلْ","Muatkan"],["فِيهَا","di dalamnya"],["مِن","daripada"],["كُلٍّۢ","setiap jenis"],["زَوْجَيْنِ","sepasang"],["ٱثْنَيْنِ","dua"],["وَأَهْلَكَ","dan keluarga kamu"],["إِلَّا","kecuali"],["مَن","yang"],["سَبَقَ","telah mendahului"],["عَلَيْهِ","terhadapnya"],["ٱلْقَوْلُ","perkataan itu"],["وَمَنْ","dan sesiapa"],["ءَامَنَ ۚ","beriman"],["وَمَآ","Dan tidak"],["ءَامَنَ","beriman"],["مَعَهُۥٓ","dengan dia"],["إِلَّا","kecuali"],["قَلِيلٌۭ","beberapa"]]],"1514":["(Dan ia berkata) yakni Nabi Nuh (\"Naiklah kamu sekalian ke dalamnya dengan menyebut nama Allah di waktu berlayar dan berlabuhnya.\") artinya sewaktu berlayar dan sewaktu berlabuh. (Sesungguhnya Rabbku benar-benar Maha Pengampun lagi Maha Penyayang) di mana Dia tidak membinasakan kami.",[["۞ وَقَالَ","Dan dia berkata"],["ٱرْكَبُوا۟","Naik kapal"],["فِيهَا","di dalamnya"],["بِسْمِ","dalam nama"],["ٱللَّهِ","daripada Allah"],["مَجْر۪ىٰهَا","(adalah) perjalanannya"],["وَمُرْسَىٰهَآ ۚ","dan berlabuhnya"],["إِنَّ","Sesungguhnya"],["رَبِّى","Tuhanku"],["لَغَفُورٌۭ","(adalah) tentulah Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"1515":["(Dan bahtera itu berlayar membawa mereka dalam gelombang laksana gunung) menggambarkan tentang tinggi dan besarnya gelombang. (Dan Nuh memanggil anaknya) yaitu Kan`an (sedangkan anaknya itu berada di tempat yang jauh) dari bahtera (\"Hai anakku! Naiklah bersama kami dan janganlah kamu berada bersama orang-orang yang kafir.\")",[["وَهِىَ","Dan ia"],["تَجْرِى","belayar"],["بِهِمْ","bersama mereka"],["فِى","pada"],["مَوْجٍۢ","ombak"],["كَٱلْجِبَالِ","seperti gunung"],["وَنَادَىٰ","dan Nuh memanggil"],["نُوحٌ","dan Nuh memanggil"],["ٱبْنَهُۥ","(kepada) anaknya"],["وَكَانَ","dan dia"],["فِى","[dalam]"],["مَعْزِلٍۢ","berpisah"],["يَـٰبُنَىَّ","Wahai anakku"],["ٱرْكَب","Naik kapal"],["مَّعَنَا","dengan kami"],["وَلَا","dan jangan"],["تَكُن","jadilah"],["مَّعَ","dengan"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"1516":["(Anaknya menjawab, \"Aku akan mencari perlindungan ke gunung yang dapat memelihara diriku) yang dapat menyelamatkan diriku (dari air bah ini.\" Nuh berkata, \"Tidak ada yang melindungi hari ini dari azab Allah) dari siksaan-Nya (selain) kecuali hanya (Zat Yang Maha Penyayang.\") yaitu Allah sendiri, hanya Dialah yang dapat menolong. Selanjutnya Allah berfirman mengisahkan kelanjutannya. (Dan gelombang menjadi penghalang antara keduanya, maka jadilah anak itu termasuk orang-orang yang ditenggelamkan.)",[["قَالَ","Dia berkata"],["سَـَٔاوِىٓ","Aku akan mengambil sendiri"],["إِلَىٰ","kepada"],["جَبَلٍۢ","sebuah gunung"],["يَعْصِمُنِى","(itu) akan menyelamatkan aku"],["مِنَ","daripada"],["ٱلْمَآءِ ۚ","air itu"],["قَالَ","Dia berkata"],["لَا","(Ada) tidak"],["عَاصِمَ","pelindung"],["ٱلْيَوْمَ","hari ini"],["مِنْ","daripada"],["أَمْرِ","perintah Allah"],["ٱللَّهِ","perintah Allah"],["إِلَّا","kecuali"],["مَن","(pada) siapa"],["رَّحِمَ ۚ","Dia mempunyai belas kasihan"],["وَحَالَ","Dan datang"],["بَيْنَهُمَا","(di) antara mereka"],["ٱلْمَوْجُ","ombak"],["فَكَانَ","jadi dia"],["مِنَ","antara"],["ٱلْمُغْرَقِينَ","yang lemas"]]],"1517":["(Dan difirmankan, \"Hai bumi! Telanlah airmu) yang bersumberkan darimu, maka langsung bumi menelan airnya akan tetapi yang turun dari langit masih tetap, sehingga jadilah sungai-sungai dan laut-laut (dan hai hujan berhentilah.\") hentikanlah air hujanmu, maka seketika itu juga hujan berhenti (dan surutlah) berkuranglah (air itu hingga selesailah perintah Allah) kaum Nabi Nuh telah selesai dibinasakan (dan bahtera itu berlabuh) bahtera Nabi Nuh berhenti (di atas bukit Al-Judi) nama sebuah bukit yang terletak di suatu pulau dekat dengan negeri Maushul (dan dikatakan, \"Binasalah) hancurlah (orang-orang yang lalim.\") yaitu orang-orang yang kafir.",[["وَقِيلَ","Dan ia dikatakan"],["يَـٰٓأَرْضُ","Wahai bumi"],["ٱبْلَعِى","Telan"],["مَآءَكِ","air kamu"],["وَيَـٰسَمَآءُ","dan wahai langit"],["أَقْلِعِى","menahan"],["وَغِيضَ","Dan reda"],["ٱلْمَآءُ","air itu"],["وَقُضِىَ","dan telah dipenuhi"],["ٱلْأَمْرُ","Perintah itu"],["وَٱسْتَوَتْ","Dan ia berehat"],["عَلَى","pada"],["ٱلْجُودِىِّ ۖ","Judi"],["وَقِيلَ","Dan ia dikatakan"],["بُعْدًۭا","jauh"],["لِّلْقَوْمِ","dengan rakyat"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"1518":["(Dan Nuh berseru kepada Rabbnya seraya berkata, \"Ya Rabbku! Sesungguhnya anakku) yaitu Kan'an (termasuk keluargaku) sedangkan Engkau telah menjanjikan kepadaku akan menyelamatkan mereka (dan sesungguhnya janji Engkau itulah yang benar) janji yang tidak akan diingkari. (Dan Engkau adalah hakim yang seadil-adilnya.\") paling mengetahui masalah kehakiman dan paling adil.",[["وَنَادَىٰ","Dan Nuh menelefon"],["نُوحٌۭ","Dan Nuh menelefon"],["رَّبَّهُۥ","(kepada) Tuhannya"],["فَقَالَ","dan berkata"],["رَبِّ","Wahai Tuhanku"],["إِنَّ","Sesungguhnya"],["ٱبْنِى","anak aku"],["مِنْ","(adalah) daripada"],["أَهْلِى","keluarga aku"],["وَإِنَّ","dan sesungguhnya"],["وَعْدَكَ","janji kamu"],["ٱلْحَقُّ","(adalah) benar"],["وَأَنتَ","dan kamu"],["أَحْكَمُ","(adalah) Yang Maha Adil"],["ٱلْحَـٰكِمِينَ","(dari) para hakim"]]],"1519":["(Dan berfirmanlah) Allah swt. (\"Hai Nuh! Sesungguhnya dia bukan termasuk keluargamu) yang dijanjikan akan diselamatkan, atau dia bukan termasuk pemeluk agamamu (sesungguhnya) permintaanmu kepada-Ku yang memohon supaya dia diselamatkan (perbuatan yang tidak baik) karena sesungguhnya dia adalah orang kafir, dan tidak ada keselamatan bagi orang-orang kafir. Menurut qiraat lain dibaca `amila sedangkan lafal ghairu dibaca ghaira dan dhamir kembali kepada anaknya Nabi Nuh, artinya sesungguhnya dia telah mengerjakan perbuatan yang tidak baik (sebab itu janganlah kamu memohon kepada-Ku) dapat dibaca tas-alanna dan tas-alan (sesuatu yang kamu tidak mengetahuinya) yaitu memohon supaya anakmu diselamatkan. (Sesungguhnya Aku memperingatkan kepadamu supaya kamu jangan termasuk orang-orang yang tidak berpengetahuan\") yang menyebabkan kamu meminta kepada-Ku apa-apa yang kamu tidak ketahui hakikatnya.",[["قَالَ","Dia berkata"],["يَـٰنُوحُ","Wahai Nuh"],["إِنَّهُۥ","Sesungguhnya dia"],["لَيْسَ","(adalah) tidak"],["مِنْ","daripada"],["أَهْلِكَ ۖ","keluarga kamu"],["إِنَّهُۥ","sesungguhnya, [dia]"],["عَمَلٌ","perbuatan (nya)."],["غَيْرُ","(adalah) selain daripada"],["صَـٰلِحٍۢ ۖ","soleh"],["فَلَا","jadi (jangan)"],["تَسْـَٔلْنِ","tanya aku"],["مَا","(tentang) apa"],["لَيْسَ","tidak"],["لَكَ","kamu ada"],["بِهِۦ","daripadanya"],["عِلْمٌ ۖ","sebarang pengetahuan"],["إِنِّىٓ","Sesungguhnya aku"],["أَعِظُكَ","tegur kamu"],["أَن","jangan-jangan"],["تَكُونَ","kamu jadilah"],["مِنَ","antara"],["ٱلْجَـٰهِلِينَ","yang jahil"]]],"1520":["(Nuh berkata, \"Ya Rabbku! Sesungguhnya aku berlindung kepada Engkau) daripada perbuatan (memohon kepada Engkau sesuatu yang aku tiada mengetahui hakikatnya. Dan sekiranya Engkau tidak memberi ampun kepadaku) atas apa yang aku telah terlanjur melakukannya (dan tidak menaruh belas kasihan kepadaku, niscaya aku akan termasuk orang-orang yang merugi\")",[["قَالَ","Dia berkata"],["رَبِّ","Wahai Tuhanku"],["إِنِّىٓ","Sesungguhnya aku"],["أَعُوذُ","mencari perlindungan"],["بِكَ","pada-Mu"],["أَنْ","bahawa"],["أَسْـَٔلَكَ","Aku (harus) bertanya kepada-Mu"],["مَا","apa"],["لَيْسَ","tidak"],["لِى","aku ada"],["بِهِۦ","daripadanya"],["عِلْمٌۭ ۖ","pengetahuan"],["وَإِلَّا","Dan melainkan"],["تَغْفِرْ","kamu maafkan"],["لِى","aku"],["وَتَرْحَمْنِىٓ","dan Engkau kasihanilah aku"],["أَكُن","aku akan jadi"],["مِّنَ","antara"],["ٱلْخَـٰسِرِينَ","yang rugi"]]],"1521":["(Difirmankan, \"Hai Nuh! Turunlah) turunlah dari bahtera (dengan selamat) dengan selamat atau dengan hormat (dari Kami dan penuh keberkahan) penuh kebaikan (atasmu dan atas umat-umat yang mukmin dan orang-orang yang bersamamu\") di dalam bahtera, yang dimaksud adalah anak cucu dan keturunannya, yaitu orang-orang yang beriman (Dan ada pula umat-umat) dibaca rafa` yaitu umamun, makna yang dimaksud adalah umat-umat yang bersamamu (yang Kami beri kesenangan pada mereka) di dunia (kemudian mereka akan ditimpa azab yang pedih dari Kami) di akhirat kelak; mereka adalah orang-orang kafir.",[["قِيلَ","Dikatakan"],["يَـٰنُوحُ","Wahai Nuh"],["ٱهْبِطْ","turunlah"],["بِسَلَـٰمٍۢ","dengan kedamaian"],["مِّنَّا","daripada Kami"],["وَبَرَكَـٰتٍ","dan berkat"],["عَلَيْكَ","pada kamu"],["وَعَلَىٰٓ","dan seterusnya"],["أُمَمٍۢ","bangsa-bangsa"],["مِّمَّن","daripada mereka"],["مَّعَكَ ۚ","bersama kamu"],["وَأُمَمٌۭ","Tetapi (kepada bangsa lain)."],["سَنُمَتِّعُهُمْ","Kami akan memberikan kenikmatan"],["ثُمَّ","kemudian"],["يَمَسُّهُم","akan menyentuh mereka"],["مِّنَّا","daripada Kami"],["عَذَابٌ","azab"],["أَلِيمٌۭ","yang pedih"]]],"1522":["(Itu adalah) ayat-ayat yang mengandung kisah Nabi Nuh (di antara berita-berita penting yang gaib) berita-berita yang belum engkau ketahui (yang Kami wahyukan kepadamu) hai Muhammad (tidak pernah kamu mengetahuinya dan tidak pula kaummu sebelum ini) sebelum diturunkannya Alquran ini. (Maka bersabarlah) di dalam menyampaikan risalah dan menghadapi perlakuan kaummu yang menyakitkan itu, sebagaimana Nabi Nuh bersabar (sesungguhnya kesudahan yang baik) yang terpuji (adalah bagi orang-orang yang bertakwa).",[["تِلْكَ","Ini"],["مِنْ","(adalah) daripada"],["أَنۢبَآءِ","berita itu"],["ٱلْغَيْبِ","(dari) yang ghaib"],["نُوحِيهَآ","(yang) Kami dedahkan"],["إِلَيْكَ ۖ","kepada kamu"],["مَا","Tidak"],["كُنتَ","kamu dahulu"],["تَعْلَمُهَآ","mengetahuinya"],["أَنتَ","kamu"],["وَلَا","dan bukan"],["قَوْمُكَ","orang kamu"],["مِن","daripada"],["قَبْلِ","sebelum"],["هَـٰذَا ۖ","ini"],["فَٱصْبِرْ ۖ","Jadi bersabarlah"],["إِنَّ","sesungguhnya"],["ٱلْعَـٰقِبَةَ","penghujungnya"],["لِلْمُتَّقِينَ","(adalah) untuk Tuhan yang bertakwa"]]],"1523":["(Dan) Kami utuskan (kepada kaum Ad saudara mereka) dari kabilah mereka sendiri (Hud. Ia berkata, \"Hai kaumku! Sembahlah Allah) artinya esakanlah Allah (sekali-kali tidak ada bagi kalian) huruf min di sini zaidah (Tuhan selain Dia, tiada lain) (kalian) yang dimaksud adalah penyembahan kalian terhadap berhala-berhala itu (hanyalah mengada-adakan saja) kalian berdusta terhadap Allah.",[["وَإِلَىٰ","Dan kepada"],["عَادٍ","Aad"],["أَخَاهُمْ","(Kami hantar) saudara mereka"],["هُودًۭا ۚ","Hud"],["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["ٱعْبُدُوا۟","Ibadah"],["ٱللَّهَ","Allah"],["مَا","tidak"],["لَكُم","(adalah) untuk kamu"],["مِّنْ","sebarang"],["إِلَـٰهٍ","tuhan"],["غَيْرُهُۥٓ ۖ","selain Dia"],["إِنْ","Tidak"],["أَنتُمْ","kamu"],["إِلَّا","(adalah) tetapi"],["مُفْتَرُونَ","pencipta"]]],"1524":["(Hai kaumku! Aku tidak meminta kepada kalian atas hal ini) yakni menganjurkan mentauhidkan Allah (upah. Tiada lain) (upahku hanyalah dari Allah yang telah menciptakanku) yang telah menjadikan aku (Maka tidakkah kalian memikirkannya?\")",[["يَـٰقَوْمِ","Wahai kaumku"],["لَآ","Tidak"],["أَسْـَٔلُكُمْ","aku tanya kamu"],["عَلَيْهِ","baginya"],["أَجْرًا ۖ","sebarang ganjaran"],["إِنْ","Tidak"],["أَجْرِىَ","(ialah) pahala aku"],["إِلَّا","kecuali"],["عَلَى","daripada"],["ٱلَّذِى","yang Esa"],["فَطَرَنِىٓ ۚ","mencipta aku"],["أَفَلَا","Kemudian tidak akan"],["تَعْقِلُونَ","kamu menggunakan alasan"]]],"1525":["(Dan dia berkata, \"Hai kaumku! Mohonlah ampun kepada Rabb kalian) dari kemusyrikan (lalu bertobatlah kalian) kembalilah kalian (kepada-Nya) dengan menjalankan ketaatan (niscaya Dia menurunkan hujan) air hujan yang sebelumnya mereka kekeringan (kepada kalian dengan derasnya) sangat deras (dan Dia akan menambahkan kekuatan kepada) bersama dengan (kekuatanmu) yaitu berupa harta benda dan anak-anak (dan janganlah kalian berpaling dengan berbuat dosa.\") yakni berbuat kemusyrikan.",[["وَيَـٰقَوْمِ","Dan wahai kaumku"],["ٱسْتَغْفِرُوا۟","Minta ampun"],["رَبَّكُمْ","Tuhanmu"],["ثُمَّ","kemudian"],["تُوبُوٓا۟","bertaubat"],["إِلَيْهِ","kepada-Nya"],["يُرْسِلِ","Dia akan hantar"],["ٱلسَّمَآءَ","(dari) langit (hujan)"],["عَلَيْكُم","ke atas kamu"],["مِّدْرَارًۭا","(dalam) kelimpahan"],["وَيَزِدْكُمْ","dan menambah kamu"],["قُوَّةً","(dalam) kekuatan"],["إِلَىٰ","(ditambah) kepada"],["قُوَّتِكُمْ","kekuatan kamu"],["وَلَا","Dan jangan"],["تَتَوَلَّوْا۟","berpaling"],["مُجْرِمِينَ","(sebagai) penjenayah"]]],"1526":["(Kaum Ad berkata, \"Hai Hud! Kamu tidak mendatangkan kepada kami suatu bukti yang nyata) yang menunjukkan kebenaran perkataanmu itu (dan kami sekali-kali tidak akan meninggalkan sembahan-sembahan kami karena perkataanmu) hanya karena ucapanmu itu (dan kami sekali-kali tidak akan mempercayai kamu).",[["قَالُوا۟","Mereka berkata"],["يَـٰهُودُ","Wahai Hud"],["مَا","Kamu tidak membawa kami"],["جِئْتَنَا","Kamu tidak membawa kami"],["بِبَيِّنَةٍۢ","bukti yang jelas"],["وَمَا","dan bukan"],["نَحْنُ","kita"],["بِتَارِكِىٓ","(akan) pergi"],["ءَالِهَتِنَا","tuhan kita"],["عَن","pada"],["قَوْلِكَ","kata-kata kamu"],["وَمَا","dan bukan"],["نَحْنُ","kami (adalah)"],["لَكَ","dalam kamu"],["بِمُؤْمِنِينَ","orang yang beriman"]]],"1527":["(Tidaklah) tiadalah (kami mengatakan) perihal dirimu (melainkan, akan menimpamu) kamu akan tertimpa (penyakit gila karena sebagian sembahan kami\") karena sesembahan kami itu akan menyerapah kamu hingga menjadi orang gila, sebab kamu mencacinya, setelah itu kamu akan mengigau sendirian. (Hud menjawab, \"Sesungguhnya aku bersaksi kepada Allah) atas diriku sendiri (dan saksikanlah olehmu sekalian, bahwa sesungguhnya aku berlepas diri dari apa yang kalian persekutukan) itu terhadap Allah.",[["إِن","Tidak"],["نَّقُولُ","kita cakap"],["إِلَّا","kecuali (itu)"],["ٱعْتَرَىٰكَ","telah menangkap kamu"],["بَعْضُ","beberapa"],["ءَالِهَتِنَا","(dari) tuhan-tuhan kami"],["بِسُوٓءٍۢ ۗ","dengan kejahatan"],["قَالَ","Dia berkata"],["إِنِّىٓ","Sesungguhnya aku"],["أُشْهِدُ","[Aku] menyeru Allah menjadi saksi"],["ٱللَّهَ","[Aku] menyeru Allah menjadi saksi"],["وَٱشْهَدُوٓا۟","dan (kamu) menjadi saksi"],["أَنِّى","bahawa aku"],["بَرِىٓءٌۭ","tidak bersalah"],["مِّمَّا","tentang apa"],["تُشْرِكُونَ","kamu bergaul"]]],"1528":["(Dari selain-Nya, sebab itu jalankanlah tipu daya terhadapku) lancarkanlah tipu daya untuk membinasakan diriku (oleh kalian semuanya) oleh kalian dan berhala-berhala sesembahan kalian itu (dan janganlah kalian memberi tangguh kepadaku) janganlah kalian menangguh-nangguhkannya.",[["مِن","Selain Dia"],["دُونِهِۦ ۖ","Selain Dia"],["فَكِيدُونِى","Jadi komplot terhadap aku"],["جَمِيعًۭا","semua bersama"],["ثُمَّ","kemudian"],["لَا","jangan"],["تُنظِرُونِ","beri aku tangguh"]]],"1529":["(Sesungguhnya aku bertawakal kepada Allah, Rabbku dan Rabb kalian. Tidak ada) huruf min di sini adalah zaidah (suatu binatang) makhluk yang melata di bumi (melainkan Dialah yang memegang ubun-ubunnya) artinya, Dialah yang menguasai dan yang memaksakannya, maka tidak dapat memberikan manfaat dan tidak pula mudarat melainkan seizin-Nya. Dalam ayat ini disebutkan lafal an-naashiyah secara khusus, yang artinya ubun-ubun, karena seseorang yang dipegang ubun-ubunnya berarti sangat hina. Ini menggambarkan hinanya makhluk dibandingkan dengan Allah. (Sesungguhnya Rabbku di atas jalan yang lurus) yaitu jalan kebenaran dan keadilan.",[["إِنِّى","Sesungguhnya aku"],["تَوَكَّلْتُ","[Aku] meletakkan kepercayaan aku"],["عَلَى","ke atas"],["ٱللَّهِ","Allah"],["رَبِّى","Tuhanku"],["وَرَبِّكُم ۚ","dan Tuhanmu"],["مَّا","(ada) tidak"],["مِن","daripada makhluk yang bergerak"],["دَآبَّةٍ","daripada makhluk yang bergerak"],["إِلَّا","tetapi"],["هُوَ","Dia"],["ءَاخِذٌۢ","mempunyai genggaman"],["بِنَاصِيَتِهَآ ۚ","ubun-ubunnya"],["إِنَّ","Sesungguhnya"],["رَبِّى","Tuhanku"],["عَلَىٰ","(berada) di atas"],["صِرَٰطٍۢ","satu laluan"],["مُّسْتَقِيمٍۢ","lurus"]]],"1530":["(Jika kalian berpaling) asalnya ialah tatawallau, kemudian salah satu dari huruf ta dibuang sehingga jadilah tawallau, artinya berpaling (maka sesungguhnya aku telah menyampaikan kepada kalian apa/amanat yang aku diutus untuk menyampaikannya kepada kalian. Dan Rabbku akan mengganti kalian dengan kaum yang lain dari kalian; dan kalian tidak dapat membuat mudarat kepada-Nya sedikit pun) oleh sebab kemusyrikan kalian. (Sesungguhnya Rabbku adalah Maha Pemelihara segala sesuatu\") yang mengawasinya.",[["فَإِن","Jadi jika"],["تَوَلَّوْا۟","kamu berpaling"],["فَقَدْ","maka sesungguhnya"],["أَبْلَغْتُكُم","Aku telah sampaikan kepada kamu"],["مَّآ","apa"],["أُرْسِلْتُ","Aku dihantar"],["بِهِۦٓ","dengan [ia]"],["إِلَيْكُمْ ۚ","kepada kamu"],["وَيَسْتَخْلِفُ","Dan Tuhanku akan menggantikan"],["رَبِّى","Dan Tuhanku akan menggantikan"],["قَوْمًا","(kepada) suatu kaum"],["غَيْرَكُمْ","selain kamu"],["وَلَا","dan bukan"],["تَضُرُّونَهُۥ","kamu akan membahayakanNya"],["شَيْـًٔا ۚ","(dalam) apa-apa"],["إِنَّ","Sesungguhnya"],["رَبِّى","Tuhanku"],["عَلَىٰ","(berada) di atas"],["كُلِّ","semua"],["شَىْءٍ","benda"],["حَفِيظٌۭ","seorang Penjaga"]]],"1531":["(Dan tatkala datang perintah Kami) azab Kami (Kami selamatkan Hud dan orang-orang yang beriman bersama dia dengan rahmat) yakni petunjuk (dari Kami; dan Kami selamatkan pula mereka dari azab yang berat) dari siksaan yang keras di akhirat.",[["وَلَمَّا","Dan apabila"],["جَآءَ","datang"],["أَمْرُنَا","Perintah kami"],["نَجَّيْنَا","Kami menyelamatkan"],["هُودًۭا","Hud"],["وَٱلَّذِينَ","dan orang yang"],["ءَامَنُوا۟","beriman"],["مَعَهُۥ","dengan dia"],["بِرَحْمَةٍۢ","oleh Rahmat"],["مِّنَّا","daripada Kami"],["وَنَجَّيْنَـٰهُم","dan Kami selamatkan mereka"],["مِّنْ","daripada"],["عَذَابٍ","azab"],["غَلِيظٍۢ","teruk"]]],"1532":["(Dan itulah kisah kaum Ad) ini mengisyaratkan kepada peninggalan-peninggalan mereka. Makna yang dimaksud ialah berjalanlah kalian di muka bumi ini dan lihatlah bekas-bekas peninggalan mereka. Kemudian Allah swt. menggambarkan keadaan mereka, untuk itu Dia berfirman: (Mereka mengingkari tanda-tanda kekuasaan Rabb mereka dan mendurhakai rasul-rasul Allah) ungkapan di sini memakai bentuk jamak, dimaksud karena orang yang mendurhakai seorang rasul berarti sama saja dengan mendurhakai semua rasul. Karena pada apa yang didatangkan oleh para rasul itu hakikatnya bersumberkan dari asal yang sama, yaitu dari ajaran tauhid (dan mereka menuruti) artinya orang-orang yang rendah (perintah semua penguasa yang sewenang-wenang lagi menentang kebenaran) yakni selalu menentang perkara yang hak, yang dimaksud adalah para pemimpinnya.",[["وَتِلْكَ","Dan ini"],["عَادٌۭ ۖ","(adalah) Aad"],["جَحَدُوا۟","mereka menolak"],["بِـَٔايَـٰتِ","(the) Tanda-tanda"],["رَبِّهِمْ","(dari) Tuhan mereka"],["وَعَصَوْا۟","dan menderhaka"],["رُسُلَهُۥ","Rasul-rasulNya"],["وَٱتَّبَعُوٓا۟","dan diikuti"],["أَمْرَ","(perintah)."],["كُلِّ","(daripada) setiap"],["جَبَّارٍ","zalim"],["عَنِيدٍۢ","degil"]]],"1533":["(Dan mereka selalu diikuti dengan kutukan di dunia ini) dari manusia (dan begitu pula di hari kiamat) mereka akan dikutuk di hadapan makhluk semuanya. (Ingatlah sesungguhnya kaum Ad itu kafir) mereka ingkar (terhadap Rabb mereka. Ingatlah, sesungguhnya amat jauh) dari rahmat Allah (bagi kaum Ad yaitu kaumnya Hud).",[["وَأُتْبِعُوا۟","Dan mereka diikuti"],["فِى","dalam"],["هَـٰذِهِ","ini"],["ٱلدُّنْيَا","dunia"],["لَعْنَةًۭ","(dengan) sumpahan"],["وَيَوْمَ","dan (pada) Hari"],["ٱلْقِيَـٰمَةِ ۗ","Kiamat"],["أَلَآ","Tidak syak lagi"],["إِنَّ","Sesungguhnya"],["عَادًۭا","Aad"],["كَفَرُوا۟","kufur"],["رَبَّهُمْ ۗ","Tuhan mereka"],["أَلَا","Jadi"],["بُعْدًۭا","jauh"],["لِّعَادٍۢ","dengan Aad"],["قَوْمِ","kaum"],["هُودٍۢ","(daripada) Hud"]]],"1534":["(Dan) Kami utus (kepada Tsamud saudara mereka) yang satu kabilah (Saleh. Saleh berkata, \"Hai kaumku! Sembahlah Allah) artinya esakanlah Dia (sekali-kali tidak ada bagi kalian Tuhan selain Dia. Dia telah menciptakan kalian) Dialah yang mula-mula menciptakan kalian (dari bumi) yaitu dengan menciptakan bapak moyang kalian, Adam, dari tanah (dan menjadikan kalian pemakmurnya) Dia menjadikan kalian sebagai para penghuni bumi (karena itu mohonlah ampunan-Nya) dari kemusyrikan (kemudian bertobatlah) kembali kalian (kepada-Nya) dengan menjalankan ketaatan. (Sesungguhnya Rabbku amat dekat) kepada makhluk-Nya melalui pengetahuan-Nya (lagi memperkenankan.\") doa orang yang meminta kepada-Nya.",[["۞ وَإِلَىٰ","Dan kepada"],["ثَمُودَ","kaum Thamud"],["أَخَاهُمْ","(Kami hantar) saudara mereka"],["صَـٰلِحًۭا ۚ","Salih"],["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["ٱعْبُدُوا۟","Ibadah"],["ٱللَّهَ","Allah"],["مَا","tidak"],["لَكُم","kamu ada"],["مِّنْ","sebarang"],["إِلَـٰهٍ","tuhan"],["غَيْرُهُۥ ۖ","selain Dia"],["هُوَ","Dia"],["أَنشَأَكُم","menghasilkan kamu"],["مِّنَ","daripada"],["ٱلْأَرْضِ","bumi"],["وَٱسْتَعْمَرَكُمْ","dan menyelesaikan kamu"],["فِيهَا","di dalamnya"],["فَٱسْتَغْفِرُوهُ","Maka mohonlah ampun kepada-Nya"],["ثُمَّ","kemudian"],["تُوبُوٓا۟","bertaubat"],["إِلَيْهِ ۚ","kepada-Nya"],["إِنَّ","Sesungguhnya"],["رَبِّى","Tuhanku"],["قَرِيبٌۭ","(ada) dekat"],["مُّجِيبٌۭ","Semua Responsif"]]],"1535":["(Kaum Tsamud berkata, \"Hai Saleh! Sesungguhnya engkau adalah seorang di antara kami yang kami harapkan) kami mengharapkan semoga engkau menjadi penghulu dan pemimpin kami (sebelum ini) sebelum apa yang kamu lakukan itu (apakah kamu melarang kami untuk menyembah apa yang disembah oleh bapak-bapak kami) yaitu berhala-berhala (dan sesungguhnya kami betul-betul dalam keraguan terhadap agama yang kamu serukan kepada kami) yaitu agama tauhid (lagi sangat gelisah.\") maksudnya yang diserukannya itu amat meresahkan.",[["قَالُوا۟","Mereka berkata"],["يَـٰصَـٰلِحُ","Wahai Salih"],["قَدْ","Sesungguhnya"],["كُنتَ","kamu dahulu"],["فِينَا","antara kita"],["مَرْجُوًّۭا","yang di letakkan harapan"],["قَبْلَ","sebelum"],["هَـٰذَآ ۖ","ini"],["أَتَنْهَىٰنَآ","Adakah kamu melarang kami"],["أَن","bahawa"],["نَّعْبُدَ","kami sembah"],["مَا","apa"],["يَعْبُدُ","nenek moyang kita disembah"],["ءَابَآؤُنَا","nenek moyang kita disembah"],["وَإِنَّنَا","Dan sesungguhnya kita"],["لَفِى","pasti (berada) dalam"],["شَكٍّۢ","keraguan"],["مِّمَّا","tentang apa"],["تَدْعُونَآ","kamu hubungi kami"],["إِلَيْهِ","kepadanya"],["مُرِيبٍۢ","mencurigakan"]]],"1536":["(Saleh berkata, \"Hai kaumku! Bagaimana pikiran kalian jika aku mempunyai bukti) bukti yang jelas (dari Rabbku dan diberi-Nya aku rahmat daripada-Nya?) kenabian (Maka siapakah yang akan menolong aku) yang dapat memelihara diriku (dari Allah) maksudnya dari azab-Nya (jika aku mendurhakai-Nya. Sebab itu kalian tidak menambah apa pun kepadaku) dengan perintah kalian yang menyuruhku untuk melakukan hal tersebut (selain daripada kerugian.\") penyesatan.",[["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["أَرَءَيْتُمْ","Adakah kamu melihat"],["إِن","jika"],["كُنتُ","aku"],["عَلَىٰ","pada"],["بَيِّنَةٍۢ","bukti yang jelas"],["مِّن","daripada"],["رَّبِّى","Tuhanku"],["وَءَاتَىٰنِى","dan Dia telah memberi aku"],["مِنْهُ","daripadaNya"],["رَحْمَةًۭ","sebuah Rahmat"],["فَمَن","kemudian siapa"],["يَنصُرُنِى","(boleh) membantu aku"],["مِنَ","terhadap"],["ٱللَّهِ","Allah"],["إِنْ","jika"],["عَصَيْتُهُۥ ۖ","Aku (seharusnya) menderhaka kepada-Nya"],["فَمَا","Jadi tidak"],["تَزِيدُونَنِى","kamu akan meningkatkan aku"],["غَيْرَ","tetapi"],["تَخْسِيرٍۢ","(dalam) kerugian"]]],"1537":["(\"Hai kaumku! Inilah unta betina dari Allah sebagai mukjizat yang menunjukkan kebenaran untuk kalian) lafal aayatan berkedudukan menjadi hal atau kata keterangan sedangkan yang menjadi amilnya adalah isim isyarah atau lafal haadzihii tadi (sebab itu biarkanlah dia makan di bumi Allah, dan janganlah kalian mengganggunya dengan gangguan apa pun) seperti menyembelihnya (yang akan menyebabkan kalian ditimpa azab yang dekat.\") jika kalian menyembelihnya.",[["وَيَـٰقَوْمِ","Dan wahai kaumku"],["هَـٰذِهِۦ","Ini"],["نَاقَةُ","unta betina"],["ٱللَّهِ","(milik) Allah"],["لَكُمْ","(adalah) untuk kamu"],["ءَايَةًۭ","sebuah Tanda"],["فَذَرُوهَا","jadi tinggalkan dia"],["تَأْكُلْ","untuk makan"],["فِىٓ","dalam"],["أَرْضِ","bumi"],["ٱللَّهِ","(milik) Allah"],["وَلَا","dan jangan"],["تَمَسُّوهَا","sentuh dia"],["بِسُوٓءٍۢ","dengan kemudaratan"],["فَيَأْخُذَكُمْ","supaya tidak akan menangkap kamu"],["عَذَابٌۭ","azab"],["قَرِيبٌۭ","akan datang"]]],"1538":["(Maka mereka menyembelihnya) unta betina itu disembelih oleh seseorang yang kuat atas perintah mereka (maka ia berkata) Nabi Saleh (\"Bersuka-rialah kalian) bersenang-senanglah kalian (di rumah kalian selama tiga hari) kemudian kalian akan binasa (itu adalah janji yang tidak dapat didustakan.\") janji yang tidak diingkari lagi.",[["فَعَقَرُوهَا","Tetapi mereka memanjangkannya"],["فَقَالَ","Jadi dia berkata"],["تَمَتَّعُوا۟","Nikmati (sendiri)"],["فِى","dalam"],["دَارِكُمْ","rumah kamu"],["ثَلَـٰثَةَ","(untuk) tiga"],["أَيَّامٍۢ ۖ","hari"],["ذَٰلِكَ","Itu"],["وَعْدٌ","(adalah) janji"],["غَيْرُ","tidak"],["مَكْذُوبٍۢ","(untuk) didustakan"]]],"1539":["(Maka tatkala datang perintah Kami) yang memerintahkan supaya mereka dibinasakan (Kami selamatkan Saleh beserta orang-orang yang beriman bersama dia) jumlah mereka ada empat ribu orang (dengan rahmat dari Kami dan) Kami selamatkan pula mereka (dari kehinaan di hari itu) kalau dibaca yaumi-idzin dianggap sebagai isim yang mu`rab dan kalau dibaca yaumaidzin dianggap sebagai isim yang mabni karena diidhafatkan kepada isim yang mabni pula; demikianlah menurut pendapat kebanyakan ahli nahwu. (Sesungguhnya Rabbmu Dialah Yang Maha Kuasa lagi Maha Perkasa) Maha Menang.",[["فَلَمَّا","Maka apabila"],["جَآءَ","datang"],["أَمْرُنَا","Perintah kami"],["نَجَّيْنَا","Kami menyelamatkan"],["صَـٰلِحًۭا","Salih"],["وَٱلَّذِينَ","dan orang yang"],["ءَامَنُوا۟","beriman"],["مَعَهُۥ","dengan dia"],["بِرَحْمَةٍۢ","oleh Rahmat"],["مِّنَّا","daripada Kami"],["وَمِنْ","dan daripada"],["خِزْىِ","(the) aib"],["يَوْمِئِذٍ ۗ","(pada) hari itu"],["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["هُوَ","Dia"],["ٱلْقَوِىُّ","(adalah) Maha Kuat"],["ٱلْعَزِيزُ","Maha Perkasa"]]],"1540":["(Dan satu suara yang keras yang mengguntur menimpa orang-orang yang lalim itu lalu mereka mati bergelimpangan di tempat tinggal mereka) dalam keadaan bersimpuh pada lutut mereka padahal mereka telah mati semuanya.",[["وَأَخَذَ","Dan dirampas"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوا۟","dizalimi"],["ٱلصَّيْحَةُ","letupan gemuruh"],["فَأَصْبَحُوا۟","kemudian mereka menjadi"],["فِى","dalam"],["دِيَـٰرِهِمْ","rumah mereka"],["جَـٰثِمِينَ","jatuh tersungkur"]]],"1541":["(Seolah-olah) lafal ka-an adalah takhfif daripada ka-anna sedangkan isimnya tidak disebutkan, kepanjangannya adalah ka-annahum, artinya seolah-olah mereka (belum pernah berdiam) belum pernah tinggal (di tempat itu) di dalam rumah mereka. (Ingatlah, sesungguhnya kaum Tsamud mengingkari Tuhan mereka. Ingatlah, kebinasaanlah bagi kaum Tsamud) lafal tsamuud dapat ditanwinkan sehingga menjadi tsamuudan dan dapat pula dibaca tanpa memakai tanwin sehingga menjadi tsamuuda. Makna yang dimaksud ialah kabilahnya.",[["كَأَن","Seolah-olah"],["لَّمْ","tidak"],["يَغْنَوْا۟","mereka (telah) berjaya"],["فِيهَآ ۗ","di dalamnya"],["أَلَآ","Tidak syak lagi"],["إِنَّ","sesungguhnya"],["ثَمُودَا۟","kaum Thamud"],["كَفَرُوا۟","kufur"],["رَبَّهُمْ ۗ","(dalam) Tuhan mereka"],["أَلَا","jadi"],["بُعْدًۭا","jauh"],["لِّثَمُودَ","dengan kaum Thamud"]]],"1542":["(Dan sesungguhnya utusan-utusan Kami telah datang kepada Ibrahim dengan membaca kabar gembira) yaitu akan diberi anak bernama Ishak dan menyusul Yakub anak Ishak sesudah itu. (mereka mengucapkan, \"Selamat.\") lafal salaaman menjadi mashdar (Ibrahim menjawab, \"Selamatlah.\") atas kalian (Maka tidak lama kemudian Ibrahim menyuguhkan daging anak sapi yang dipanggang) daging panggang anak sapi.",[["وَلَقَدْ","Dan sungguh"],["جَآءَتْ","datang"],["رُسُلُنَآ","utusan kami"],["إِبْرَٰهِيمَ","(kepada) Ibrahim"],["بِٱلْبُشْرَىٰ","dengan khabar gembira"],["قَالُوا۟","mereka berkata"],["سَلَـٰمًۭا ۖ","Damai"],["قَالَ","Dia berkata"],["سَلَـٰمٌۭ ۖ","Damai"],["فَمَا","dan tidak dia berlengah-lengah"],["لَبِثَ","dan tidak dia berlengah-lengah"],["أَن","kepada"],["جَآءَ","bawak"],["بِعِجْلٍ","seekor anak lembu"],["حَنِيذٍۢ","dibakar"]]],"1543":["(Maka tatkala dilihatnya tangan mereka tidak menjamahnya, Ibrahim memandang aneh perbuatan mereka) merasa heran dengan kelakuan mereka itu (dan mulai timbul) memendam rasa di dalam hati (rasa takut terhadap mereka) ketakutan. (Malaikat itu berkata, \"Jangan kamu takut, sesungguhnya kami adalah malaikat-malaikat yang diutus kepada kaum Luth.\") untuk membinasakan mereka.",[["فَلَمَّا","Tetapi apabila"],["رَءَآ","dia nampak"],["أَيْدِيَهُمْ","tangan mereka"],["لَا","tidak"],["تَصِلُ","mencapai"],["إِلَيْهِ","kepadanya"],["نَكِرَهُمْ","dia berasa asing dengan mereka"],["وَأَوْجَسَ","dan berasa was-was"],["مِنْهُمْ","daripada mereka"],["خِيفَةًۭ ۚ","[takut]"],["قَالُوا۟","Mereka berkata"],["لَا","Jangan"],["تَخَفْ","bertakwa"],["إِنَّآ","Sesungguhnya kami"],["أُرْسِلْنَآ","[kami] telah dihantar"],["إِلَىٰ","kepada"],["قَوْمِ","kaum"],["لُوطٍۢ","(dari) Lut"]]],"1544":["(Dan istrinya) yakni istri Nabi Ibrahim, yaitu Siti Sarah (berdiri) melayani mereka (lalu dia tersenyum) merasa gembira dengan akan dibinasakannya kaum Luth (maka Kami sampaikan kepadanya berita gembira tentang kelahiran Ishak dan menyusul sesudah) (Ishak Yakub) yaitu anak Nabi Ishak yang sempat melihat Nabi Ibrahim.",[["وَٱمْرَأَتُهُۥ","Dan isterinya"],["قَآئِمَةٌۭ","(sedang) berdiri"],["فَضَحِكَتْ","dan dia ketawa"],["فَبَشَّرْنَـٰهَا","Kemudian Kami beri khabar gembira kepadanya"],["بِإِسْحَـٰقَ","daripada Ishak"],["وَمِن","dan selepas"],["وَرَآءِ","dan selepas"],["إِسْحَـٰقَ","Ishak"],["يَعْقُوبَ","(dari) Yaqub"]]],"1545":["(Istrinya berkata, \"Sungguh mengherankan) lafal wailataa ini merupakan kalimat yang biasa diucapkan di kala seseorang melihat perkara yang besar. Huruf ya yang ada padanya merupakan pergantian dari huruf alif (apakah aku akan melahirkan anak padahal aku adalah seorang perempuan tua) aku berumur sembilan puluh sembilan tahun (dan ini suamiku pun dalam keadaan yang sudah tua pula) Nabi Ibrahim pada saat itu berumur seratus atau seratus dua puluh tahun. Lafal syaikhan dinashabkan karena menjadi hal, sedangkan amilnya adalah isim isyarah yaitu lafal haadzaa tadi. (Sesungguhnya ini benar-benar suatu yang aneh\") kedua pasangan yang sama-sama telah tua dapat mempunyai anak.",[["قَالَتْ","Dia berkata"],["يَـٰوَيْلَتَىٰٓ","Celaka aku"],["ءَأَلِدُ","Adakah aku akan melahirkan anak"],["وَأَنَا۠","sedangkan aku"],["عَجُوزٌۭ","seorang wanita tua"],["وَهَـٰذَا","dan ini"],["بَعْلِى","suami aku"],["شَيْخًا ۖ","(adalah) seorang lelaki tua"],["إِنَّ","Sesungguhnya"],["هَـٰذَا","ini"],["لَشَىْءٌ","(adalah) pasti sesuatu"],["عَجِيبٌۭ","menakjubkan"]]],"1546":["(Para malaikat itu berkata, \"Apakah kamu merasa heran tentang perintah Allah) yakni kekuasaan-Nya (itu adalah rahmat Allah dan keberkatan-Nya dicurahkan atas kalian) hai (ahlul bait) keluarga Nabi Ibrahim. (Sesungguhnya Allah Maha Terpuji) sangat terpuji (lagi Maha Pemurah\") Maha Pengasih.",[["قَالُوٓا۟","Mereka berkata"],["أَتَعْجَبِينَ","Adakah kamu kagum"],["مِنْ","di"],["أَمْرِ","(ketetapan) Allah"],["ٱللَّهِ ۖ","(ketetapan) Allah"],["رَحْمَتُ","Rahmat Allah"],["ٱللَّهِ","Rahmat Allah"],["وَبَرَكَـٰتُهُۥ","dan rahmatNya"],["عَلَيْكُمْ","(berada) atas kamu"],["أَهْلَ","orang ramai"],["ٱلْبَيْتِ ۚ","(dari) rumah itu"],["إِنَّهُۥ","Sesungguhnya Dia"],["حَمِيدٌۭ","(adalah) Maha Terpuji"],["مَّجِيدٌۭ","Maha Mulia"]]],"1547":["(Maka tatkala rasa takut hilang dari Ibrahim) perasaan takut telah lenyap dari hatinya (dan berita gembira telah datang kepadanya) yaitu memperoleh anak, mulailah (dia pun bersoal jawab dengan Kami) yakni dengan malaikat-malaikat utusan Kami (tentang) mengenai perihal (kaum Luth).",[["فَلَمَّا","Dan apabila"],["ذَهَبَ","(telah) pergi"],["عَنْ","daripada"],["إِبْرَٰهِيمَ","Ibrahim"],["ٱلرَّوْعُ","ketakutan itu"],["وَجَآءَتْهُ","dan telah sampai kepadanya"],["ٱلْبُشْرَىٰ","berita gembira itu"],["يُجَـٰدِلُنَا","dia berdebat dengan Kami"],["فِى","tentang"],["قَوْمِ","manusia"],["لُوطٍ","daripada Lut"]]],"1548":["(Sesungguhnya Ibrahim itu benar-benar penyantun) sangat sabar (lagi penghiba dan suka kembali kepada Allah) banyak istighfarnya atau ia banyak mengucapkan kalimat innaa lillaahi wa innaa ilaihi raaji`uuna. Maka Nabi Ibrahim berkata kepada para malaikat itu, \"Apakah kalian akan membinasakan suatu kota yang di dalamnya terdapat tiga ratus orang beriman?\" Para malaikat menjawab, \"Tidak.\" Ia kembali bertanya, \"Apakah kalian akan membinasakan suatu kota yang di dalamnya terdapat dua ratus orang yang beriman?\" Para malaikat menjawab, \"Tidak.\" Ia bertanya lagi, \"Apakah kalian akan membinasakan suatu kota yang di dalamnya terdapat empat puluh orang yang beriman.\" Para malaikat menjawab, \"Tidak.\" Ia kembali bertanya, \"Apakah kalian akan membinasakan suatu kota yang di dalamnya terdapat empat belas orang yang beriman?\" Mereka menjawab, \"Tidak.\" Nabi Ibrahim kembali bertanya, \"Bagaimana pendapat kalian jika di dalam sebuah kota terdapat hanya seorang yang beriman?\" Mereka menjawab, \"Tidak pula.\" Maka Nabi Ibrahim berkata kepada mereka, \"Sesungguhnya di dalam kota tersebut terdapat Nabi Luth.\" Mereka menjawab, \"Kami lebih mengetahui tentang orang-orang beriman yang terdapat di dalamnya",[["إِنَّ","Sesungguhnya"],["إِبْرَٰهِيمَ","Ibrahim"],["لَحَلِيمٌ","(adalah) tentulah sabar"],["أَوَّٰهٌۭ","memohon"],["مُّنِيبٌۭ","dan sering kembali"]]],"1549":["Maka tatkala Nabi Ibrahim berkepanjangan di dalam bertanya jawab dengan mereka, lalu mereka mengatakan: (\"Hai Ibrahim! Tinggalkanlah soal jawab ini) perbantahan ini (sesungguhnya telah datang ketetapan Rabbmu) untuk membinasakan mereka (dan sesungguhnya mereka itu akan didatangi azab yang tidak dapat ditolak.\")",[["يَـٰٓإِبْرَٰهِيمُ","Wahai Ibrahim"],["أَعْرِضْ","berpaling"],["عَنْ","daripada"],["هَـٰذَآ ۖ","ini"],["إِنَّهُۥ","Sesungguhnya, ia"],["قَدْ","sudah tentu"],["جَآءَ","telah datang"],["أَمْرُ","(the) Perintah"],["رَبِّكَ ۖ","Tuhanmu"],["وَإِنَّهُمْ","dan sesungguhnya, [mereka]"],["ءَاتِيهِمْ","(akan) datang (untuk) mereka"],["عَذَابٌ","azab"],["غَيْرُ","(yang) tidak boleh"],["مَرْدُودٍۢ","(be) ditolak"]]],"1550":["(Dan tatkala datang utusan-utusan Kami itu kepada Luth, dia merasa susah) merasa repot dengan kedatangan mereka itu (dan merasa sempit dadanya karena kedatangan mereka) mereka datang dalam rupa yang tampan menyamar sebagai tamu-tamu. Hal inilah yang membuat Nabi Luth merasa takut terhadap kaumnya yang tentunya akan berlaku tidak senonoh terhadap tamu-tamunya ini (dan dia berkata, \"Ini adalah hari yang amat berat.\") hari yang sangat keras.",[["وَلَمَّا","Dan apabila"],["جَآءَتْ","datang"],["رُسُلُنَا","utusan kami"],["لُوطًۭا","(kepada) Lut"],["سِىٓءَ","dia tertekan"],["بِهِمْ","bagi mereka"],["وَضَاقَ","dan berasa tertekan"],["بِهِمْ","bagi mereka"],["ذَرْعًۭا","(dan) gelisah"],["وَقَالَ","dan berkata"],["هَـٰذَا","Ini"],["يَوْمٌ","(adalah) sehari"],["عَصِيبٌۭ","menyusahkan"]]],"1551":["(Datanglah kepadanya kaumnya) ketika mereka mengetahui tentang tamu-tamunya itu (dengan bergegas-gegas) dengan segera (menuju kepadanya. Dan sejak dahulu) sebelum kedatangan para tetamu itu (mereka selalu mengerjakan perbuatan-perbuatan keji) yaitu menyetubuhi anus laki-laki. (Ia pernah berkata,) yakni Nabi Luth (\"Hai kaumku! Inilah putri-putriku) maka kawinilah mereka (mereka lebih suci bagi kalian, maka bertakwalah kepada Allah dan janganlah kalian membuat malu) mempermalukan diriku (terhadap tamuku ini) tamu-tamu ini. (Tidak adakah di antara kalian seorang yang berakal?\") yang memerintahkan kalian berbuat kebajikan dan melarang kalian melakukan perbuatan yang mungkar.",[["وَجَآءَهُۥ","Dan datang (kepada)nya"],["قَوْمُهُۥ","umatnya"],["يُهْرَعُونَ","tergesa-gesa"],["إِلَيْهِ","kepadanya"],["وَمِن","dan sebelum ini"],["قَبْلُ","dan sebelum ini"],["كَانُوا۟","mereka (telah) telah"],["يَعْمَلُونَ","melakukan"],["ٱلسَّيِّـَٔاتِ ۚ","perbuatan jahat itu"],["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["هَـٰٓؤُلَآءِ","Ini"],["بَنَاتِى","(adalah) anak perempuan aku"],["هُنَّ","mereka"],["أَطْهَرُ","(adalah) lebih suci"],["لَكُمْ ۖ","bagi kamu"],["فَٱتَّقُوا۟","Jadi takut"],["ٱللَّهَ","Allah"],["وَلَا","dan jangan"],["تُخْزُونِ","memalukan aku"],["فِى","tentang"],["ضَيْفِىٓ ۖ","tetamu aku"],["أَلَيْسَ","Adakah (ada) tidak"],["مِنكُمْ","antara kamu"],["رَجُلٌۭ","seorang lelaki"],["رَّشِيدٌۭ","berfikiran betul"]]],"1552":["(Mereka menjawab, \"Sesungguhnya kamu telah mengetahui bahwa kami tak mempunyai keinginan terhadap putri-putrimu itu) kami tidak membutuhkannya (dan sesungguhnya kamu tentu mengetahui apa yang sekiranya kami kehendaki.\") yaitu suka menyetubuhi anus laki-laki.",[["قَالُوا۟","Mereka berkata"],["لَقَدْ","Sesungguhnya"],["عَلِمْتَ","kamu tahu"],["مَا","(itu) tidak"],["لَنَا","kita ada"],["فِى","tentang"],["بَنَاتِكَ","anak perempuan kamu"],["مِنْ","sebarang"],["حَقٍّۢ","betul"],["وَإِنَّكَ","Dan sesungguhnya, kamu"],["لَتَعْلَمُ","pasti tahu"],["مَا","apa"],["نُرِيدُ","kita mahu"]]],"1553":["(Luth berkata, \"Seandainya aku mempunyai kekuatan untuk menolak kalian) mempunyai kemampuan untuk menolak keinginan kalian (atau kalau aku dapat berlindung kepada keluarga yang kuat\") yakni keluarga yang mau menolongku, tentu aku akan menghajar kalian atas kekurangajaran kalian itu. Maka tatkala para malaikat itu melihat hal tersebut, lalu mereka mengatakan:",[["قَالَ","Dia berkata"],["لَوْ","Jika"],["أَنَّ","bahawa"],["لِى","aku ada"],["بِكُمْ","atas kamu"],["قُوَّةً","kuasa"],["أَوْ","atau"],["ءَاوِىٓ","Aku boleh berlindung"],["إِلَىٰ","dalam"],["رُكْنٍۢ","sebuah sokongan"],["شَدِيدٍۢ","kuat"]]],"1554":["(Para utusan itu berkata, \"Hai Luth! Sesungguhnya kami adalah utusan-utusan Rabbmu, sekali-kali mereka tidak akan dapat mengganggu kamu) dengan berlaku jahat terhadap dirimu (sebab itu bawalah pergi keluarga dan pengikut-pengikut kamu di akhir) pada bagian yang terakhir dari (malam dan janganlah ada seorang pun di antara kalian yang tertinggal) supaya ia tidak melihat kengerian azab yang menimpa mereka (kecuali istrimu) dengan dibaca rafa`, yaitu imra-atuka, berkedudukan menjadi badal dari lafal ahadin. Menurut qiraat lain dibaca nashab, yaitu imra-ataka, berkedudukan menjadi istitsna dari lafal al-ahl. Artinya janganlah engkau membawa pergi dia. (Sesungguhnya dia akan ditimpa azab yang menimpa mereka) menurut suatu pendapat dikatakan bahwa Nabi Luth tidak membawa istrinya pergi. Akan tetapi menurut pendapat yang lain dikatakan bahwa Nabi Luth membawanya pergi. Hanya saja ia menoleh ke belakang seraya mengatakan, 'Aduh kaumku!' Lalu ia ditimpa oleh batu besar sehingga matilah dia.\" Nabi Luth bertanya kepada utusan tentang waktu pembinasaan kaumnya, maka para utusan itu berkata. (\"Sesungguhnya saat jatuhnya azab kepada mereka ialah di waktu subuh) Nabi Luth meminta, 'Aku minta supaya lebih disegerakan lagi.' Mereka menjawab ('Bukankah subuh itu sudah dekat?'\")",[["قَالُوا۟","Mereka berkata"],["يَـٰلُوطُ","Wahai Lut"],["إِنَّا","Sesungguhnya kami"],["رُسُلُ","(adalah) utusan"],["رَبِّكَ","Tuhanmu"],["لَن","tidak pernah"],["يَصِلُوٓا۟","mereka akan sampai"],["إِلَيْكَ ۖ","kamu"],["فَأَسْرِ","Jadi melancong"],["بِأَهْلِكَ","bersama keluarga kamu"],["بِقِطْعٍۢ","dalam bahagian"],["مِّنَ","daripada"],["ٱلَّيْلِ","malam"],["وَلَا","dan (biar) jangan"],["يَلْتَفِتْ","pandang belakang"],["مِنكُمْ","sesiapa di antara kamu"],["أَحَدٌ","sesiapa di antara kamu"],["إِلَّا","kecuali"],["ٱمْرَأَتَكَ ۖ","isteri kamu"],["إِنَّهُۥ","Sesungguhnya, ia"],["مُصِيبُهَا","akan memukulnya"],["مَآ","apa"],["أَصَابَهُمْ ۚ","akan menyerang mereka"],["إِنَّ","Sesungguhnya"],["مَوْعِدَهُمُ","masa yang ditetapkan mereka"],["ٱلصُّبْحُ ۚ","(adalah) pagi"],["أَلَيْسَ","bukan"],["ٱلصُّبْحُ","waktu pagi"],["بِقَرِيبٍۢ","dekat"]]],"1555":["(Maka tatkala datang perintah Kami) untuk membinasakan mereka (Kami jadikan bagian atas) dari negeri kaum Luth (ke bawah) artinya malaikat Jibril mengangkat negeri mereka ke atas kemudian menjatuhkannya ke bumi dalam keadaan terbalik (dan Kami hujani mereka dengan batu dari tanah yang terbakar) yaitu lumpur yang panas membara (dengan bertubi-tubi) secara terus-menerus.",[["فَلَمَّا","Maka apabila"],["جَآءَ","datang"],["أَمْرُنَا","Perintah Kami"],["جَعَلْنَا","Kami buat"],["عَـٰلِيَهَا","terbaliknya"],["سَافِلَهَا","keburukannya"],["وَأَمْطَرْنَا","dan Kami menghujani"],["عَلَيْهَا","ke atas mereka"],["حِجَارَةًۭ","batu"],["مِّن","daripada"],["سِجِّيلٍۢ","tanah liat yang dibakar"],["مَّنضُودٍۢ","(dalam) lapisan"]]],"1556":["(Yang diberi tanda) telah ditandai masing-masing tanah yang membara itu dengan nama orang yang dikenainya (oleh Rabbmu) menjadi zharaf bagi lafal mu`allamatan (dan hal itu) makna yang diisyaratkan di sini adalah azab yang berupa batu itu atau negeri mereka (dari orang-orang yang lalim) artinya penduduk Mekah (tidak jauh).",[["مُّسَوَّمَةً","Ditanda"],["عِندَ","daripada"],["رَبِّكَ ۖ","Tuhanmu"],["وَمَا","Dan tidak"],["هِىَ","ia"],["مِنَ","(adalah) daripada"],["ٱلظَّـٰلِمِينَ","orang yang zalim"],["بِبَعِيدٍۢ","jauh"]]],"1557":["(Dan) Kami utus (kepada penduduk Madyan saudara mereka Syuaib. Ia berkata, \"Hai kaumku! Sembahlah Allah) tauhidkanlah Dia (sekali-kali tiada Tuhan bagi kalian selain Dia. Dan janganlah kalian kurangi takaran dan timbangan, sesungguhnya aku melihat kalian dalam keadaan yang baik) kalian hidup dalam keadaan yang menyenangkan sehingga kalian tidak perlu melakukan pengurangan takaran dan timbangan (dan sesungguhnya aku) (khawatir terhadap kalian) jika kalian tidak mau beriman (akan azab hari yang membinasakan\") hari yang meliputi kalian dengan kebinasaan. Lafal yaum disifati dengan lafal muhith mengandung pengertian majaz, karena terjadinya azab itu pada hari tersebut.",[["۞ وَإِلَىٰ","Dan kepada"],["مَدْيَنَ","Madyan"],["أَخَاهُمْ","abang mereka"],["شُعَيْبًۭا ۚ","Shuaib"],["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["ٱعْبُدُوا۟","Ibadah"],["ٱللَّهَ","Allah"],["مَا","tidak"],["لَكُم","(adalah) untuk kamu"],["مِّنْ","sebarang"],["إِلَـٰهٍ","tuhan"],["غَيْرُهُۥ ۖ","selain Dia"],["وَلَا","Dan jangan"],["تَنقُصُوا۟","berkurangan"],["ٱلْمِكْيَالَ","(dari) sukatan"],["وَٱلْمِيزَانَ ۚ","dan skala"],["إِنِّىٓ","Sesungguhnya aku"],["أَرَىٰكُم","jumpa kamu"],["بِخَيْرٍۢ","dalam kemakmuran"],["وَإِنِّىٓ","tetapi sesungguhnya, aku"],["أَخَافُ","bertakwa"],["عَلَيْكُمْ","bagi kamu"],["عَذَابَ","hukuman"],["يَوْمٍۢ","(dari) sehari"],["مُّحِيطٍۢ","merangkumi semua"]]],"1558":["(Dan Syuaib berkata, \"Hai kaumku!) (Cukupkanlah takaran dan timbungan) sempurnakanlah keduanya (dengan adil) secara tetap (dan janganlah kalian merugikan manusia terhadap hak-hak mereka) janganlah kalian mengurangi hak-hak mereka sedikit pun (dan janganlah kalian membuat kejahatan di muka bumi dengan membuat kerusakan) dengan melakukan pembunuhan dan kejahatan lainnya. Lafal ta'tsau berasal dari fi'il madhi `atsiya, artinya mengadakan kerusakan. Sedangkan lafal mufsidiina berkedudukan menjadi hal atau keterangan yang mengukuhkan makna amilnya yaitu ta'tsau.",[["وَيَـٰقَوْمِ","Dan wahai kaumku"],["أَوْفُوا۟","Beri penuh"],["ٱلْمِكْيَالَ","mengukur"],["وَٱلْمِيزَانَ","dan berat"],["بِٱلْقِسْطِ ۖ","dalam keadilan"],["وَلَا","dan jangan"],["تَبْخَسُوا۟","melucutkan"],["ٱلنَّاسَ","manusia"],["أَشْيَآءَهُمْ","(dari) barang-barang mereka"],["وَلَا","dan jangan"],["تَعْثَوْا۟","bertindak jahat"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["مُفْسِدِينَ","menyebarkan rasuah"]]],"1559":["(Sisa keuntungan dari Allah) yaitu rezeki yang masih tersisa bagi kalian sesudah kalian mencukupkan takaran dan timbangan (adalah lebih baik bagi kalian) daripada perbuatan mengurangi takaran dan timbangan (jika kalian orang-orang yang beriman. Dan aku bukanlah seorang penjaga atas diri kalian.\") aku bukanlah pengawas yang membalas kalian terhadap amal perbuatan kalian, akan tetapi sesungguhnya aku adalah orang yang diutus bagi kalian sebagai pembawa peringatan.",[["بَقِيَّتُ","(Apa) yang tinggal"],["ٱللَّهِ","(dari) Allah"],["خَيْرٌۭ","(adalah) terbaik"],["لَّكُمْ","bagi kamu"],["إِن","jika"],["كُنتُم","kamu"],["مُّؤْمِنِينَ ۚ","orang yang beriman"],["وَمَآ","Dan tidak"],["أَنَا۠","aku"],["عَلَيْكُم","atas kamu"],["بِحَفِيظٍۢ","seorang penjaga"]]],"1560":["(Mereka berkata) kepada Nabi Syuaib dengan nada mengejek (\"Hai Syuaib! Apakah salatmu menyuruhmu) membebankan kepadamu (agar kami meninggalkan apa yang disembah oleh bapak-bapak kami) yaitu berhala-berhala (atau) melarang kami (mencegah kami melakukan apa yang kami kehendaki tentang harta kami) maksudnya hal ini tidak benar sama sekali, tidak ada seorang pun yang menyeru kepada kebaikan. (Sesungguhnya kamu adalah orang yang sangat penyantun lagi berakal.\") mereka mengatakan demikian dengan nada mengejek dan mencemoohkan Nabi Syuaib.",[["قَالُوا۟","Mereka berkata"],["يَـٰشُعَيْبُ","Wahai Syuaib"],["أَصَلَوٰتُكَ","Lakukan solat kamu"],["تَأْمُرُكَ","perintah kamu"],["أَن","bahawa"],["نَّتْرُكَ","kita pergi"],["مَا","apa"],["يَعْبُدُ","ibadah"],["ءَابَآؤُنَآ","nenek moyang kita"],["أَوْ","atau"],["أَن","bahawa"],["نَّفْعَلَ","kita buat"],["فِىٓ","tentang"],["أَمْوَٰلِنَا","kekayaan kita"],["مَا","apa"],["نَشَـٰٓؤُا۟ ۖ","kita akan"],["إِنَّكَ","Sesungguhnya kamu"],["لَأَنتَ","pasti kamu"],["ٱلْحَلِيمُ","(adalah) orang-orang yang penyabar"],["ٱلرَّشِيدُ","yang berfikiran benar"]]],"1561":["(Syuaib berkata, \"Bagaimana pikiran kalian jika aku mempunyai bukti yang nyata dari Rabbku dan dianugerahi-Nya aku daripada-Nya rezeki yang baik) rezeki yang halal lalu apakah patut jika aku mencampurinya dengan barang yang haram hasil mengurangi takaran dan timbangan (Dan aku tidak berkehendak menyalahi kalian) melakukan (apa yang aku larang kalian daripadanya) kemudian aku mengerjakannya. (Aku tidak) aku tiada (bermaksud kecuali mendatangkan perbaikan) bagi kalian supaya menegakkan keadilan (selama aku masih berkesanggupan. Dan tidak ada taufik bagiku) berkemampuan untuk melakukan hal tersebut dan perkara ketaatan lainnya (melainkan dengan pertolongan Allah. Hanya kepada Allah aku bertawakal dan hanya kepada-Nyalah aku kembali.\") mengembalikan semua perkara.",[["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["أَرَءَيْتُمْ","Adakah kamu melihat"],["إِن","jika"],["كُنتُ","aku"],["عَلَىٰ","pada"],["بَيِّنَةٍۢ","bukti yang jelas"],["مِّن","daripada"],["رَّبِّى","Tuhanku"],["وَرَزَقَنِى","dan Dia telah menyediakan aku"],["مِنْهُ","daripada diriNya sendiri"],["رِزْقًا","peruntukan yang baik"],["حَسَنًۭا ۚ","peruntukan yang baik"],["وَمَآ","Dan tidak"],["أُرِيدُ","aku berniat"],["أَنْ","bahawa"],["أُخَالِفَكُمْ","Aku berbeza dengan kamu"],["إِلَىٰ","dalam"],["مَآ","apa"],["أَنْهَىٰكُمْ","aku larang kamu"],["عَنْهُ ۚ","daripadanya"],["إِنْ","Tidak"],["أُرِيدُ","aku berniat"],["إِلَّا","kecuali"],["ٱلْإِصْلَـٰحَ","pembaharuan itu"],["مَا","setakat yang aku mampu"],["ٱسْتَطَعْتُ ۚ","setakat yang aku mampu"],["وَمَا","Dan tidak"],["تَوْفِيقِىٓ","(adalah) kejayaan aku"],["إِلَّا","kecuali"],["بِٱللَّهِ ۚ","dengan Allah"],["عَلَيْهِ","atas Dia"],["تَوَكَّلْتُ","aku beriman"],["وَإِلَيْهِ","dan kepada-Nya"],["أُنِيبُ","aku berpaling"]]],"1562":["(\"Hai kaumku! Janganlah membuat kalian jahat) menyebabkan kalian melakukannya (adanya pertentangan dengan aku) pertentangan antara aku dan kalian. Lafal syiqaaqii menjadi fa'il atau subjek daripada fi'il yajrimannakum, dan lafal qaum yang terkandung di dalamnya berkedudukan menjadi maf'ul awwal atau objek pertama, sedangkan maf'ul yang kedua ialah (hingga kalian ditimpa azab seperti yang menimpa kaum Nuh atau kaum Hud atau kaum Saleh) ditimpa azab yang sama (sedangkan kaum Luth tidaklah) artinya tempat tinggal kaum Luth atau waktu mereka dibinasakan (jauh dari kalian) maka ambillah hal itu sebagai pelajaran buat kalian.",[["وَيَـٰقَوْمِ","Dan wahai kaumku"],["لَا","(Janganlah) menyebabkan kamu berbuat dosa"],["يَجْرِمَنَّكُمْ","(Janganlah) menyebabkan kamu berbuat dosa"],["شِقَاقِىٓ","perselisihan aku"],["أَن","jangan-jangan"],["يُصِيبَكُم","menimpa kamu"],["مِّثْلُ","serupa"],["مَآ","(kepada) apa"],["أَصَابَ","menimpa"],["قَوْمَ","(kaum) Nuh"],["نُوحٍ","(kaum) Nuh"],["أَوْ","atau"],["قَوْمَ","(kaum) Hud"],["هُودٍ","(kaum) Hud"],["أَوْ","atau"],["قَوْمَ","orang Salih"],["صَـٰلِحٍۢ ۚ","orang Salih"],["وَمَا","Dan tidak"],["قَوْمُ","(ialah) kaum Luth"],["لُوطٍۢ","(ialah) kaum Luth"],["مِّنكُم","daripada kamu"],["بِبَعِيدٍۢ","jauh sekali"]]],"1563":["(Dan mohonlah ampun kepada Rabb kalian, kemudian bertobatlah kepada-Nya. Sesungguhnya Rabbku Maha Penyayang) terhadap orang-orang yang beriman (lagi Maha Pengasih.\") sangat mencintai orang-orang yang beriman.",[["وَٱسْتَغْفِرُوا۟","Dan minta ampun"],["رَبَّكُمْ","Tuhanmu"],["ثُمَّ","kemudian"],["تُوبُوٓا۟","bertaubat"],["إِلَيْهِ ۚ","kepada-Nya"],["إِنَّ","Sesungguhnya"],["رَبِّى","Tuhanku"],["رَحِيمٌۭ","(adalah) Maha Penyayang"],["وَدُودٌۭ","Maha Penyayang"]]],"1564":["(Mereka berkata) dengan nada yang menunjukkan kurang perhatian mereka terhadap perkataan Nabi Syuaib (\"Hai Syuaib! Kami tidak mengerti) kurang memahami (banyak tentang apa yang kamu katakan itu dan sesungguhnya kami benar-benar melihat kamu seorang yang lemah di antara kami) maksudnya orang yang rendah (kalau tidaklah karena keluargamu) familimu (tentulah kami telah merajam kamu) dengan batu (sedangkan kamu pun bukanlah seorang yang berwibawa di sisi kami.\") bukan orang-orang tidak pantas untuk dihukum rajam; dan sesungguhnya hanya keluargamu sajalah orang-orang yang berwibawa itu.",[["قَالُوا۟","Mereka berkata"],["يَـٰشُعَيْبُ","Wahai Syuaib"],["مَا","Tidak"],["نَفْقَهُ","kami faham"],["كَثِيرًۭا","banyak"],["مِّمَّا","tentang apa"],["تَقُولُ","kamu cakap"],["وَإِنَّا","dan sesungguhnya, kita"],["لَنَرَىٰكَ","nescaya [kami] melihat kamu"],["فِينَا","antara kita"],["ضَعِيفًۭا ۖ","lemah"],["وَلَوْلَا","Dan jika tidak"],["رَهْطُكَ","untuk keluarga kamu"],["لَرَجَمْنَـٰكَ ۖ","nescaya kami akan merejam kamu"],["وَمَآ","dan kamu tidak"],["أَنتَ","dan kamu tidak"],["عَلَيْنَا","terhadap kita"],["بِعَزِيزٍۢ","perkasa"]]],"1565":["(Syuaib menjawab, \"Hai kaumku! Apakah keluargaku lebih terhormat menurut pandangan kalian daripada Allah) oleh sebab itu lalu kalian tidak mau membunuhku demi mereka dan kalian tidak mau membiarkan aku demi karena Allah (sedangkan kalian menjadikan Dia) yakni kalian menganggap Allah (sebagai sesuatu yang terbuang di belakang kalian) terasing di belakang kalian tanpa kalian hiraukan Dia. (Sesungguhnya Rabbku meliputi apa yang kalian kerjakan.\") Dia Maha Mengetahui kesemuanya; oleh karena itu kelak Dia akan membalas kalian.",[["قَالَ","Dia berkata"],["يَـٰقَوْمِ","Wahai kaumku"],["أَرَهْطِىٓ","Adakah keluarga aku"],["أَعَزُّ","lebih gagah"],["عَلَيْكُم","pada kamu"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["وَٱتَّخَذْتُمُوهُ","Dan kamu telah mengambil Dia"],["وَرَآءَكُمْ","belakang kamu"],["ظِهْرِيًّا ۖ","belakang"],["إِنَّ","Sesungguhnya"],["رَبِّى","Tuhanku"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["مُحِيطٌۭ","(adalah) Merangkumi"]]],"1566":["(Dan dia berkata, \"Hai kaumku! Berbuatlah menurut kemampuan kalian) sesuai dengan keadaan kalian (sesungguhnya aku pun berbuat pula) sesuai dengan kedudukanku. (Kelak kalian akan mengetahui siapa) lafal man di sini adalah maushul yang berkedudukan menjadi maf'ul dari lafal ta'lamuuna (yang akan ditimpa azab yang menghinakannya dan siapa yang berdusta. Dan tunggulah) akibat daripada perbuatan kalian itu (sesungguhnya aku pun menunggu bersama kalian.\") ikut mengawasinya.",[["وَيَـٰقَوْمِ","Dan wahai kaumku"],["ٱعْمَلُوا۟","Kerja"],["عَلَىٰ","(mengikut) kepada"],["مَكَانَتِكُمْ","kedudukan kamu"],["إِنِّى","sesungguhnya, aku"],["عَـٰمِلٌۭ ۖ","bekerja"],["سَوْفَ","Tidak lama lagi"],["تَعْلَمُونَ","kamu akan tahu"],["مَن","(pada) siapa"],["يَأْتِيهِ","akan datang"],["عَذَابٌۭ","azab"],["يُخْزِيهِ","(yang akan) menghinakannya"],["وَمَنْ","dan siapa"],["هُوَ","[dia]"],["كَـٰذِبٌۭ ۖ","(adalah) pembohong"],["وَٱرْتَقِبُوٓا۟","Dan menonton"],["إِنِّى","sesungguhnya, aku"],["مَعَكُمْ","bersama kamu"],["رَقِيبٌۭ","seorang pemerhati"]]],"1567":["(Dan tatkala datang perintah Kami) yang memerintahkan supaya mereka dibinasakan (Kami selamatkan Syuaib dan orang-orang yang beriman bersama-sama dengan dia sebagai rahmat dari Kami, dan orang-orang yang lalim dibinasakan oleh suatu suara yang mengguntur) malaikat Jibril mengeluarkan suara yang mengguntur terhadap mereka (lalu jadilah mereka mati bergelimpangan di tempat tinggalnya) mereka mati dalam keadaan bersimpuh.",[["وَلَمَّا","Dan apabila"],["جَآءَ","datang"],["أَمْرُنَا","Perintah Kami"],["نَجَّيْنَا","Kami menyelamatkan"],["شُعَيْبًۭا","Shuaib"],["وَٱلَّذِينَ","dan orang yang"],["ءَامَنُوا۟","beriman"],["مَعَهُۥ","dengan dia"],["بِرَحْمَةٍۢ","oleh Rahmat"],["مِّنَّا","daripada Kami"],["وَأَخَذَتِ","Dan dirampas"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوا۟","dizalimi"],["ٱلصَّيْحَةُ","letupan gemuruh"],["فَأَصْبَحُوا۟","kemudian mereka menjadi"],["فِى","dalam"],["دِيَـٰرِهِمْ","rumah mereka"],["جَـٰثِمِينَ","jatuh tersungkur"]]],"1568":["(Seolah-olah) mereka; lafal ka-an adalah bentuk takhfif daripada lafal ka-anna (belum pernah tinggal di tempat tinggalnya itu, di tempat mereka bermukim. Ingatlah, kebinasaanlah bagi penduduk Madyan sebagaimana kaum Tsamud telah binasa).",[["كَأَن","Seolah-olah"],["لَّمْ","tidak"],["يَغْنَوْا۟","mereka (telah) berjaya"],["فِيهَآ ۗ","di dalamnya"],["أَلَا","Jadi"],["بُعْدًۭا","jauh"],["لِّمَدْيَنَ","dengan Madyan"],["كَمَا","seperti"],["بَعِدَتْ","telah dibawa pergi"],["ثَمُودُ","kaum Thamud"]]],"1569":["(Dan sesungguhnya Kami telah mengutus Musa dengan membawa tanda-tanda kekuasaan Kami dan mukjizat yang nyata) bukti yang jelas dan gamblang.",[["وَلَقَدْ","Dan sungguh"],["أَرْسَلْنَا","Kami utus"],["مُوسَىٰ","Musa"],["بِـَٔايَـٰتِنَا","dengan Tanda-tanda Kami"],["وَسُلْطَـٰنٍۢ","dan pihak berkuasa"],["مُّبِينٍ","yang nyata"]]],"1570":["(Kepada Firaun dan pemimpin-pemimpin kaumnya, tetapi mereka mengikuti perintah Firaun, padahal perintah Firaun sekali-kali bukanlah perintah yang benar) perintah yang lurus.",[["إِلَىٰ","Kepada"],["فِرْعَوْنَ","Firaun"],["وَمَلَإِي۟هِۦ","dan ketua-ketuanya"],["فَٱتَّبَعُوٓا۟","tetapi mereka mengikut"],["أَمْرَ","(perintah) Firaun"],["فِرْعَوْنَ ۖ","(perintah) Firaun"],["وَمَآ","dan bukan"],["أَمْرُ","(perintah) Firaun"],["فِرْعَوْنَ","(perintah) Firaun"],["بِرَشِيدٍۢ","betul"]]],"1571":["(Ia berjalan di muka) berada paling depan (kaumnya di hari kiamat) sehingga para pengikutnya mengikutinya sebagaimana mereka mengikutinya sewaktu hidup di dunia (lalu memasukkan mereka) menjerumuskan mereka (ke dalam neraka. Neraka itu seburuk-buruk tempat yang didatangi.)",[["يَقْدُمُ","Dia akan mendahului"],["قَوْمَهُۥ","umatnya"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","Kiamat"],["فَأَوْرَدَهُمُ","dan memimpin mereka"],["ٱلنَّارَ ۖ","(ke dalam) Neraka"],["وَبِئْسَ","Dan celaka"],["ٱلْوِرْدُ","(adalah) tempat itu"],["ٱلْمَوْرُودُ","ke mana (mereka) dipimpin"]]],"1572":["(Dan mereka telah diikuti di dalam) dunia ini (oleh kutukan, dan begitu pula di hari kiamat) mereka dikutuk pula (seburuk-buruk pemberian) bantuan (adalah yang diberikan kepada mereka) kutukan yang diberikan kepada mereka.",[["وَأُتْبِعُوا۟","Dan mereka diikuti"],["فِى","dalam"],["هَـٰذِهِۦ","ini"],["لَعْنَةًۭ","(oleh) sumpahan"],["وَيَوْمَ","dan (pada) Hari"],["ٱلْقِيَـٰمَةِ ۚ","Kiamat"],["بِئْسَ","celaka"],["ٱلرِّفْدُ","(ialah) hadiah"],["ٱلْمَرْفُودُ","yang (akan) diberikan"]]],"1573":["(Yang demikian itu) hal yang telah disebutkan tadi; lafal dzaalika berkedudukan menjadi mubtada sedangkan khabarnya ialah (adalah sebagian berita-berita negeri yang Kami ceritakan kepadamu) hai Muhammad (di antaranya) di antara negeri-negeri itu (ada yang masih kedapatan bekas-bekasnya) artinya penduduknya telah binasa tetapi bekas-bekasnya masih ada (dan) di antaranya ada pula (yang telah musnah) telah binasa berikut penduduknya, sehingga tidak ada bekasnya sama sekali. Perumpamaan mereka sama dengan tanaman yang dipanen dengan memakai sabit.",[["ذَٰلِكَ","Itu"],["مِنْ","(adalah) daripada"],["أَنۢبَآءِ","(the) berita"],["ٱلْقُرَىٰ","(dari) bandar-bandar"],["نَقُصُّهُۥ","(yang) Kami kaitkan"],["عَلَيْكَ ۖ","kepada kamu"],["مِنْهَا","daripada mereka"],["قَآئِمٌۭ","ada yang berdiri"],["وَحَصِيدٌۭ","dan (sebahagian) dipotong"]]],"1574":["(Dan Kami tidak menganiaya mereka) dengan membinasakan mereka tanpa dosa (tetapi merekalah yang menganiaya dirinya sendiri) dengan melakukan perbuatan syirik (karena itu tiadalah bermanfaat) tidak ada gunanya (kepada diri mereka, sesembahan-sesembahan yang mereka seru) yang mereka sembah (selain Allah). Huruf min di sini zaidah atau tidak mengandung makna (sedikit pun, di waktu perintah Rabbmu datang) yaitu azab-Nya. (Dan sesembahan-sesembahan itu tidaklah menambah kepada mereka) penyembahan mereka terhadapnya itu tidak dapat memberikan kepada mereka (selain kerugian belaka) yaitu kebinasaan.",[["وَمَا","Dan tidak"],["ظَلَمْنَـٰهُمْ","Kami menganiaya mereka"],["وَلَـٰكِن","tetapi"],["ظَلَمُوٓا۟","mereka melakukan kesalahan"],["أَنفُسَهُمْ ۖ","diri mereka"],["فَمَآ","Jadi tidak"],["أَغْنَتْ","dimanfaatkan"],["عَنْهُمْ","mereka"],["ءَالِهَتُهُمُ","tuhan mereka"],["ٱلَّتِى","yang"],["يَدْعُونَ","mereka menyeru"],["مِن","selain Allah"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["مِن","sebarang"],["شَىْءٍۢ","perkara"],["لَّمَّا","apabila"],["جَآءَ","datang"],["أَمْرُ","(perintah) Tuhanmu"],["رَبِّكَ ۖ","(perintah) Tuhanmu"],["وَمَا","Dan tidak"],["زَادُوهُمْ","mereka menambahnya"],["غَيْرَ","selain daripada"],["تَتْبِيبٍۢ","kehancuran"]]],"1575":["(Dan begitulah) perumpamaan azab-Nya (azab Rabbmu apabila Dia mengazab penduduk negeri-negeri) yang dimaksud adalah penduduknya (yang berbuat lalim) dengan melakukan perbuatan-perbuatan dosa. Jelasnya tidak ada sesuatu pun yang dapat memberi manfaat kepada mereka bila azab Allah diturunkan kepada mereka. (Sesungguhnya azab-Nya itu adalah sangat pedih lagi keras) sehubungan dengan ayat ini Imam Bukhari dan Imam Muslim meriwayatkan sebuah hadis melalui Abu Musa Al-Asyari r.a. yang menceritakan bahwasanya Rasulullah saw. telah bersabda, \"Sesungguhnya Allah selalu mencatat semua perbuatan orang yang aniaya sehingga apabila Dia mengazabnya, maka ia tidak dapat luput daripada-Nya.\" Kemudian Rasulullah saw. membacakan firman-Nya, \"Dan begitulah azab Rabbmu..\" (Q.S. Hud 102)",[["وَكَذَٰلِكَ","Dan dengan demikian"],["أَخْذُ","(ialah) rampasan (dari) Tuhanmu"],["رَبِّكَ","(ialah) rampasan (dari) Tuhanmu"],["إِذَآ","apabila"],["أَخَذَ","Dia merampas"],["ٱلْقُرَىٰ","bandar-bandar"],["وَهِىَ","sedangkan mereka"],["ظَـٰلِمَةٌ ۚ","(sedang) melakukan kesalahan"],["إِنَّ","Sesungguhnya"],["أَخْذَهُۥٓ","sawan dia"],["أَلِيمٌۭ","(adalah) menyakitkan"],["شَدِيدٌ","(dan) teruk"]]],"1576":["(Sesungguhnya pada yang demikian itu) pada kisah-kisah yang telah disebutkan tadi (benar-benar terdapat pelajaran) bahan pelajaran (bagi orang-orang yang takut kepada azab akhirat. Hari itu) yakni hari kiamat itu (adalah suatu hari yang dikumpulkan menghadap kepada-Nya) pada hari itu (semua manusia, dan hari itu adalah suatu hari yang disaksikan) artinya hari itu disaksikan oleh semua makhluk.",[["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَةًۭ","(adalah) sesungguhnya suatu tanda"],["لِّمَنْ","untuk (mereka) yang"],["خَافَ","bertakwa"],["عَذَابَ","azab"],["ٱلْـَٔاخِرَةِ ۚ","(dari) Akhirat"],["ذَٰلِكَ","Itu"],["يَوْمٌۭ","(adalah) sehari"],["مَّجْمُوعٌۭ","(akan) dikumpulkan"],["لَّهُ","di atasnya"],["ٱلنَّاسُ","umat manusia"],["وَذَٰلِكَ","dan bahawa"],["يَوْمٌۭ","(adalah) sehari"],["مَّشْهُودٌۭ","disaksikan"]]],"1577":["(Dan Kami tiadalah mengundur-undurkannya melainkan sampai waktu yang tertentu) waktu yang hanya diketahui oleh Allah.",[["وَمَا","Dan tidak"],["نُؤَخِّرُهُۥٓ","Kami menangguhkannya"],["إِلَّا","kecuali"],["لِأَجَلٍۢ","untuk satu penggal"],["مَّعْدُودٍۢ","terhad"]]],"1578":["(Di kala datang hari itu) sudah tiba saatnya (tidak dapat berbicara) lafal takallama pada asalnya adalah tatakallama, kemudian salah satu huruf tanya dibuang sehingga jadilah ia takallama (seorang pun melainkan dengan izin-Nya) izin Allah swt. (maka di antara mereka) makhluk (ada yang celaka dan) yang lainnya (ada yang berbahagia) masing-masing telah dipastikan nasibnya di zaman azali.",[["يَوْمَ","(The) Hari"],["يَأْتِ","(ia) datang"],["لَا","tidak"],["تَكَلَّمُ","akan bercakap"],["نَفْسٌ","sebuah jiwa"],["إِلَّا","kecuali"],["بِإِذْنِهِۦ ۚ","dengan izinNya"],["فَمِنْهُمْ","Kemudian di antara mereka"],["شَقِىٌّۭ","(akan menjadi) celaka"],["وَسَعِيدٌۭ","dan (yang) gembira"]]],"1579":["(Adapun orang-orang yang celaka) menurut pengetahuan Allah swt. (maka tempatnya di dalam neraka, di dalamnya mereka mengeluarkan jeritan) suara yang sangat keras (dan rintihan) suara yang lemah.",[["فَأَمَّا","Adapun"],["ٱلَّذِينَ","orang yang"],["شَقُوا۟","adalah celaka"],["فَفِى","kemudian (mereka akan) masuk"],["ٱلنَّارِ","neraka"],["لَهُمْ","Untuk mereka"],["فِيهَا","di dalamnya"],["زَفِيرٌۭ","(sedang) mengeluh"],["وَشَهِيقٌ","dan meratap"]]],"1580":["(Mereka kekal di dalamnya selama ada langit dan bumi) artinya selama keberadaan langit dan bumi di alam dunia (kecuali) melainkan (jika Rabbmu menghendaki yang lain) yaitu perpanjangan waktu yang melebihi umur langit dan bumi. Makna yang dimaksud adalah tidak terbatas; mereka kekal di dalamnya untuk selama-lamanya. (Sesungguhnya Rabbmu Maha Pelaksana terhadap apa yang Dia kehendaki.)",[["خَـٰلِدِينَ","(Akan) kekal"],["فِيهَا","di dalamnya"],["مَا","selagi masih ada"],["دَامَتِ","selagi masih ada"],["ٱلسَّمَـٰوَٰتُ","langit"],["وَٱلْأَرْضُ","dan bumi"],["إِلَّا","kecuali"],["مَا","apa yang Tuhanmu kehendaki"],["شَآءَ","apa yang Tuhanmu kehendaki"],["رَبُّكَ ۚ","apa yang Tuhanmu kehendaki"],["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["فَعَّالٌۭ","(ialah) Maha Pencapai"],["لِّمَا","tentang apa"],["يُرِيدُ","Dia berniat"]]],"1581":["(Adapun orang-orang yang berbahagia) dapat dibaca sa`iduu atau su`iduu (maka tempatnya di dalam surga, mereka kekal di dalamnya selama ada langit dan bumi kecuali) melainkan (jika Rabbmu menghendaki) penafsirannya seperti apa yang telah dikemukakan pada ayat terdahulu yang hal ini ditunjukkan oleh firman selanjutnya, yaitu (sebagai karunia yang tiada putus-putusnya) tidak pernah terputus, dan penakwilan yang terdahulu itulah penakwilan yang paling kuat karena ia terlepas dari pengertian yang dipaksakan. Akhirnya hanya Allah jualah Yang Maha Mengetahui akan maksud-Nya.",[["۞ وَأَمَّا","Dan untuk"],["ٱلَّذِينَ","orang yang"],["سُعِدُوا۟","gembira"],["فَفِى","kemudian (mereka akan) masuk"],["ٱلْجَنَّةِ","Syurga"],["خَـٰلِدِينَ","(akan) mematuhi"],["فِيهَا","di dalamnya"],["مَا","selagi masih ada"],["دَامَتِ","selagi masih ada"],["ٱلسَّمَـٰوَٰتُ","langit"],["وَٱلْأَرْضُ","dan bumi"],["إِلَّا","kecuali"],["مَا","apa yang Tuhanmu kehendaki"],["شَآءَ","apa yang Tuhanmu kehendaki"],["رَبُّكَ ۖ","apa yang Tuhanmu kehendaki"],["عَطَآءً","sebuah anugerah"],["غَيْرَ","tidak"],["مَجْذُوذٍۢ","tergendala"]]],"1582":["(Maka janganlah kamu) hai Muhammad (berada dalam keraguan) menaruh syak (tentang apa yang disembah oleh mereka) yaitu berhala-berhala sesembahan mereka karena sesungguhnya Kami akan mengazab mereka sebagaimana Kami mengazab orang-orang sebelum mereka yang melakukan perbuatan yang sama. Ayat ini dimaksud sebagai penghibur hati Nabi saw. (Mereka tidak menyembah melainkan sebagaimana nenek moyang mereka menyembah) artinya sama dengan penyembahan mereka (dahulu) dan sungguh dahulu Kami telah mengazab mereka. (Dan sesungguhnya Kami pasti akan menunaikan terhadap mereka) sama dengan apa yang telah Kami tunaikan kepada nenek moyang mereka (bagian mereka) pembalasan azab mereka (dengan tidak dikurangi sedikit pun) artinya secukup-cukupnya.",[["فَلَا","Jadi (jangan)"],["تَكُ","jadilah"],["فِى","dalam"],["مِرْيَةٍۢ","keraguan"],["مِّمَّا","tentang apa"],["يَعْبُدُ","ibadah"],["هَـٰٓؤُلَآءِ ۚ","mereka ini (orang musyrik)"],["مَا","Tidak"],["يَعْبُدُونَ","mereka menyembah"],["إِلَّا","kecuali"],["كَمَا","sebagai apa"],["يَعْبُدُ","disembah"],["ءَابَآؤُهُم","nenek moyang mereka"],["مِّن","sebelum"],["قَبْلُ ۚ","sebelum"],["وَإِنَّا","Dan sesungguhnya, Kami"],["لَمُوَفُّوهُمْ","pasti akan membayar mereka sepenuhnya"],["نَصِيبَهُمْ","bahagian mereka"],["غَيْرَ","tanpa"],["مَنقُوصٍۢ","semakin berkurangan"]]],"1583":["(Dan sesungguhnya Kami telah memberikan Kitab kepada Musa) yaitu kitab Taurat (lalu diperselisihkan tentang Kitab itu) ada yang membenarkan dan ada yang mendustakan, sama halnya dengan nasib yang menimpa Alquran (Dan seandainya tidak ada ketetapan yang terdahulu dari Rabbmu) dengan ditangguhkannya penghisaban dan pembalasan terhadap semua makhluk hingga hari kiamat nanti (niscaya telah ditetapkan peradilan di antara mereka) di dunia tentang apa yang mereka perselisihkan mengenai masalah Kitab itu. (Dan sesungguhnya mereka) yaitu orang-orang yang mendustakannya (dalam keraguan yang menggelisahkan terhadap Alquran) mereka ragu terhadapnya.",[["وَلَقَدْ","Dan sesungguhnya"],["ءَاتَيْنَا","Kami memberi"],["مُوسَى","Musa"],["ٱلْكِتَـٰبَ","Kitab"],["فَٱخْتُلِفَ","tetapi perbezaan timbul"],["فِيهِ ۚ","di dalamnya"],["وَلَوْلَا","Dan jika tidak"],["كَلِمَةٌۭ","(untuk) Firman"],["سَبَقَتْ","(yang) mendahului"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["لَقُضِىَ","pasti akan dihakimi"],["بَيْنَهُمْ ۚ","antara mereka"],["وَإِنَّهُمْ","Dan sesungguhnya, mereka"],["لَفِى","pasti (berada) dalam"],["شَكٍّۢ","keraguan"],["مِّنْهُ","berkenaan dengannya"],["مُرِيبٍۢ","mencurigakan"]]],"1584":["(Dan sesungguhnya) dapat dibaca wain dan wainna (kepada masing-masing) artinya kepada setiap makhluk (pasti) huruf maa adalah zaidah, sedangkan huruf lam adalah mauthiah atau pendahuluan bagi qasam atau sumpah, atau lam fariqah. Menurut qiraat yang lain lamaa dibaca tasydid sehingga menjadi lammaa yang maknanya sama dengan illaa sedangkan huruf in sebelumnya bermakna nafi (Rabbmu akan menyempurnakan dengan cukup amal perbuatan mereka) yakni pembalasannya. (Sesungguhnya Dia Maha Mengetahui apa yang mereka kerjakan) Dia Maha Mengetahui apa yang tersembunyi dan yang terlahirkan daripadanya.",[["وَإِنَّ","Dan sesungguhnya"],["كُلًّۭا","kepada setiap [apabila]"],["لَّمَّا","kepada setiap [apabila]"],["لَيُوَفِّيَنَّهُمْ","pasti akan membayar mereka sepenuhnya"],["رَبُّكَ","Tuhanmu"],["أَعْمَـٰلَهُمْ ۚ","perbuatan mereka"],["إِنَّهُۥ","Sesungguhnya Dia"],["بِمَا","tentang apa"],["يَعْمَلُونَ","mereka lakukan"],["خَبِيرٌۭ","(adalah) Maha Mengetahui"]]],"1585":["(Maka tetaplah kamu pada jalan yang benar) yaitu mengamalkan perintah Rabbmu dan menyembah kepada-Nya (sebagaimana diperintahkan kepadamu dan) juga tetaplah pada jalan yang benar (orang yang telah bertobat) yaitu orang yang telah beriman (beserta kamu dan janganlah kalian melampuai batas) melanggar batasan-batasan Allah. (Sesungguhnya Dia Maha Melihat apa yang kalian kerjakan) oleh sebab itu Dia membalas kalian.",[["فَٱسْتَقِمْ","Jadi berdiri teguh"],["كَمَآ","seperti"],["أُمِرْتَ","kamu diperintahkan"],["وَمَن","dan (mereka) yang"],["تَابَ","berpaling (dalam taubat)"],["مَعَكَ","bersama kamu"],["وَلَا","dan jangan"],["تَطْغَوْا۟ ۚ","langgar"],["إِنَّهُۥ","Sesungguhnya Dia"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["بَصِيرٌۭ","(ialah) Maha Melihat"]]],"1586":["(Dan janganlah kalian cenderung) condong hati (kepada orang-orang yang lalim) dengan menyukai mereka atau berbasa-basi terhadap mereka atau menyenangi perbuatan mereka (yang menyebabkan kalian disentuh) kalian terkena (api neraka dan sekali-kali kalian tiada mempunyai selain daripada Allah) selain-Nya (seorang penolong pun) yang dapat memelihara diri kalian dari azab-Nya. Huruf min di sini zaidah (kemudian kalian tidak akan diberi pertolongan) sehingga kalian tidak dapat selamat dari azab-Nya.",[["وَلَا","Dan jangan"],["تَرْكَنُوٓا۟","condong"],["إِلَى","kepada"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوا۟","buat salah"],["فَتَمَسَّكُمُ","supaya tidak menyentuh kamu"],["ٱلنَّارُ","neraka"],["وَمَا","dan bukan"],["لَكُم","(adalah) untuk kamu"],["مِّن","selain Allah"],["دُونِ","selain Allah"],["ٱللَّهِ","selain Allah"],["مِنْ","sebarang"],["أَوْلِيَآءَ","pelindung"],["ثُمَّ","kemudian"],["لَا","tidak"],["تُنصَرُونَ","kamu akan dibantu"]]],"1587":["(Dan dirikanlah salat itu pada kedua tepi siang) yaitu di waktu pagi dan sore; yang dimaksud adalah salat subuh, zuhur dan asar (dan pada bagian permulaan) lafal zulafan adalah bentuk jamak dari kata tunggal zulfatan, artinya beberapa bagian (dari malam hari) yaitu salat isyak dan magrib. (Sesungguhnya perbuatan-perbuatan yang baik itu) seperti menjalankan salat lima waktu (menghapuskan perbuatan-perbuatan yang buruk) yakni dosa-dosa yang kecil. Ayat ini diturunkan berkenaan dengan seorang sahabat yang mencium perempuan bukan muhrimnya. Kemudian sahabat itu menceritakannya kepada Nabi saw. Maka Nabi saw. bersabda sampai dengan perkataannya berikut ini, \"... hal ini berlaku bagi umatku seluruhnya.\" Hadis ini diriwayatkan oleh Imam Bukhari dan Imam Muslim. (Itulah peringatan bagi orang-orang yang ingat) sebagai pelajaran bagi orang-orang yang mau mengambil pelajaran.",[["وَأَقِمِ","Dan menubuhkan"],["ٱلصَّلَوٰةَ","solat"],["طَرَفَىِ","(di) dua hujung"],["ٱلنَّهَارِ","(dari) hari itu"],["وَزُلَفًۭا","dan (pada) pendekatan"],["مِّنَ","daripada"],["ٱلَّيْلِ ۚ","malam"],["إِنَّ","Sesungguhnya"],["ٱلْحَسَنَـٰتِ","perbuatan baik itu"],["يُذْهِبْنَ","keluarkan"],["ٱلسَّيِّـَٔاتِ ۚ","perbuatan jahat itu"],["ذَٰلِكَ","Itu"],["ذِكْرَىٰ","(adalah) peringatan"],["لِلذَّٰكِرِينَ","bagi yang ingat"]]],"1588":["(Dan bersabarlah) hai Muhammad, di dalam menghadapi perlakuan kaummu yang menyakitkan itu; atau bersabarlah kamu di dalam menjalankan salat (karena sesungguhnya Allah tidak menyia-nyiakan pahala orang-orang yang berbuat kebaikan) bersabar di dalam menjalankan ketaatan.",[["وَٱصْبِرْ","Dan bersabarlah"],["فَإِنَّ","kerana sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يُضِيعُ","biarkan pergi membazir"],["أَجْرَ","(i) ganjaran"],["ٱلْمُحْسِنِينَ","(dari) orang-orang yang berbuat baik"]]],"1589":["(Maka mengapa tidak ada) mengapa tidak (dari umat-umat) dari bangsa-bangsa terdahulu (sebelum kamu orang-orang yang mempunyai keutamaan) orang-orang yang teguh dalam beragama dan memiliki keutamaan (yang melarang daripada mengerjakan kerusakan di muka bumi) makna yang dimaksud adalah meniadakan, artinya hal tersebut jelas tidak akan terjadi di kalangan mereka (kecuali) hanya (sebagian kecil di antara orang-orang yang telah Kami selamatkan di antara mereka) yang melakukan nahi mungkar sehingga selamatlah mereka. Huruf min di sini mengandung makna bayan atau penjelasan (dan orang-orang yang lalim hanya mementingkan) mereka tidak mau melakukan nahi mungkar dan selalu senang dengan perbuatan kerusakan (kenikmatan yang mewah yang ada pada mereka) mereka hanya bersenang-senang saja (dan mereka adalah orang-orang yang berdosa).",[["فَلَوْلَا","Jadi kenapa tidak"],["كَانَ","telah"],["مِنَ","daripada"],["ٱلْقُرُونِ","generasi"],["مِن","sebelum kamu"],["قَبْلِكُمْ","sebelum kamu"],["أُو۟لُوا۟","mereka yang mempunyai sisa"],["بَقِيَّةٍۢ","mereka yang mempunyai sisa"],["يَنْهَوْنَ","melarang"],["عَنِ","daripada"],["ٱلْفَسَادِ","rasuah itu"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["إِلَّا","kecuali"],["قَلِيلًۭا","beberapa"],["مِّمَّنْ","daripada itu"],["أَنجَيْنَا","Kami menyelamatkan"],["مِنْهُمْ ۗ","antara mereka"],["وَٱتَّبَعَ","Tetapi diikuti"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوا۟","buat salah"],["مَآ","apa"],["أُتْرِفُوا۟","kemewahan yang diberikan kepada mereka"],["فِيهِ","di dalamnya"],["وَكَانُوا۟","dan mereka"],["مُجْرِمِينَ","penjenayah"]]],"1590":["(Dan Rabbmu sekali-kali tidak akan membinasakan negeri-negeri secara lalim) dengan sesuka-Nya terhadap negeri-negeri tersebut (sedangkan penduduknya orang-orang yang berbuat kebaikan) orang-orang yang beriman.",[["وَمَا","Dan tidak"],["كَانَ","akan"],["رَبُّكَ","Tuhanmu"],["لِيُهْلِكَ","memusnahkan"],["ٱلْقُرَىٰ","bandar-bandar"],["بِظُلْمٍۢ","secara tidak adil"],["وَأَهْلُهَا","manakala rakyatnya"],["مُصْلِحُونَ","(adalah) pembaharu"]]],"1591":["(Jikalau Rabbmu menghendaki, tentu Dia menjadikan manusia umat yang satu) pemeluk agama yang satu (tetapi mereka senantiasa berselisih pendapat) dalam masalah agama.",[["وَلَوْ","Dan jika"],["شَآءَ","Tuhanmu (telah) menghendaki"],["رَبُّكَ","Tuhanmu (telah) menghendaki"],["لَجَعَلَ","sesungguhnya Dia (boleh) menjadikan"],["ٱلنَّاسَ","umat manusia"],["أُمَّةًۭ","satu komuniti"],["وَٰحِدَةًۭ ۖ","satu komuniti"],["وَلَا","tetapi tidak"],["يَزَالُونَ","mereka akan berhenti"],["مُخْتَلِفِينَ","untuk berbeza"]]],"1592":["(Kecuali orang-orang yang diberi rahmat oleh Rabbmu) artinya Allah telah menghendaki kebaikan bagi mereka sehingga mereka tidak berselisih pendapat tentangnya. (Dan untuk itulah Allah menciptakan mereka) sebagian di antara mereka ada yang suka berselisih dan sebagian yang lain ada yang diberi rahmat oleh-Nya sehingga mereka tidak berselisih mengenai agama. (Kalimat Rabbmu telah diputuskan) yaitu (sesungguhnya Aku akan memenuhi Jahanam dengan jin dan manusia semuanya.)",[["إِلَّا","Kecuali"],["مَن","(pada) siapa"],["رَّحِمَ","Tuhanmu telah melimpahkan rahmat"],["رَبُّكَ ۚ","Tuhanmu telah melimpahkan rahmat"],["وَلِذَٰلِكَ","dan untuk itu"],["خَلَقَهُمْ ۗ","Dia menciptakan mereka"],["وَتَمَّتْ","Dan akan dipenuhi"],["كَلِمَةُ","(firman) Tuhanmu"],["رَبِّكَ","(firman) Tuhanmu"],["لَأَمْلَأَنَّ","Pasti aku akan penuhkan"],["جَهَنَّمَ","Neraka"],["مِنَ","dengan"],["ٱلْجِنَّةِ","golongan Jin"],["وَٱلنَّاسِ","dan lelaki"],["أَجْمَعِينَ","semua bersama"]]],"1593":["(Dan setiap) lafal kullan ini dinashabkan dengan alamat naqsh sedangkan tanwinnya merupakan pergantian dari mudhaf ilaih, artinya semua kisah rasul-rasul yang diperlukan (Kami ceritakan kepadamu, yaitu kisah-kisah para rasul) lafal maa di sini menjadi badal daripada lafal kullan (yang dengannya Kami teguhkan) Kami tenangkan (hatimu) kalbumu (dan dalam surah ini telah datang kepadamu kebenaran) yang dimaksud adalah kisah-kisah para rasul ini atau ayat-ayat ini (serta pengajaran dan peringatan bagi orang-orang yang beriman) orang-orang yang beriman disebutkan di sini secara khusus, mengingat hanya merekalah yang dapat memanfaatkan adanya kisah-kisah atau ayat-ayat ini untuk mempertebal keimanan mereka, berbeda dengan orang-orang kafir.",[["وَكُلًّۭا","Dan masing-masing"],["نَّقُصُّ","Kami mengaitkan"],["عَلَيْكَ","kepada kamu"],["مِنْ","daripada"],["أَنۢبَآءِ","(the) berita"],["ٱلرُّسُلِ","(dari) para Rasul"],["مَا","(untuk) itu"],["نُثَبِّتُ","Kami boleh membuat tegas"],["بِهِۦ","dengannya"],["فُؤَادَكَ ۚ","hati kamu"],["وَجَآءَكَ","Dan telah datang kepada kamu"],["فِى","dalam"],["هَـٰذِهِ","ini"],["ٱلْحَقُّ","kebenaran"],["وَمَوْعِظَةٌۭ","dan teguran"],["وَذِكْرَىٰ","dan peringatan"],["لِلْمُؤْمِنِينَ","untuk orang yang beriman"]]],"1594":["(Dan katakanlah kepada orang-orang yang tidak beriman, \"Berbuatlah menurut kemampuan kalian) sesuai dengan keadaan dan kondisi kalian (sesungguhnya Kami pun berbuat pula.\") sesuai dengan keadaan Kami; ungkapan ini dimaksud sebagai ancaman buat orang-orang yang tidak beriman.",[["وَقُل","Dan katakan"],["لِّلَّذِينَ","kepada mereka yang"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"],["ٱعْمَلُوا۟","Kerja"],["عَلَىٰ","(mengikut) kepada"],["مَكَانَتِكُمْ","kedudukan kamu"],["إِنَّا","sesungguhnya, kita"],["عَـٰمِلُونَ","(juga) bekerja"]]],"1595":["(\"Dan tunggulah) akibat perbuatan kalian (sesungguhnya kami pun menunggu pula.\") hal tersebut.",[["وَٱنتَظِرُوٓا۟","Dan tunggu"],["إِنَّا","sesungguhnya, kita"],["مُنتَظِرُونَ","(adalah) mereka yang menunggu"]]],"1596":["(Dan kepunyaan Allahlah apa yang gaib di langit dan di bumi) artinya Allah mengetahui semua yang samar atau yang gaib di dalam keduanya (dan kepada-Nyalah dikembalikan) jika dibaca yarji'u artinya sama dengan lafal ya'uudu yaitu kembali. Jika dibaca yurja'u maka artinya sama dengan lafal yuraddu yaitu dikembalikan (urusan-urusan semuanya) oleh sebab itu Dia menghukum orang-orang yang durhaka terhadap-Nya (maka sembahlah Dia) artinya esakanlah Dia (dan bertawakallah kepada-Nya) artinya percayalah kepada-Nya karena sesungguhnya Dialah yang mencukupimu. (Dan sekali-kali Rabbmu tidak lalai dari apa yang mereka kerjakan) sesungguhnya Dia sengaja menangguhkan mereka hanya sampai pada saatnya nanti. Menurut suatu qiraat lafal ya'maluuna dibaca ta`maluuna, artinya yang kalian kerjakan.",[["وَلِلَّهِ","Dan untuk Allah"],["غَيْبُ","(adalah) ghaib"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَإِلَيْهِ","dan kepada-Nya"],["يُرْجَعُ","akan dikembalikan"],["ٱلْأَمْرُ","perkara itu"],["كُلُّهُۥ","semua (dari) itu"],["فَٱعْبُدْهُ","maka sembahlah Dia"],["وَتَوَكَّلْ","dan meletakkan kepercayaan kamu"],["عَلَيْهِ ۚ","atas Dia"],["وَمَا","Dan Tuhanmu tidak"],["رَبُّكَ","Dan Tuhanmu tidak"],["بِغَـٰفِلٍ","tak sedar"],["عَمَّا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"1597":["(Alif laam raa) hanya Allahlah yang mengetahui maksudnya (ini) ayat-ayat ini (adalah ayat-ayat Kitab) yakni Alquran; idhafat di sini mengandung makna min, artinya bagian daripada Alquran (yang jelas) yang membedakan perkara hak daripada perkara yang batil.",[["الٓر ۚ","Alif Laam Ra"],["تِلْكَ","Ini"],["ءَايَـٰتُ","(adalah) Ayat-ayat"],["ٱلْكِتَـٰبِ","Kitab"],["ٱلْمُبِينِ","[yang] jelas"]]],"1598":["(Sesungguhnya Kami menurunkannya berupa Alquran dengan berbahasa Arab) dengan memakai bahasa Arab (agar kalian) hai penduduk Mekah (memahaminya) memahami makna-maknanya.",[["إِنَّآ","Sesungguhnya Kami"],["أَنزَلْنَـٰهُ","Kami telah menurunkannya"],["قُرْءَٰنًا","(sebagai) al-Quran dalam bahasa Arab"],["عَرَبِيًّۭا","(sebagai) al-Quran dalam bahasa Arab"],["لَّعَلَّكُمْ","supaya kamu"],["تَعْقِلُونَ","faham"]]],"1599":["(Kami menceritakan kepadamu kisah yang paling baik dengan mewahyukan) melalui apa yang Kami wahyukan (Alquran ini kepadamu dan sesungguhnya) lafal in merupakan takhfif daripada lafal inna (kamu sebelumnya adalah termasuk orang-orang yang belum mengetahui).",[["نَحْنُ","Kami"],["نَقُصُّ","kaitkan"],["عَلَيْكَ","kepada kamu"],["أَحْسَنَ","yang terbaik"],["ٱلْقَصَصِ","daripada riwayat-riwayat tersebut"],["بِمَآ","pada apa"],["أَوْحَيْنَآ","Kami telah mendedahkan"],["إِلَيْكَ","kepada kamu"],["هَـٰذَا","(dari) ini"],["ٱلْقُرْءَانَ","al-Quran"],["وَإِن","walaupun"],["كُنتَ","kamu dahulu"],["مِن","sebelum itu"],["قَبْلِهِۦ","sebelum itu"],["لَمِنَ","pasti antara"],["ٱلْغَـٰفِلِينَ","yang tidak sedar"]]],"1600":["Ingatlah (Ketika Yusuf berkata kepada ayahnya) Nabi Yakub (\"Wahai ayahku!) dibaca kasrah, yaitu abati untuk menunjukkan adanya ya idhafat yang tidak disebutkan. Sedangkan bila dibaca fatah, maka menunjukkan adanya huruf alif yang tidak disebutkan, yaitu abata, kemudian alif ditukar dengan ya (Sesungguhnya aku telah melihat) di dalam tidurku, yakni bermimpi (sebelas buah bintang dan matahari serta bulan, kulihat semuanya) lafal ra-aytuhum berkedudukan menjadi taukid atau pengukuh dari lafal ra-aytu di muka tadi (sujud kepadaku.\") lafal saajidiina adalah bentuk jamak, yang alamat i'rabnya memakai ya dan nun karena menggambarkan keadaan sujud, hal ini merupakan ciri khas daripada makhluk yang berakal.",[["إِذْ","Apabila"],["قَالَ","berkata"],["يُوسُفُ","Yusuf"],["لِأَبِيهِ","kepada bapanya"],["يَـٰٓأَبَتِ","Wahai ayahku"],["إِنِّى","Sesungguhnya aku"],["رَأَيْتُ","aku nampak"],["أَحَدَ","sebelas"],["عَشَرَ","sebelas"],["كَوْكَبًۭا","bintang"],["وَٱلشَّمْسَ","dan matahari"],["وَٱلْقَمَرَ","dan bulan"],["رَأَيْتُهُمْ","Aku melihat mereka"],["لِى","kepada aku"],["سَـٰجِدِينَ","sujud"]]],"1601":["(Ayahnya berkata, \"Hai anakku! Janganlah kamu ceritakan mimpimu itu kepada saudara-audaramu, maka mereka membuat makar kepadamu) maksudnya mereka pasti akan membuat tipu muslihat guna membinasakanmu, karena terdorong oleh rasa dengki mereka kepadamu. Tentu mereka menakwilkan impianmu itu, bahwa bintang-bintang itu adalah mereka sendiri dan matahari itu adalah ibumu, sedangkan bulan adalah ayahmu. (Sesungguhnya setan itu adalah musuh yang nyata bagi manusia.\") jelas permusuhannya.",[["قَالَ","Dia berkata"],["يَـٰبُنَىَّ","Wahai anakku"],["لَا","Jangan"],["تَقْصُصْ","kaitkan"],["رُءْيَاكَ","penglihatan kamu"],["عَلَىٰٓ","kepada"],["إِخْوَتِكَ","saudara-saudara kamu"],["فَيَكِيدُوا۟","supaya mereka tidak merancang"],["لَكَ","terhadap kamu"],["كَيْدًا ۖ","plot"],["إِنَّ","Sesungguhnya"],["ٱلشَّيْطَـٰنَ","syaitan"],["لِلْإِنسَـٰنِ","(adalah) kepada manusia"],["عَدُوٌّۭ","seorang musuh"],["مُّبِينٌۭ","terbuka"]]],"1602":["(Dan demikianlah) seperti apa yang kamu lihat dalam mimpimu itu (telah memilih kamu) telah mengangkatmu (Rabbmu dan diajarkan-Nya kepadamu sebagian dari takwil-takwil mimpi) makna mimpi (dan disempurnakan-Nya kepadamu nikmat-Nya) yaitu kenabian (dan kepada keluarga Yakub) yakni anak-anaknya (sebagaimana Dia telah menyempurnakan nikmat-Nya) yaitu nikmat kenabian (kepada kedua orang tuamu sebelum itu, yaitu Ibrahim dan Ishak. Sesungguhnya Rabbmu Maha Mengetahui) tentang makhluk-Nya (lagi Maha Bijaksana) di dalam memperlakukan mereka.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["يَجْتَبِيكَ","akan memilih kamu"],["رَبُّكَ","Tuhanmu"],["وَيُعَلِّمُكَ","dan akan mengajar kamu"],["مِن","daripada"],["تَأْوِيلِ","(the) tafsiran"],["ٱلْأَحَادِيثِ","(daripada) naratif"],["وَيُتِمُّ","dan lengkap"],["نِعْمَتَهُۥ","NikmatNya"],["عَلَيْكَ","pada kamu"],["وَعَلَىٰٓ","dan seterusnya"],["ءَالِ","(keluarga)."],["يَعْقُوبَ","(dari) Yaqub"],["كَمَآ","seperti"],["أَتَمَّهَا","Dia menyelesaikannya"],["عَلَىٰٓ","pada"],["أَبَوَيْكَ","dua moyang kamu"],["مِن","sebelum ini"],["قَبْلُ","sebelum ini"],["إِبْرَٰهِيمَ","Ibrahim"],["وَإِسْحَـٰقَ ۚ","dan Ishak"],["إِنَّ","Sesungguhnya"],["رَبَّكَ","Tuhanmu"],["عَلِيمٌ","Maha Mengetahui"],["حَكِيمٌۭ","Maha Bijaksana"]]],"1603":["(Sesungguhnya telah ada pada) kisah (Yusuf dan saudara-saudaranya) jumlah mereka ada sebelas orang (tanda-tanda) bahan-bahan pelajaran (bagi orang-orang yang bertanya).",[["۞ لَّقَدْ","Sungguh"],["كَانَ","adalah"],["فِى","dalam"],["يُوسُفَ","Yusuf"],["وَإِخْوَتِهِۦٓ","dan saudara-saudaranya"],["ءَايَـٰتٌۭ","tanda-tanda"],["لِّلسَّآئِلِينَ","bagi yang bertanya"]]],"1604":["Ingatlah (ketika mereka berkata) yaitu sebagian saudara-saudara Nabi Yusuf kepada sebagian yang lain (\"Sesungguhnya Yusuf) lafal Yusuf berkedudukan menjadi mubtada (dan saudaranya) yang sekandung yaitu Bunyamin (lebih dicintai) menjadi khabar dari lafal Yusuf tadi (oleh ayah kita daripada kita sendiri, padahal kita ini adalah satu golongan) kelompok yang kuat. (Sesungguhnya ayah kita adalah dalam kesesatan) kekeliruan (yang nyata) kekeliruan yang jelas dikarenakan ia lebih menyayangi Yusuf dan saudara sekandungnya daripada kita.",[["إِذْ","Apabila"],["قَالُوا۟","mereka berkata"],["لَيُوسُفُ","Pasti Yusuf"],["وَأَخُوهُ","dan abangnya"],["أَحَبُّ","(adalah) lebih disayangi"],["إِلَىٰٓ","kepada"],["أَبِينَا","bapa kita"],["مِنَّا","daripada kita"],["وَنَحْنُ","sedangkan kita"],["عُصْبَةٌ","(adalah) kumpulan"],["إِنَّ","Sesungguhnya"],["أَبَانَا","bapa kita"],["لَفِى","(adalah) pasti dalam"],["ضَلَـٰلٍۢ","satu kesilapan"],["مُّبِينٍ","yang nyata"]]],"1605":["(Bunuhlah Yusuf atau buanglah dia ke suatu daerah) ke tempat yang jauh dan belum dikenal (supaya perhatian ayah kalian tertumpah kepada kalian) sehingga beliau hanya memperhatikan kalian dan tidak kepada yang lainnya (dan sesudah itu hendaklah kalian) sesudah membunuh Yusuf atau membuangnya (menjadi orang-orang yang baik.\") dengan jalan bertobat.",[["ٱقْتُلُوا۟","Bunuh"],["يُوسُفَ","Yusuf"],["أَوِ","atau"],["ٱطْرَحُوهُ","buang dia"],["أَرْضًۭا","(ke) tanah"],["يَخْلُ","jadi akan percuma"],["لَكُمْ","bagi kamu"],["وَجْهُ","(si) muka"],["أَبِيكُمْ","(dari) bapa kamu"],["وَتَكُونُوا۟","dan kamu akan menjadi"],["مِنۢ","selepas itu"],["بَعْدِهِۦ","selepas itu"],["قَوْمًۭا","suatu kaum"],["صَـٰلِحِينَ","soleh"]]],"1606":["(Seorang di antara mereka berkata,) yaitu Yahudza (\"Janganlah kalian bunuh Yusuf, tetapi lemparkanlah dia) masukkanlah dia (ke dasar sumur) yang gelap sekali. Menurut qiraat lafal al-jub dibaca dalam bentuk jamak (supaya dia dipungut oleh beberapa orang musafir) orang-orang yang sedang melakukan perjalanan (jika kalian hendak berbuat.\") apa yang kalian kehendaki, yaitu ingin memisahkan antara Yusuf dan ayahnya, maka cukuplah dengan cara tersebut.",[["قَالَ","Berkata"],["قَآئِلٌۭ","seorang penceramah"],["مِّنْهُمْ","antara mereka"],["لَا","Jangan"],["تَقْتُلُوا۟","membunuh"],["يُوسُفَ","Yusuf"],["وَأَلْقُوهُ","tapi buang dia"],["فِى","dalam"],["غَيَـٰبَتِ","bahagian bawah"],["ٱلْجُبِّ","(dari) perigi"],["يَلْتَقِطْهُ","akan memilihnya"],["بَعْضُ","beberapa"],["ٱلسَّيَّارَةِ","[the] karavan"],["إِن","jika"],["كُنتُمْ","kamu"],["فَـٰعِلِينَ","melakukan"]]],"1607":["(Mereka berkata, \"Wahai ayah kami! Apa sebabnya engkau tidak mempercayai kami terhadap Yusuf, padahal sesungguhnya kami adalah orang-orang yang menginginkan kebaikan baginya.\") orang-orang yang bersedia mengurusi semua kepentingan-kepentingannya.",[["قَالُوا۟","Mereka berkata"],["يَـٰٓأَبَانَا","Wahai ayah kami"],["مَا","kenapa"],["لَكَ","(buat) kamu"],["لَا","tidak"],["تَأْمَ۫نَّا","percayakan kami"],["عَلَىٰ","dengan"],["يُوسُفَ","Yusuf"],["وَإِنَّا","sedangkan sesungguhnya, kita"],["لَهُۥ","(adalah) untuknya"],["لَنَـٰصِحُونَ","pastinya orang yang berbahagia"]]],"1608":["(\"Biarkanlah dia pergi bersama kami besok pagi) ke padang sahara (agar dia dapat bersenang-senang dan bermain-main) dapat dibaca yarta' dan yal'ab, atau narta' dan nal`ab; artinya supaya dia atau kami dapat semangat yang baru dan pikiran yang segar (dan sesungguhnya kami pasti menjaganya\").",[["أَرْسِلْهُ","Hantar dia"],["مَعَنَا","dengan kami"],["غَدًۭا","esok"],["يَرْتَعْ","(untuk) menikmati"],["وَيَلْعَبْ","dan bermain"],["وَإِنَّا","Dan sesungguhnya, kita"],["لَهُۥ","baginya"],["لَحَـٰفِظُونَ","pasti (akan) menjadi penjaga"]]],"1609":["(Berkata Yakub, \"Sesungguhnya amat menyedihkan aku kepergian kalian) bila kalian pergi (bersama Yusuf) karena merasa berat berpisah dengannya (dan aku khawatir kalau-kalau dia dimakan serigala) makna yang dimaksud adalah jenis, yaitu mencakup semua binatang buas. Tersebutlah bahwa daerah tempat tinggal mereka terkenal banyak hewan buasnya (sedangkan kalian lengah daripadanya.\") lalai daripadanya.",[["قَالَ","Dia berkata"],["إِنِّى","Sesungguhnya, [aku]"],["لَيَحْزُنُنِىٓ","ia pasti menyedihkan aku"],["أَن","bahawa"],["تَذْهَبُوا۟","kamu patut bawa dia"],["بِهِۦ","kamu patut bawa dia"],["وَأَخَافُ","dan aku takut"],["أَن","bahawa"],["يَأْكُلَهُ","akan memakannya"],["ٱلذِّئْبُ","seekor serigala"],["وَأَنتُمْ","sedangkan kamu"],["عَنْهُ","daripada dia"],["غَـٰفِلُونَ","(ada) tidak sedar"]]],"1610":["(Mereka berkata, \"Jika benar-benar) lam di sini bermakna qasam atau sumpah (ia dimakan oleh serigala sedangkan kami adalah golongan yang kuat) kelompok yang kuat (sesungguhnya kami kalau demikian adalah orang-orang yang merugi.\") orang-orang yang tidak mampu membela diri. Kemudian setelah itu Nabi Yakub mengizinkan kepergian mereka membawa Nabi Yusuf.",[["قَالُوا۟","Mereka berkata"],["لَئِنْ","Jika"],["أَكَلَهُ","makan dia"],["ٱلذِّئْبُ","serigala itu"],["وَنَحْنُ","sedangkan kita"],["عُصْبَةٌ","(adalah) kumpulan"],["إِنَّآ","sesungguhnya, kita"],["إِذًۭا","kemudian"],["لَّخَـٰسِرُونَ","pasti (akan) merugi"]]],"1611":["(Maka tatkala mereka membawanya dan sepakat) telah bertekad bulat (untuk memasukkannya ke dalam sumur) jawab dari lafal lammaa tidak disebutkan, yaitu maka mereka melakukan niatnya itu. Untuk itu mereka melepas baju Nabi Yusuf setelah terlebih dahulu dipukuli dan dicaci maki, kemudian mereka mengulurkan tali timba ke dalam sumur tersebut sedangkan Nabi Yusuf diikatkan padanya. Ketika tali timba mencapai setengah kedalaman sumur, lalu mereka melepaskannya, supaya Nabi Yusuf jatuh ke bawah lalu mati. Akan tetapi Nabi Yusuf jatuh di air, kemudian ia duduk di atas batu besar yang ada dalam sumur itu. Lalu saudara-saudaranya menyerunya, dan Nabi Yusuf menjawab seruan mereka; akan tetapi mereka menganggap bahwa Nabi Yusuf meminta pertolongan kepada mereka. Mereka bermaksud untuk menimpakan batu besar kepadanya, akan tetapi mereka dicegah oleh Yahudza. (Dan Kami wahyukan kepadanya) sewaktu ia berada di dalam sumur. Nabi Yusuf hidup di dalam sumur selama tujuh belas tahun atau kurang daripadanya. Allah memberikan wahyu kepadanya sebagai penenang hatinya (\"Sesungguhnya kamu akan menceritakan kepada mereka) sesudah peristiwa ini (tentang perbuatan mereka ini) tentang perlakuan mereka ini (sedangkan mereka tiada ingat lagi.\") terhadap dirimu sewaktu kamu bercerita kepada mereka.",[["فَلَمَّا","Maka apabila"],["ذَهَبُوا۟","mereka membawanya"],["بِهِۦ","mereka membawanya"],["وَأَجْمَعُوٓا۟","dan bersetuju"],["أَن","bahawa"],["يَجْعَلُوهُ","mereka meletakkan dia"],["فِى","dalam"],["غَيَـٰبَتِ","(bahagian bawah)."],["ٱلْجُبِّ ۚ","(dari) perigi"],["وَأَوْحَيْنَآ","Tetapi Kami memberi inspirasi"],["إِلَيْهِ","kepadanya"],["لَتُنَبِّئَنَّهُم","Pasti, kamu akan memberitahu mereka"],["بِأَمْرِهِمْ","tentang urusan ini"],["هَـٰذَا","tentang urusan ini"],["وَهُمْ","sedangkan mereka"],["لَا","jangan"],["يَشْعُرُونَ","mempersepsikan"]]],"1612":["(Kemudian mereka datang kepada ayah mereka di sore hari) pada waktu sore (sambil menangis).",[["وَجَآءُوٓ","Dan mereka datang"],["أَبَاهُمْ","(kepada) bapa mereka"],["عِشَآءًۭ","awal malam"],["يَبْكُونَ","menangis"]]],"1613":["(Mereka berkata, \"Wahai ayah kami! Sesungguhnya kami pergi berlomba-lomba) memanah (dan kami tinggalkan Yusuf di dekat barang-barang kami) yakni pakaian-pakaian kami (lalu dia dimakan oleh serigala dan engkau sekali-kali tidak akan percaya) mempercayai (kepada kami sekali pun kami adalah orang-orang yang benar.\") terhadapmu. Pasti engkau akan menuduh kami dengan tuduhan yang bukan-bukan sehubungan dengan perihal Yusuf ini karena kecintaanmu terhadapnya. Mengapa sampai sedemikian buruknya persangkaanmu terhadap diri kami?",[["قَالُوا۟","Mereka berkata"],["يَـٰٓأَبَانَآ","Wahai ayah kami"],["إِنَّا","Sesungguhnya kami"],["ذَهَبْنَا","[kami] pergi"],["نَسْتَبِقُ","berlumba sesama sendiri"],["وَتَرَكْنَا","dan kami pergi"],["يُوسُفَ","Yusuf"],["عِندَ","dengan"],["مَتَـٰعِنَا","harta benda kita"],["فَأَكَلَهُ","dan memakannya"],["ٱلذِّئْبُ ۖ","serigala itu"],["وَمَآ","Tetapi tidak"],["أَنتَ","kamu"],["بِمُؤْمِنٍۢ","(akan) beriman"],["لَّنَا","kami"],["وَلَوْ","walaupun"],["كُنَّا","kita"],["صَـٰدِقِينَ","jujur"]]],"1614":["(Mereka datang membawa baju gamisnya) lafal `alaa qamiishihi beri'rab mahal nashab karena menjadi zharaf. Artinya yang berlumuran padanya (dengan darah palsu) darah yang bukan darah Nabi Yusuf; hal ini mereka lakukan dengan menyembelih seekor kambing, kemudian mereka lumurkan darahnya pada baju gamis Nabi Yusuf, akan tetapi mereka lupa merobek-robeknya. Lalu mereka menghadap kepada ayahnya seraya berkata, \"Sesungguhnya ini adalah darah Yusuf.\" (Yakub berkata) sewaktu ia melihat baju Yusuf dalam keadaan utuh dan ia mengetahui bahwa mereka berdusta dalam hal ini (\"Sebenarnya telah menghiasi) menganggap baik (diri kalian suatu perbuatan yang buruk) kemudian kalian mengerjakannya (maka kesabaran yang baik itulah kesabaranku) kesabaran yang tidak disertai rasa kaget dan gelisah. Lafal fashabrun jamiil ini adalah mubtada sedangkan khabarnya tidak disebutkan, yaitu amri yang artinya adalah kesabaranku. (Dan Allah sajalah yang dimohon pertolongan-Nya) hanya Allahlah yang diminta pertolongan-Nya (terhadap apa yang kalian ceritakan.\") apa yang kalian kisahkan tentang perkara Yusuf ini.",[["وَجَآءُو","Dan mereka membawa"],["عَلَىٰ","ke atas"],["قَمِيصِهِۦ","bajunya"],["بِدَمٍۢ","dengan darah palsu"],["كَذِبٍۢ ۚ","dengan darah palsu"],["قَالَ","Dia berkata"],["بَلْ","Bahkan"],["سَوَّلَتْ","telah memikat kamu"],["لَكُمْ","telah memikat kamu"],["أَنفُسُكُمْ","jiwa kamu"],["أَمْرًۭا ۖ","(kepada) sesuatu perkara"],["فَصَبْرٌۭ","jadi sabar"],["جَمِيلٌۭ ۖ","(adalah) cantik"],["وَٱللَّهُ","Dan Allah"],["ٱلْمُسْتَعَانُ","(ialah) Dia yang meminta pertolongan"],["عَلَىٰ","terhadap"],["مَا","apa"],["تَصِفُونَ","kamu huraikan"]]],"1615":["(Kemudian datanglah kelompok orang-orang musafir) rombongan orang-orang yang melakukan perjalanan dari Madyan ke Mesir, lalu mereka istirahat di dekat sumur Nabi Yusuf (lalu mereka menyuruh seorang pengambil air) yang khusus untuk mencari air buat minum rombongan musafir (maka dia menurunkan) melepaskan (timbanya) ke dalam sumur kemudian Nabi Yusuf bergantung ke tali timba, sehingga keluarlah Nabi Yusuf dari dalam sumur itu. Ketika pengambil air melihat Nabi Yusuf (dia berkata, \"Oh, kabar gembira) menurut suatu qiraat dibaca busyraaya seruan di sini mengandung makna majaz, artinya cepatlah ini sudah masanya bagimu (ini seorang anak muda.\") maka hal itu diketahui oleh teman-teman penimba air, lalu mereka mendatanginya. (Kemudian mereka menyembunyikan dia) artinya, mereka merahasiakan perkara Nabi Yusuf ini, dengan maksud untuk menjadikannya (sebagai barang dagangan) seumpamanya mereka menganggapnya sebagai budak yang telah minggat kemudian ditemukan lagi. Sedangkan Nabi Yusuf diam saja karena ia merasa khawatir akan dibunuh oleh mereka. (Dan Allah Maha Mengetahui apa yang mereka kerjakan.)",[["وَجَآءَتْ","Dan datanglah"],["سَيَّارَةٌۭ","sebuah karavan"],["فَأَرْسَلُوا۟","dan mereka menghantar"],["وَارِدَهُمْ","laci air mereka"],["فَأَدْلَىٰ","kemudian dia mengecewakan"],["دَلْوَهُۥ ۖ","baldinya"],["قَالَ","Dia berkata"],["يَـٰبُشْرَىٰ","Wahai berita gembira"],["هَـٰذَا","Ini"],["غُلَـٰمٌۭ ۚ","(ialah) seorang budak lelaki"],["وَأَسَرُّوهُ","Dan mereka menyembunyikannya"],["بِضَـٰعَةًۭ ۚ","(sebagai) barang dagangan"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌۢ","Maha Mengetahui"],["بِمَا","tentang apa"],["يَعْمَلُونَ","mereka lakukan"]]],"1616":["(Dan mereka menjual Yusuf) orang-orang musafir itu membelinya dari tangan penimba air dan teman-temannya (dengan harga yang murah) kurang dari semestinya (yaitu hanya beberapa dirham saja) sekitar dua puluh atau dua puluh dua dirham saja (dan mereka) yakni saudara-saudara penimba air itu (merasa tidak tertarik hatinya kepada Yusuf) kemudian rombongan musafir itu membawa Yusuf ke negeri Mesir selanjutnya Nabi Yusuf dijual oleh orang yang membelinya dengan harga dua puluh dinar, dua pasang terompah dan dua buah baju.",[["وَشَرَوْهُ","Dan mereka menjualnya"],["بِثَمَنٍۭ","untuk harga"],["بَخْسٍۢ","sangat rendah"],["دَرَٰهِمَ","dirham"],["مَعْدُودَةٍۢ","sedikit"],["وَكَانُوا۟","dan mereka"],["فِيهِ","tentang dia"],["مِنَ","daripada"],["ٱلزَّٰهِدِينَ","mereka yang ingin berputus asa"]]],"1617":["(Dan orang Mesir yang membelinya berkata) dia bernama Qithfir Al-Aziz (kepada istrinya) yaitu Zulaikha (\"Berikanlah kepadanya tempat dan layanan yang baik) muliakanlah dia di antara kita (boleh jadi dia bermanfaat bagi kita atau kita pungut dia sebagai anak.\") disebutkan bahwa Qithfir Al-Aziz tidak mempunyai anak atau impoten. (Dan demikian pulalah) artinya sebagaimana Kami selamatkan dia dari pembunuhan dan sewaktu di dalam sumur serta Kami jadikan hati Al-Aziz merasa sayang kepadanya (Kami memberikan kedudukan yang baik kepada Yusuf di muka bumi) negeri Mesir sehingga sampai pada waktunya (dan agar Kami ajarkan kepadanya takwil mimpi) makna mimpi; lafal linu`allimahu diathafkan kepada fi`il yang keberadaannya diperkirakan dan berta`alluq kepada lafal makkannaa; artinya Kami ajarkan kepadanya makna mimpi sehingga ia menguasainya. Atau huruf wawu yang sebelum linu`allimahu ini adalah huruf tambahan. (Dan Allah berkuasa terhadap urusan-Nya) tidak ada sesuatu pun yang dapat menghalang-halangi-Nya (tetapi kebanyakan manusia) yang dimaksud adalah orang-orang kafir (tidak mengetahui) hal tersebut.",[["وَقَالَ","Dan berkata"],["ٱلَّذِى","orang yang"],["ٱشْتَرَىٰهُ","membelinya"],["مِن","daripada"],["مِّصْرَ","Mesir"],["لِٱمْرَأَتِهِۦٓ","kepada isterinya"],["أَكْرِمِى","Buat selesa"],["مَثْوَىٰهُ","penginapannya"],["عَسَىٰٓ","barangkali"],["أَن","bahawa"],["يَنفَعَنَآ","(dia) akan memberi manfaat kepada kita"],["أَوْ","atau"],["نَتَّخِذَهُۥ","kita akan ambil dia"],["وَلَدًۭا ۚ","(sebagai) anak lelaki"],["وَكَذَٰلِكَ","Dan dengan demikian"],["مَكَّنَّا","Kami menubuhkan"],["لِيُوسُفَ","Yusuf"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَلِنُعَلِّمَهُۥ","supaya Kami ajarkan kepadanya"],["مِن","(the) tafsiran"],["تَأْوِيلِ","(the) tafsiran"],["ٱلْأَحَادِيثِ ۚ","peristiwa"],["وَٱللَّهُ","Dan Allah"],["غَالِبٌ","(adalah) dominan"],["عَلَىٰٓ","atas"],["أَمْرِهِۦ","urusan dia"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَ","kebanyakannya"],["ٱلنَّاسِ","(daripada) rakyat"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"1618":["(Dan tatkala dia cukup dewasa) yaitu mencapai umur tiga puluh tahun atau tiga puluh tiga tahun (Kami berikan kepadanya hikmah) kebijaksanaan (dan ilmu) pengetahuan agama sebelum ia diangkat menjadi nabi. (Demikianlah) sebagaimana Kami berikan imbalan kepadanya (Kami memberi balasan kepada orang-orang yang berbuat baik) terhadap diri mereka sendiri.",[["وَلَمَّا","Dan apabila"],["بَلَغَ","dia sampai"],["أَشُدَّهُۥٓ","kematangannya"],["ءَاتَيْنَـٰهُ","Kami beri dia"],["حُكْمًۭا","kebijaksanaan"],["وَعِلْمًۭا ۚ","dan pengetahuan"],["وَكَذَٰلِكَ","Dan dengan demikian"],["نَجْزِى","Kami memberi ganjaran"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"1619":["(Dan wanita, yang Yusuf tinggal di rumahnya menggoda Yusuf) yaitu Zulaikha (untuk menundukkan dirinya kepadanya) yakni ia meminta kepada Yusuf supaya mau memenuhi kehendaknya (dan dia menutup pintu-pintu) rumah (seraya berkata) kepada Yusuf (\"Marilah ke sini.\") artinya kemarilah; huruf lam dari lafal haitalak bermakna tabyin atau untuk menjelaskan. Menurut qiraat dibaca dengan dikasrahkan huruf ha-nya, sehingga bacaannya menjadi hiitalak. Sedangkan menurut qiraat lainnya dapat dibaca haytulak dengan mendamahkan huruf ta-nya. (Yusuf berkata, \"Aku berlindung kepada Allah) artinya aku berlindung kepada Allah dari perbuatan itu (sesungguhnya dia) artinya orang yang telah membelinya (adalah tuanku) majikanku (telah memperlakukan aku dengan baik) telah berlaku baik terhadap diriku maka aku tidak akan mengkhianatinya dengan berlaku tidak baik terhadap istrinya (sesungguhnya) pada kenyataannya (orang-orang yang lalim tiada akan beruntung) yang dimaksud adalah orang-orang yang suka berzina.",[["وَرَٰوَدَتْهُ","Dan berusaha untuk menggodanya"],["ٱلَّتِى","dia yang"],["هُوَ","dia (adalah)"],["فِى","dalam"],["بَيْتِهَا","rumah dia"],["عَن","daripada"],["نَّفْسِهِۦ","dirinya"],["وَغَلَّقَتِ","Dan dia menutup"],["ٱلْأَبْوَٰبَ","pintu"],["وَقَالَتْ","dan dia berkata"],["هَيْتَ","Ayuh"],["لَكَ ۚ","kamu"],["قَالَ","Dia berkata"],["مَعَاذَ","Aku berlindung kepada Allah"],["ٱللَّهِ ۖ","Aku berlindung kepada Allah"],["إِنَّهُۥ","Sesungguhnya dia"],["رَبِّىٓ","(ialah) tuanku"],["أَحْسَنَ","(yang telah) membuat kebaikan"],["مَثْوَاىَ ۖ","penginapan aku"],["إِنَّهُۥ","Sesungguhnya"],["لَا","tidak"],["يُفْلِحُ","akan berjaya"],["ٱلظَّـٰلِمُونَ","orang yang zalim"]]],"1620":["(Sesungguhnya wanita itu telah mempunyai maksud terhadap Yusuf) artinya dia telah bermaksud terhadap Nabi Yusuf supaya menyetubuhinya (dan Yusuf pun bermaksud melakukannya pula dengan wanita itu) artinya Yusuf pun mempunyai keinginan yang sama (andaikata dia tidak melihat tanda dari Rabbnya) menurut Ibnu Abbas r.a. bahwa pada saat yang kritis itu tiba-tiba Nabi Yakub atau ayahnya tampak di hadapannya, lalu memukul dadanya sehingga keluarlah nafsu syahwat yang telah membara itu dari semua ujung-ujung jarinya. Jawab dari lafal laulaa ialah lajaama`ahaa; artinya niscaya Yusuf menyetubuhinya. (Demikianlah) Kami perlihatkan tanda kekuasaan-Ku kepadanya (agar Kami memalingkan daripadanya kemungkaran) perbuatan khianat (dan kekejian) perbuatan zina. (Sesungguhnya Yusuf itu termasuk hamba-hamba Kami yang terikhlas) dalam hal ketaatan. Menurut suatu qiraat dibaca mukhlishiin dengan dikasrahkan huruf lam-nya; artinya sama dengan lafal al-mukhtaariina atau orang-orang yang terpilih.",[["وَلَقَدْ","Dan sungguh"],["هَمَّتْ","dia memang berhajat"],["بِهِۦ ۖ","dia"],["وَهَمَّ","dan dia akan mahu"],["بِهَا","dia"],["لَوْلَآ","jika tidak"],["أَن","bahawa"],["رَّءَا","dia nampak"],["بُرْهَـٰنَ","buktinya"],["رَبِّهِۦ ۚ","(dari) Tuhannya"],["كَذَٰلِكَ","Demikianlah"],["لِنَصْرِفَ","yang dapat Kami hindari"],["عَنْهُ","daripada dia"],["ٱلسُّوٓءَ","yang jahat"],["وَٱلْفَحْشَآءَ ۚ","dan maksiat itu"],["إِنَّهُۥ","Sesungguhnya dia"],["مِنْ","(adalah) daripada"],["عِبَادِنَا","hamba kita"],["ٱلْمُخْلَصِينَ","yang ikhlas"]]],"1621":["(Dan keduanya berlomba-lomba menuju pintu) Yusuf segera lari menuju ke pintu rumah untuk melepaskan diri daripadanya. Sedangkan Zulaikha yang sudah kerasukan nafsu syahwatnya memegang baju bagian belakang Yusuf kemudian berupaya menariknya (dan robeklah) menjadi sobek (baju gamis Yusuf dari arah belakangnya dan kedua-duanya mendapati) menemukan (suami wanita itu) suami Zulaikha (di muka pintu) maka secara spontan Zulaikha membersihkan dirinya selanjutnya. (Wanita itu berkata, \"Tiadalah pembalasan terhadap orang yang bermaksud berbuat serong dengan istrimu) yakni berzina (selain dipenjarakan) ditahan di dalam penjara (atau dihukum dengan siksaan yang pedih?\") siksaan yang menyakitkan, dipukuli umpamanya.",[["وَٱسْتَبَقَا","Dan mereka berdua berlumba"],["ٱلْبَابَ","(ke) pintu"],["وَقَدَّتْ","dan dia mengoyakkan"],["قَمِيصَهُۥ","bajunya"],["مِن","daripada"],["دُبُرٍۢ","bahagian belakang"],["وَأَلْفَيَا","dan mereka berdua dapati"],["سَيِّدَهَا","suaminya"],["لَدَا","di"],["ٱلْبَابِ ۚ","pintu"],["قَالَتْ","Dia berkata"],["مَا","Apa"],["جَزَآءُ","(ialah) balasannya"],["مَنْ","(daripada satu) siapa"],["أَرَادَ","dimaksudkan"],["بِأَهْلِكَ","untuk isteri kamu"],["سُوٓءًا","jahat"],["إِلَّآ","kecuali"],["أَن","bahawa"],["يُسْجَنَ","dia dipenjarakan"],["أَوْ","atau"],["عَذَابٌ","azab"],["أَلِيمٌۭ","yang pedih"]]],"1622":["(Yusuf berkata) membela dirinya (\"Dia menggodaku untuk menundukkan diriku kepadanya,\" dan seorang saksi dari keluarga wanita itu memberikan kesaksiannya) sepupu Zulaikha. Tetapi menurut suatu riwayat disebutkan, bahwa saksi itu adalah bayi yang masih dalam ayunan. Kemudian saksi itu mengatakan (\"Jika baju gamisnya koyak di muka) pada bagian muka Yusuf (maka wanita itu benar dan Yusuf termasuk orang-orang yang dusta.\").",[["قَالَ","Dia berkata"],["هِىَ","dia"],["رَٰوَدَتْنِى","berusaha untuk memikat aku"],["عَن","tentang"],["نَّفْسِى ۚ","diri sendiri"],["وَشَهِدَ","Dan bersaksi"],["شَاهِدٌۭ","seorang saksi"],["مِّنْ","daripada"],["أَهْلِهَآ","keluarganya"],["إِن","Jika"],["كَانَ","[adalah]"],["قَمِيصُهُۥ","bajunya"],["قُدَّ","(adalah) koyak"],["مِن","daripada"],["قُبُلٍۢ","bahagian hadapan"],["فَصَدَقَتْ","maka dia telah bercakap benar"],["وَهُوَ","dan dia"],["مِنَ","(adalah) daripada"],["ٱلْكَـٰذِبِينَ","pendusta"]]],"1623":["(\"Dan jika baju gamisnya koyak di belakangnya) pada bagian belakang Yusuf (maka wanita itulah yang dusta dan Yusuf termasuk orang-orang yang benar.\")",[["وَإِن","Tetapi jika"],["كَانَ","[adalah]"],["قَمِيصُهُۥ","bajunya"],["قُدَّ","(adalah) koyak"],["مِن","daripada"],["دُبُرٍۢ","(the) belakang"],["فَكَذَبَتْ","maka dia telah berbohong"],["وَهُوَ","dan dia"],["مِنَ","(adalah) daripada"],["ٱلصَّـٰدِقِينَ","yang benar"]]],"1624":["(Maka tatkala suami wanita itu melihat) suami Zulaikha (baju gamis Yusuf koyak di belakang berkatalah dia, \"Sesungguhnya kejadian itu) yang kamu katakan, apakah pembalasan terhadap orang yang bermaksud memperkosa istrimu (adalah di antara tipu daya kalian) hai kaum wanita (sesungguhnya tipu daya kalian adalah besar.\").",[["فَلَمَّا","Maka apabila"],["رَءَا","dia nampak"],["قَمِيصَهُۥ","bajunya"],["قُدَّ","koyak"],["مِن","daripada"],["دُبُرٍۢ","(the) belakang"],["قَالَ","dia berkata"],["إِنَّهُۥ","Sesungguhnya, ia"],["مِن","(adalah) daripada"],["كَيْدِكُنَّ ۖ","plot kamu"],["إِنَّ","Sesungguhnya"],["كَيْدَكُنَّ","plot kamu"],["عَظِيمٌۭ","(adalah) hebat"]]],"1625":["Selanjutnya suami wanita itu berkata, \"Hai (Yusuf! Berpalinglah dari ini) dari peristiwa ini, lupakanlah supaya jangan tersiar beritanya (dan kamu mohon ampunlah) hai Zulaikha istriku (atas dosamu itu, karena kamu sesungguhnya termasuk orang-orang yang berbuat salah.\") yakni orang-orang yang telah berbuat dosa. Akan tetapi peristiwa itu beritanya tidak dapat disembunyikan lalu tersiarlah di kalangan masyarakat.",[["يُوسُفُ","Yusuf"],["أَعْرِضْ","berpaling"],["عَنْ","daripada"],["هَـٰذَا ۚ","ini"],["وَٱسْتَغْفِرِى","Dan minta ampun"],["لِذَنۢبِكِ ۖ","kerana dosamu"],["إِنَّكِ","Sesungguhnya kamu"],["كُنتِ","adalah"],["مِنَ","daripada"],["ٱلْخَاطِـِٔينَ","yang berdosa"]]],"1626":["(Dan wanita-wanita di kota berkata) yaitu kota Mesir (\"Istri Aziz menggoda bujangnya) yaitu hamba sahaya lakinya (untuk menundukkan dirinya menuruti kemauannya, sesungguhnya cintanya kepada bujangnya itu adalah sangat mendalam) lafal hubban berkedudukan menjadi tamyiz; artinya cinta Zulaikha terhadap Yusuf telah merasup ke dalam lubuk hatinya. (Sesungguhnya kami memandangnya dalam kesesatan yang nyata.\") jelas sesat karena mencintai hambanya sendiri.",[["۞ وَقَالَ","Dan berkata"],["نِسْوَةٌۭ","perempuan"],["فِى","dalam"],["ٱلْمَدِينَةِ","bandar itu"],["ٱمْرَأَتُ","Isteri kepada"],["ٱلْعَزِيزِ","Aziz"],["تُرَٰوِدُ","(sedang) ingin memikat"],["فَتَىٰهَا","budak budak dia"],["عَن","tentang"],["نَّفْسِهِۦ ۖ","dirinya sendiri"],["قَدْ","sesungguhnya"],["شَغَفَهَا","dia telah membangkitkan semangatnya"],["حُبًّا ۖ","(dengan) cinta"],["إِنَّا","Sesungguhnya kami"],["لَنَرَىٰهَا","[kita] pasti melihatnya"],["فِى","dalam"],["ضَلَـٰلٍۢ","satu kesilapan"],["مُّبِينٍۢ","yang nyata"]]],"1627":["(Maka tatkala wanita itu mendengar cercaan mereka) pergunjingan mereka terhadap dirinya (diundangnyalah wanita-wanita itu dan disediakannya) Zulaikha mempersiapkan (bagi mereka makanan) yang harus dipotong terlebih dahulu dengan pisau dan beralaskan pada talenan (dan diberikannya) Zulaikha memberikan (kepada masing-masing mereka sebuah pisau, kemudian dia berkata) kepada Yusuf (\"Keluarlah kepada mereka.\" Maka tatkala wanita-wanita itu melihatnya, mereka merasa kagum terhadapnya) kepada ketampanan dan keelokan rupanya (dan mereka melukai jari tangannya) dengan pisau-pisau yang mereka pegang itu tanpa mereka sadari dan tanpa merasa sakit karena kekaguman mereka terhadap ketampanan Yusuf (dan berkatalah mereka, \"Maha Sempurna Allah) dimaksud sebagai ungkapan memahasucikan Allah swt. (ini bukanlah) artinya Nabi Yusuf ini (manusia tetapi) melainkan (ia adalah malaikat yang mulia.\") mengingat ketampanan dan keelokan rupanya hal ini tidak akan ditemui pada manusia. Di dalam sebuah hadis disebutkan bahwasanya Nabi Yusuf telah dianugerahi separuh dari ketampanan dan keelokan rupa.",[["فَلَمَّا","Maka apabila"],["سَمِعَتْ","dia dengar"],["بِمَكْرِهِنَّ","rancangan mereka"],["أَرْسَلَتْ","dia hantar"],["إِلَيْهِنَّ","bagi mereka"],["وَأَعْتَدَتْ","dan dia bersiap"],["لَهُنَّ","bagi mereka"],["مُتَّكَـًۭٔا","jamuan"],["وَءَاتَتْ","dan dia memberi"],["كُلَّ","setiap satu"],["وَٰحِدَةٍۢ","satu"],["مِّنْهُنَّ","daripada mereka"],["سِكِّينًۭا","sebilah pisau"],["وَقَالَتِ","dan dia berkata"],["ٱخْرُجْ","Keluarlah"],["عَلَيْهِنَّ ۖ","sebelum mereka"],["فَلَمَّا","Kemudian apabila"],["رَأَيْنَهُۥٓ","mereka melihatnya"],["أَكْبَرْنَهُۥ","mereka sangat mengaguminya"],["وَقَطَّعْنَ","dan potong"],["أَيْدِيَهُنَّ","tangan mereka"],["وَقُلْنَ","mereka berkata"],["حَـٰشَ","Melarang"],["لِلَّهِ","Allah"],["مَا","tidak"],["هَـٰذَا","(adalah) ini"],["بَشَرًا","seorang lelaki"],["إِنْ","tidak"],["هَـٰذَآ","(adalah) ini"],["إِلَّا","tetapi"],["مَلَكٌۭ","seorang malaikat"],["كَرِيمٌۭ","mulia"]]],"1628":["(Wanita itu berkata) yang dimaksud adalah istri Al-Aziz sewaktu ia melihat apa yang terjadi pada diri mereka (\"Itulah dia) dialah (orangnya yang kalian cela aku karena tertarik kepadanya) karena aku mencintainya. Kalimat ini merupakan penjelasan tentang alasan Zulaikha (dan sesungguhnya aku telah menggoda dia untuk menundukkan dirinya kepadaku akan tetapi ia mempertahankan dirinya) menolak. (Dan sesungguhnya jika dia tidak menaati apa yang aku perintahkan kepadanya) untuk dilakukannya (niscaya dia akan dipenjarakan dan dia akan termasuk golongan orang-orang yang hina\") orang-orang yang tidak terpandang. Maka wanita-wanita itu berkata kepada Yusuf, \"Turutilah kemauan tuan wanitamu ini.\"",[["قَالَتْ","Dia berkata"],["فَذَٰلِكُنَّ","Itu"],["ٱلَّذِى","(ialah) yang satu"],["لُمْتُنَّنِى","kamu salahkan aku"],["فِيهِ ۖ","tentang dia"],["وَلَقَدْ","Dan sungguh"],["رَٰوَدتُّهُۥ","Aku cuba memikatnya"],["عَن","[dari]"],["نَّفْسِهِۦ","[sendiri]"],["فَٱسْتَعْصَمَ ۖ","tetapi dia menyelamatkan dirinya"],["وَلَئِن","dan jika"],["لَّمْ","tidak"],["يَفْعَلْ","dia buat"],["مَآ","apa"],["ءَامُرُهُۥ","aku pesan dia"],["لَيُسْجَنَنَّ","pasti, dia akan dipenjarakan"],["وَلَيَكُونًۭا","dan pasti akan jadi"],["مِّنَ","daripada"],["ٱلصَّـٰغِرِينَ","mereka yang dihina"]]],"1629":["(Yusuf berkata, \"Wahai Rabbku! Penjara lebih aku sukai daripada memenuhi ajakan mereka kepadaku. Dan jika tidak Engkau hindarkan aku dari tipu daya mereka, tentu aku akan cenderung untuk) memenuhi (kemauan mereka dan tentulah aku) menjadi (termasuk orang-orang yang bodoh\") yakni orang-orang yang berbuat dosa. Makna yang dimaksud adalah berdoa. Pada ayat selanjutnya Allah berfirman:",[["قَالَ","Dia berkata"],["رَبِّ","Tuhanku"],["ٱلسِّجْنُ","penjara itu"],["أَحَبُّ","(adalah) lebih sayang"],["إِلَىَّ","kepada aku"],["مِمَّا","daripada apa"],["يَدْعُونَنِىٓ","mereka menjemput aku"],["إِلَيْهِ ۖ","kepadanya"],["وَإِلَّا","Dan melainkan"],["تَصْرِفْ","Kamu berpaling"],["عَنِّى","daripada aku"],["كَيْدَهُنَّ","plot mereka"],["أَصْبُ","Aku mungkin condong"],["إِلَيْهِنَّ","terhadap mereka"],["وَأَكُن","dan [aku] menjadi"],["مِّنَ","daripada"],["ٱلْجَـٰهِلِينَ","yang jahil"]]],"1630":["(Maka Rabbnya memperkenankan doa Yusuf) permintaannya (dan Dia menghindarkan Yusuf dari tipu daya mereka. Sesungguhnya Dialah Yang Maha Mendengar) semua pembicaraan (lagi Maha Mengetahui) semua pekerjaan.",[["فَٱسْتَجَابَ","Maka dijawab"],["لَهُۥ","kepadanya"],["رَبُّهُۥ","Tuhannya"],["فَصَرَفَ","dan berpaling"],["عَنْهُ","daripada dia"],["كَيْدَهُنَّ ۚ","plot mereka"],["إِنَّهُۥ","Sesungguhnya, [Dia]"],["هُوَ","Dia"],["ٱلسَّمِيعُ","(adalah) Yang Maha Mendengar"],["ٱلْعَلِيمُ","Maha Mengetahui"]]],"1631":["(Kemudian timbul pikiran) tampak nyata (pada mereka setelah melihat tanda-tanda) yang menunjukkan kebersihan diri Nabi Yusuf, yaitu memenjarakannya. Hal ini terbukti dengan adanya penjelasan pada ayat selanjutnya (bahwa mereka harus memenjarakannya sampai) hingga (sesuatu waktu) semua yang hadir setuju dengan pendapat ini akhirnya Nabi Yusuf dipenjarakan.",[["ثُمَّ","Kemudian"],["بَدَا","(ia) muncul"],["لَهُم","kepada mereka"],["مِّنۢ","selepas"],["بَعْدِ","selepas"],["مَا","[apa]"],["رَأَوُا۟","mereka telah melihat"],["ٱلْـَٔايَـٰتِ","tanda-tanda"],["لَيَسْجُنُنَّهُۥ","nescaya mereka harus memenjarakannya"],["حَتَّىٰ","sehingga"],["حِينٍۢ","suatu masa"]]],"1632":["(Dan bersama dengan dia masuk pula ke dalam penjara dua orang pemuda) dua orang pelayan raja; salah seorang di antaranya bekas atau mantan penyuguh minumannya dan yang seorang lainnya mantan penyuguh makanannya. Kemudian mereka berdua melihat bahwa Nabi Yusuf pandai menakwilkan arti mimpi lalu keduanya sepakat untuk mengujinya. (Berkatalah salah seorang di antara keduanya) yaitu mantan penyuguh minuman raja (\"Sesungguhnya aku bermimpi bahwa aku memeras khamar.\") yang dimaksud adalah memeras anggur (Dan yang lainnya berkata) yaitu mantan penyuguh hidangan raja (\"Sesungguhnya aku bermimpi bahwa aku membawa roti di atas kepalaku, sebagiannya dimakan burung. Berikanlah kepada kami) ceritakanlah kepada kami (takbirnya) arti impian itu (sesungguhnya kami memandang kamu termasuk orang-orang yang pandai menakwilkan mimpi.\").",[["وَدَخَلَ","Dan masuk"],["مَعَهُ","dengan dia"],["ٱلسِّجْنَ","(dalam) penjara"],["فَتَيَانِ ۖ","dua orang pemuda"],["قَالَ","Berkata"],["أَحَدُهُمَآ","salah seorang daripada mereka"],["إِنِّىٓ","Sesungguhnya aku"],["أَرَىٰنِىٓ","[Aku] melihat diri aku sendiri"],["أَعْصِرُ","menekan"],["خَمْرًۭا ۖ","wain"],["وَقَالَ","Dan berkata"],["ٱلْـَٔاخَرُ","yang lain"],["إِنِّىٓ","Sesungguhnya aku"],["أَرَىٰنِىٓ","[Aku] melihat diri aku sendiri"],["أَحْمِلُ","[Aku] membawa"],["فَوْقَ","atas"],["رَأْسِى","kepala aku"],["خُبْزًۭا","roti"],["تَأْكُلُ","(sedang) makan"],["ٱلطَّيْرُ","burung-burung itu"],["مِنْهُ ۖ","daripadanya"],["نَبِّئْنَا","Maklumkan kepada kami"],["بِتَأْوِيلِهِۦٓ ۖ","daripada tafsirannya"],["إِنَّا","sesungguhnya, kita"],["نَرَىٰكَ","[kami] jumpa kamu"],["مِنَ","daripada"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"1633":["(Yusuf berkata) kepada kedua pemuda itu seraya menegaskan, bahwa dirinya pandai di dalam menakbirkan arti mimpi (\"Tidak disampaikan kepada kamu berdua makanan yang akan diberikan kepadamu) di dalam mimpi kamu berdua (melainkan aku telah dapat menerangkan takwilnya) apa yang akan terjadi di alam kenyataan (sebelum makanan itu sampai kepada kamu berdua) sebelum kenyataan mimpi itu menimpa kalian berdua. (Yang demikian itu adalah sebagian dari apa yang diajarkan kepadaku oleh Rabbku) di dalam ungkapan ini terkandung pengertian yang menganjurkan supaya mereka berdua beriman kepada Allah. Selanjutnya hal ini diperkuat oleh perkataannya lagi, yaitu: (Sesungguhnya aku telah meninggalkan tuntunan) agama (orang-orang yang tidak beriman kepada Allah sedangkan mereka terhadap hari kiamat benar-benar) sungguh (ingkar\").",[["قَالَ","Dia berkata"],["لَا","Tidak"],["يَأْتِيكُمَا","(akan) datang kepada kamu berdua"],["طَعَامٌۭ","makanan"],["تُرْزَقَانِهِۦٓ","kamu disediakan dengan"],["إِلَّا","tetapi"],["نَبَّأْتُكُمَا","Aku akan maklumkan kepada kamu berdua"],["بِتَأْوِيلِهِۦ","daripada tafsirannya"],["قَبْلَ","sebelum"],["أَن","[bahawa]"],["يَأْتِيَكُمَا ۚ","[ia] datang kepada kamu berdua"],["ذَٰلِكُمَا","Itu"],["مِمَّا","(adalah) dari apa"],["عَلَّمَنِى","telah mengajar aku"],["رَبِّىٓ ۚ","Tuhanku"],["إِنِّى","Sesungguhnya aku"],["تَرَكْتُ","[Aku] tinggalkan"],["مِلَّةَ","(agama)."],["قَوْمٍۢ","(dari) suatu kaum"],["لَّا","tidak"],["يُؤْمِنُونَ","mereka beriman"],["بِٱللَّهِ","kepada Allah"],["وَهُم","dan mereka"],["بِٱلْـَٔاخِرَةِ","di akhirat"],["هُمْ","[mereka]"],["كَـٰفِرُونَ","(adalah) orang-orang kafir"]]],"1634":["(\"Dan aku mengikuti agama bapak-bapakku, yaitu Ibrahim, Ishak dan Yakub. Tiadalah patut) tidak pantas (bagi kami mempersekutukan Allah dengan) huruf min di sini zaidah (sesuatu pun) karena kami selalu memelihara (yang demikian itu) yakni ajaran tauhid (adalah karunia Allah kepada kami dan kepada manusia seluruhnya tetapi kebanyakan manusia itu) dimaksud adalah orang-orang kafir (tidak mensyukuri.\") terhadap Allah; lalu mereka menyekutukan-Nya. Kemudian Nabi Yusuf menjelaskan ajakannya kepada mereka berdua agar keduanya beriman seraya berkata:",[["وَٱتَّبَعْتُ","Dan aku ikut"],["مِلَّةَ","(agama)."],["ءَابَآءِىٓ","(dari) nenek moyangku"],["إِبْرَٰهِيمَ","Ibrahim"],["وَإِسْحَـٰقَ","dan Ishak"],["وَيَعْقُوبَ ۚ","dan Yaqub"],["مَا","Tidak"],["كَانَ","adalah"],["لَنَآ","bagi kami"],["أَن","bahawa"],["نُّشْرِكَ","kita bergaul"],["بِٱللَّهِ","dengan Allah"],["مِن","sebarang"],["شَىْءٍۢ ۚ","perkara"],["ذَٰلِكَ","Itu"],["مِن","(adalah) daripada"],["فَضْلِ","(yang) Rahmat"],["ٱللَّهِ","(milik) Allah"],["عَلَيْنَا","atas kita"],["وَعَلَى","dan seterusnya"],["ٱلنَّاسِ","umat manusia"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَ","kebanyakannya"],["ٱلنَّاسِ","(daripada) lelaki"],["لَا","(adalah) tidak"],["يَشْكُرُونَ","bersyukur"]]],"1635":["(\"Hai kedua temanku) yang satu tempat tinggal (dalam penjara! Manakah yang baik tuhan yang bermacam-macam itu ataukah Allah Yang Maha Esa lagi Maha Perkasa?\") pilihlah! Istifham atau kata tanya di sini mengandung pengertian taqrir atau menetapkan.",[["يَـٰصَـٰحِبَىِ","Wahai dua sahabatku"],["ٱلسِّجْنِ","(dari) penjara"],["ءَأَرْبَابٌۭ","Adakah tuan"],["مُّتَفَرِّقُونَ","berasingan"],["خَيْرٌ","lebih baik"],["أَمِ","atau"],["ٱللَّهُ","Allah"],["ٱلْوَٰحِدُ","yang Satu"],["ٱلْقَهَّارُ","yang tak tertahan"]]],"1636":["(\"Kamu berdua tidak menyembah yang selain-Nya) selain Allah (melainkan hanya menyembah nama-nama yang dibuat-buat) yaitu kalian namakan mereka berhala-berhala (oleh kalian dan nenek moyang kalian sendiri, Allah tidak menurunkan tentang nama-nama itu) untuk disembah (suatu keterangan pun) hujah dan argumentasi. (Tiada lain) tiadalah (keputusan itu) kepastian itu (hanya kepunyaan Allah) semata (Dia telah memerintahkan agar kalian tidak menyembah selain Dia. Itulah) yakni agama tauhid itulah (agama yang lurus) agama yang mustaqim (tetapi kebanyakan manusia) orang-orang kafir (tidak mengetahui.\") apa yang bakal menimpa mereka, yaitu berupa azab; mereka benar-benar orang-orang yang menyekutukan-Nya.",[["مَا","Tidak"],["تَعْبُدُونَ","kamu menyembah"],["مِن","selain Dia"],["دُونِهِۦٓ","selain Dia"],["إِلَّآ","tetapi"],["أَسْمَآءًۭ","nama"],["سَمَّيْتُمُوهَآ","yang telah kamu namakan mereka"],["أَنتُمْ","kamu"],["وَءَابَآؤُكُم","dan nenek moyang kamu"],["مَّآ","tidak"],["أَنزَلَ","(telah) diturunkan"],["ٱللَّهُ","Allah"],["بِهَا","baginya"],["مِن","sebarang"],["سُلْطَـٰنٍ ۚ","pihak berkuasa"],["إِنِ","Tidak"],["ٱلْحُكْمُ","(ialah) perintah"],["إِلَّا","tetapi"],["لِلَّهِ ۚ","kerana Allah"],["أَمَرَ","Dia telah memerintahkan"],["أَلَّا","itu tidak"],["تَعْبُدُوٓا۟","kamu menyembah"],["إِلَّآ","tetapi"],["إِيَّاهُ ۚ","Dia sahaja"],["ذَٰلِكَ","Itu"],["ٱلدِّينُ","(ialah) agama"],["ٱلْقَيِّمُ","yang betul"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَ","kebanyakannya"],["ٱلنَّاسِ","[the] lelaki"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"1637":["(\"Hai kedua temanku dalam penjara! Adapun salah seorang di antara kamu berdua) yang dimaksud adalah mantan penyuguh minuman raja; maka setelah tiga hari kemudian ia akan keluar dari penjara ini (akan memberi minum tuannya) rajanya (dengan khamar) sebagaimana biasa (dan adapun yang seorang lain) ia bakal keluar dari penjara ini setelah tiga hari (maka ia akan disalib, lalu burung memakan sebagian dari kepalanya) itulah makna mimpi kalian berdua. Kemudian keduanya menjawab, \"Kami sebenarnya tidak bermimpi melihat apa-apa.\" Nabi Yusuf berkata: (\"Telah diputuskan perkara yang kamu berdua menanyakannya.\") yang kamu berdua telah menanyakan perihalnya, apakah kamu berdua mempercayainya atau tidak, itu terserah.",[["يَـٰصَـٰحِبَىِ","Wahai dua sahabatku"],["ٱلسِّجْنِ","(dari) penjara"],["أَمَّآ","Adapun"],["أَحَدُكُمَا","salah seorang daripada kamu"],["فَيَسْقِى","dia akan memberi minum"],["رَبَّهُۥ","(kepada) tuannya"],["خَمْرًۭا ۖ","wain"],["وَأَمَّا","dan bagi"],["ٱلْـَٔاخَرُ","yang lain"],["فَيُصْلَبُ","dia akan disalib"],["فَتَأْكُلُ","dan akan makan"],["ٱلطَّيْرُ","burung-burung itu"],["مِن","daripada"],["رَّأْسِهِۦ ۚ","kepalanya"],["قُضِىَ","Telah diputuskan"],["ٱلْأَمْرُ","perkara itu"],["ٱلَّذِى","tentang yang mana"],["فِيهِ","tentang yang mana"],["تَسْتَفْتِيَانِ","kamu berdua bertanya"]]],"1638":["(Dan Yusuf berkata kepada orang yang diketahuinya) yang telah ia yakini (akan selamat di antara mereka berdua) yaitu mantan penyuguh minum raja (\"Jelaskanlah keadaanku kepada tuanmu\") yaitu kepada rajamu, bahwa sesungguhnya di dalam penjara ini terdapat seorang pemuda yang ditahan secara lalim, kemudian penyuguh minuman itu dikeluarkan dari penjara. (Maka ia dijadikan lupa) orang yang dimaksud adalah mantan penyuguh minuman (oleh setan menceritakan) tentang Nabi Yusuf (kepada tuannya. Karena itu tetaplah dia) Nabi Yusuf tetap tinggal (dalam penjara beberapa tahun lamanya) menurut suatu pendapat tujuh tahun dan menurut pendapat yang lain dua belas tahun.",[["وَقَالَ","Dan dia berkata"],["لِلَّذِى","kepada orang yang"],["ظَنَّ","fikirnya"],["أَنَّهُۥ","bahawa dia"],["نَاجٍۢ","(akan) diselamatkan"],["مِّنْهُمَا","daripada mereka berdua"],["ٱذْكُرْنِى","Sebut aku"],["عِندَ","kepada"],["رَبِّكَ","tuan kamu"],["فَأَنسَىٰهُ","Tapi membuatkan dia lupa"],["ٱلشَّيْطَـٰنُ","syaitan"],["ذِكْرَ","(the) sebutan"],["رَبِّهِۦ","(kepada) tuannya"],["فَلَبِثَ","jadi dia kekal"],["فِى","dalam"],["ٱلسِّجْنِ","penjara itu"],["بِضْعَ","beberapa"],["سِنِينَ","tahun"]]],"1639":["(Raja berkata) raja negeri Mesir, yaitu Ar-Rayyan bin Walid (\"Sesungguhnya aku bermimpi melihat) fi'il mudhari' di sini bermakna fi'il madhi (tujuh ekor sapi betina yang gemuk-gemuk dimakan oleh) ditelan oleh (tujuh ekor) sapi (sapi betina yang kurus-kurus) lafal `ijaaf adalah bentuk jamak dari kata tunggal `ajfau, artinya sapi betina yang kurus (dan tujuh bulir gandum yang hijau dan yang lainnya) yakni tujuh bulir pula (kering) telah melingkar pada tujuh bulir yang hijau itu dan menutupinya. (Hai orang-orang yang terkemuka, terangkanlah kepadaku tentang takbir mimpiku itu) jelaskanlah kepadaku makna mimpiku itu (jika kalian dapat menakbirkan mimpi.\") ceritakanlah maknanya kepadaku sekarang juga.",[["وَقَالَ","Dan berkata"],["ٱلْمَلِكُ","raja"],["إِنِّىٓ","Sesungguhnya aku"],["أَرَىٰ","[Aku] telah melihat"],["سَبْعَ","tujuh"],["بَقَرَٰتٍۢ","lembu"],["سِمَانٍۢ","gemuk"],["يَأْكُلُهُنَّ","memakannya"],["سَبْعٌ","tujuh"],["عِجَافٌۭ","yang kurus"],["وَسَبْعَ","dan tujuh"],["سُنۢبُلَـٰتٍ","telinga (jagung)"],["خُضْرٍۢ","hijau"],["وَأُخَرَ","dan lain-lain"],["يَابِسَـٰتٍۢ ۖ","kering"],["يَـٰٓأَيُّهَا","Wahai"],["ٱلْمَلَأُ","ketua-ketua"],["أَفْتُونِى","Jelaskan kepada aku"],["فِى","tentang"],["رُءْيَـٰىَ","penglihatan aku"],["إِن","jika"],["كُنتُمْ","kamu boleh"],["لِلرُّءْيَا","daripada penglihatan"],["تَعْبُرُونَ","mentafsir"]]],"1640":["(Mereka menjawab,) \"itu (adalah mimpi-mimpi yang kosong) mimpi yang tidak ada artinya (dan kami sekali-kali tidak mengetahui tentang mentakwilkan mimpi.\")",[["قَالُوٓا۟","Mereka berkata"],["أَضْغَـٰثُ","keliru"],["أَحْلَـٰمٍۢ ۖ","mimpi"],["وَمَا","dan bukan"],["نَحْنُ","kita"],["بِتَأْوِيلِ","(ada) dalam tafsiran"],["ٱلْأَحْلَـٰمِ","(dari) impian"],["بِعَـٰلِمِينَ","dipelajari"]]],"1641":["(Dan berkatalah orang yang selamat di antara mereka berdua) yaitu salah satu di antara kedua teman sepenjara Nabi Yusuf, mantan penyuguh minuman raja (dan ia teringat) kepada Nabi Yusuf. Lafal waddakara pada asalnya ialah tadzakkara, kemudian huruf ta diganti dal, selanjutnya huruf dzal asal diidghamkan kepada dal sehingga jadilah iddakara, artinya sama dengan lafal tadzakkara, yaitu ingat (sesudah beberapa waktu lamanya) setelah Nabi Yusuf tinggal beberapa lama di penjara, lalu mantan penyuguh minuman raja itu berkata (\"Aku akan memberitahukan kepada kalian tentang orang yang pandai menakwilkan mimpi itu, maka utuslah aku kepadanya.\") lalu mereka mengirimkan orang itu kepada orang yang dimaksudnya; kemudian orang itu mendatangi Nabi Yusuf seraya berkata kepadanya:",[["وَقَالَ","Tetapi berkata"],["ٱلَّذِى","orang yang"],["نَجَا","telah diselamatkan"],["مِنْهُمَا","daripada keduanya"],["وَٱدَّكَرَ","dan teringat"],["بَعْدَ","selepas"],["أُمَّةٍ","tempoh"],["أَنَا۠","aku"],["أُنَبِّئُكُم","[Aku] akan memberitahu kamu"],["بِتَأْوِيلِهِۦ","daripada tafsirannya"],["فَأَرْسِلُونِ","maka hantarlah aku"]]],"1642":["\"Hai (Yusuf, hai orang yang amat dipercaya!) artinya orang yang jujur (Terangkanlah kepada kami tentang tujuh ekor sapi betina yang gemuk-gemuk yang dimakan oleh tujuh ekor sapi betina yang kurus-kurus dan tujuh bulir gandum yang hijau dan tujuh lainnya yang kering agar aku kembali kepada orang-orang itu) yaitu raja dan pembantu-pembantunya (agar mereka mengetahui\") takwil mimpi itu.",[["يُوسُفُ","Yusuf"],["أَيُّهَا","Wahai"],["ٱلصِّدِّيقُ","yang benar"],["أَفْتِنَا","Jelaskan kepada kami"],["فِى","tentang"],["سَبْعِ","(yang) tujuh"],["بَقَرَٰتٍۢ","lembu"],["سِمَانٍۢ","gemuk"],["يَأْكُلُهُنَّ","memakannya"],["سَبْعٌ","tujuh"],["عِجَافٌۭ","yang kurus"],["وَسَبْعِ","dan tujuh"],["سُنۢبُلَـٰتٍ","telinga (jagung)"],["خُضْرٍۢ","hijau"],["وَأُخَرَ","dan lain-lain"],["يَابِسَـٰتٍۢ","kering"],["لَّعَلِّىٓ","yang aku boleh"],["أَرْجِعُ","kembali"],["إِلَى","kepada"],["ٱلنَّاسِ","manusia"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَعْلَمُونَ","mengetahui"]]],"1643":["(Yusuf berkata, \"Supaya kalian bertanam) artinya tanamlah oleh kalian (tujuh tahun lamanya sebagaimana biasa) yakni secara terus-menerus; hal ini merupakan takbir daripada tujuh ekor sapi betina yang gemuk-gemuk (maka apa yang kalian panen hendaklah kalian biarkan) biarkanlah ia (dibulirnya) supaya jangan rusak (kecuali sedikit untuk kalian makan) maka boleh kalian menumbuknya.",[["قَالَ","Dia berkata"],["تَزْرَعُونَ","Kamu akan menyemai"],["سَبْعَ","(untuk) tujuh"],["سِنِينَ","tahun"],["دَأَبًۭا","seperti biasa"],["فَمَا","dan yang"],["حَصَدتُّمْ","kamu tuai"],["فَذَرُوهُ","jadi tinggalkan"],["فِى","dalam"],["سُنۢبُلِهِۦٓ","telinganya"],["إِلَّا","kecuali"],["قَلِيلًۭا","sedikit"],["مِّمَّا","dari mana"],["تَأْكُلُونَ","kamu (akan) makan"]]],"1644":["(Kemudian sesudah itu akan datang) artinya sesudah tujuh musim yang subur-subur itu (tujuh tahun yang amat sulit) kekeringan dan masa sulit; hal ini merupakan takbir daripada tujuh ekor sapi betina yang kurus-kurus (yang menghabiskan apa yang kalian simpan untuk menghadapinya) akan memakan semua biji-bijian dari hasil panen yang selama tujuh tahun yang subur itu; dimaksud kalian memakannya selama tujuh tahun paceklik itu (kecuali sedikit dari yang kalian simpan) artinya simpanan yang sedikit itu jadikanlah sebagai bibit.",[["ثُمَّ","Kemudian"],["يَأْتِى","akan datang"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["ذَٰلِكَ","bahawa"],["سَبْعٌۭ","tujuh"],["شِدَادٌۭ","keras (tahun)"],["يَأْكُلْنَ","(yang akan) memakan"],["مَا","apa"],["قَدَّمْتُمْ","kamu maju"],["لَهُنَّ","bagi mereka"],["إِلَّا","kecuali"],["قَلِيلًۭا","sedikit"],["مِّمَّا","tentang apa"],["تُحْصِنُونَ","kamu (akan) menyimpan"]]],"1645":["(Kemudian setelah itu akan datang) yaitu sesudah tujuh tahun musim paceklik itu (tahun yang padanya manusia diberi hujan) yakni hujan yang cukup (dan di masa itu mereka memeras anggur.\") dapat memeras anggur dan buah-buahan lainnya karena suburnya musim.",[["ثُمَّ","Kemudian"],["يَأْتِى","akan datang"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["ذَٰلِكَ","bahawa"],["عَامٌۭ","setahun"],["فِيهِ","di dalamnya"],["يُغَاثُ","akan diberikan hujan yang lebat"],["ٱلنَّاسُ","manusia"],["وَفِيهِ","dan di dalamnya"],["يَعْصِرُونَ","mereka akan menekan"]]],"1646":["(Raja berkata) ketika utusannya datang dan mengisahkan kepadanya tentang takbir mimpinya itu (\"Bawalah dia kepadaku.\") bawalah orang yang telah menakbirkannya itu. (Maka tatkala datang kepadanya) kepada Nabi Yusuf (utusan raja itu) kemudian utusan itu meminta kepadanya supaya keluar dari penjara (berkatalah Yusuf) dengan maksud untuk membersihkan dirinya (\"Kembalilah kepada tuanmu dan tanyakanlah kepadanya) dimaksud supaya utusan raja itu menanyakan kepada raja (bagaimana) halnya (dengan wanita-wanita yang telah melukai tangannya. Sesungguhnya Rabbku) Tuhanku (Maha Mengetahui tipu daya mereka.\") kemudian utusan itu kembali, lalu ia menceritakan semuanya kepada sang raja, maka sang raja mengumpulkan wanita-wanita itu.",[["وَقَالَ","Dan berkata"],["ٱلْمَلِكُ","raja"],["ٱئْتُونِى","Bawa dia kepada aku"],["بِهِۦ ۖ","Bawa dia kepada aku"],["فَلَمَّا","Tetapi apabila"],["جَآءَهُ","datang kepadanya"],["ٱلرَّسُولُ","utusan itu"],["قَالَ","dia berkata"],["ٱرْجِعْ","Kembali"],["إِلَىٰ","kepada"],["رَبِّكَ","tuan tuan"],["فَسْـَٔلْهُ","dan tanya dia"],["مَا","apa"],["بَالُ","(adalah) kes"],["ٱلنِّسْوَةِ","(dari) wanita"],["ٱلَّـٰتِى","yang"],["قَطَّعْنَ","potong"],["أَيْدِيَهُنَّ ۚ","tangan mereka"],["إِنَّ","Sesungguhnya"],["رَبِّى","Tuhanku"],["بِكَيْدِهِنَّ","plot mereka"],["عَلِيمٌۭ","Maha Mengetahui"]]],"1647":["(Raja berkata, \"Bagaimana keadaan kalian) bagaimana perihal kalian (ketika kalian menggoda Yusuf untuk menundukkan dirinya kepada kemauan kalian?\") apakah kalian memandang Yusuf mempunyai kecenderungan pada permintaan kalian itu? (Mereka berkata, \"Maha Sempurna Allah, kami tiada mengetahui sesuatu keburukan daripadanya.\" Berkatalah istri Al-Aziz, \"Sekarang jelaslah) menjadi gamblanglah (kebenaran itu, akulah yang menggodanya untuk menundukkan dirinya kepada kemauanku, dan sesungguhnya dia termasuk orang-orang yang benar.\") di dalam pengakuannya, sewaktu ia mengatakan dialah yang menggodaku untuk menundukkan diriku kepada kemauannya. Setelah itu sang raja memberitahukan pengakuan itu kepada Nabi Yusuf dan setelah mendengar hal tersebut, lalu Nabi Yusuf berkata:",[["قَالَ","Dia berkata"],["مَا","Apa"],["خَطْبُكُنَّ","(adalah) urusan kamu"],["إِذْ","apabila"],["رَٰوَدتُّنَّ","kamu cuba memikat"],["يُوسُفَ","Yusuf"],["عَن","daripada"],["نَّفْسِهِۦ ۚ","dirinya sendiri"],["قُلْنَ","Mereka berkata"],["حَـٰشَ","Allah melarang"],["لِلَّهِ","Allah melarang"],["مَا","Tidak"],["عَلِمْنَا","kita tahu"],["عَلَيْهِ","tentang dia"],["مِن","sebarang"],["سُوٓءٍۢ ۚ","jahat"],["قَالَتِ","Berkata"],["ٱمْرَأَتُ","(si) isteri"],["ٱلْعَزِيزِ","(daripada) Aziz"],["ٱلْـَٔـٰنَ","Sekarang"],["حَصْحَصَ","(adalah) nyata"],["ٱلْحَقُّ","kebenaran"],["أَنَا۠","aku"],["رَٰوَدتُّهُۥ","berusaha untuk menggodanya"],["عَن","daripada"],["نَّفْسِهِۦ","dirinya sendiri"],["وَإِنَّهُۥ","dan sesungguhnya, dia"],["لَمِنَ","(adalah) pasti daripada"],["ٱلصَّـٰدِقِينَ","yang benar"]]],"1648":["(\"Yang demikian itu) yang diisyaratkan adalah permintaan bersih diri (agar dia mengetahui) yang dimaksud adalah Al-Aziz (bahwa sesungguhnya aku tidak berkhianat kepadanya) terhadap istrinya (di belakangnya) lafal bil-gaib berkedudukan sebagai hal atau kata keterangan keadaan (dan bahwasanya Allah tidak meridai tipu daya orang-orang yang berkhianat.\") kemudian Nabi Yusuf bertawadhu` atau merendahkan diri terhadap Allah seraya mengatakan:",[["ذَٰلِكَ","Itu"],["لِيَعْلَمَ","dia mungkin tahu"],["أَنِّى","bahawa aku"],["لَمْ","tidak"],["أَخُنْهُ","[Aku] mengkhianatinya"],["بِٱلْغَيْبِ","secara rahsia"],["وَأَنَّ","dan bahawa"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يَهْدِى","panduan"],["كَيْدَ","(the) rancangan"],["ٱلْخَآئِنِينَ","(dari) orang-orang yang berkhianat"]]]});